insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','gl',1,1,'Paulo, apóstolo (não da parte dos homens, nem por homem algum, mas por Jesus Cristo, e por Deus Pai, que o ressuscitou dentre os mortos),'),
('acf','gl',1,2,'E todos os irmãos que estão comigo, às igrejas da Galácia:'),
('acf','gl',1,3,'Graça e paz da parte de Deus Pai e do nosso Senhor Jesus Cristo,'),
('acf','gl',1,4,'O qual se deu a si mesmo por nossos pecados, para nos livrar do presente século mau, segundo a vontade de Deus nosso Pai,'),
('acf','gl',1,5,'Ao qual seja dada glória para todo o sempre. Amém.'),
('acf','gl',1,6,'Maravilho-me de que tão depressa passásseis daquele que vos chamou à graça de Cristo para outro evangelho;'),
('acf','gl',1,7,'O qual não é outro, mas há alguns que vos inquietam e querem transtornar o evangelho de Cristo.'),
('acf','gl',1,8,'Mas, ainda que nós mesmos ou um anjo do céu vos anuncie outro evangelho além do que já vos tenho anunciado, seja anátema.'),
('acf','gl',1,9,'Assim, como já vo-lo dissemos, agora de novo também vo-lo digo. Se alguém vos anunciar outro evangelho além do que já recebestes, seja anátema.'),
('acf','gl',1,10,'Porque, persuado eu agora a homens ou a Deus? ou procuro agradar a homens? Se estivesse ainda agradando aos homens, não seria servo de Cristo.'),
('acf','gl',1,11,'Mas faço-vos saber, irmãos, que o evangelho que por mim foi anunciado não é segundo os homens.'),
('acf','gl',1,12,'Porque não o recebi, nem aprendi de homem algum, mas pela revelação de Jesus Cristo.'),
('acf','gl',1,13,'Porque já ouvistes qual foi antigamente a minha conduta no judaísmo, como sobremaneira perseguia a igreja de Deus e a assolava.'),
('acf','gl',1,14,'E na minha nação excedia em judaísmo a muitos da minha idade, sendo extremamente zeloso das tradições de meus pais.'),
('acf','gl',1,15,'Mas, quando aprouve a Deus, que desde o ventre de minha mãe me separou, e me chamou pela sua graça,'),
('acf','gl',1,16,'Revelar seu Filho em mim, para que o pregasse entre os gentios, não consultei a carne nem o sangue,'),
('acf','gl',1,17,'Nem tornei a Jerusalém, a ter com os que já antes de mim eram apóstolos, mas parti para a Arábia, e voltei outra vez a Damasco.'),
('acf','gl',1,18,'Depois, passados três anos, fui a Jerusalém para ver a Pedro, e fiquei com ele quinze dias.'),
('acf','gl',1,19,'E não vi a nenhum outro dos apóstolos, senão a Tiago, irmão do Senhor.'),
('acf','gl',1,20,'Ora, acerca do que vos escrevo, eis que diante de Deus testifico que não minto.'),
('acf','gl',1,21,'Depois fui para as partes da Síria e da Cilícia.'),
('acf','gl',1,22,'E não era conhecido de vista das igrejas da Judéia, que estavam em Cristo;'),
('acf','gl',1,23,'Mas somente tinham ouvido dizer: Aquele que já nos perseguiu anuncia agora a fé que antes destruía.'),
('acf','gl',1,24,'E glorificavam a Deus a respeito de mim.'),
('acf','gl',2,1,'Depois, passados catorze anos, subi outra vez a Jerusalém com Barnabé, levando também comigo Tito.'),
('acf','gl',2,2,'E subi por uma revelação, e lhes expus o evangelho, que prego entre os gentios, e particularmente aos que estavam em estima; para que de maneira alguma não corresse ou não tivesse corrido em vão.'),
('acf','gl',2,3,'Mas nem ainda Tito, que estava comigo, sendo grego, foi constrangido a circuncidar-se;'),
('acf','gl',2,4,'E isto por causa dos falsos irmãos que se intrometeram, e secretamente entraram a espiar a nossa liberdade, que temos em Cristo Jesus, para nos porem em servidão;'),
('acf','gl',2,5,'Aos quais nem ainda por uma hora cedemos com sujeição, para que a verdade do evangelho permanecesse entre vós.'),
('acf','gl',2,6,'E, quanto àqueles que pareciam ser alguma coisa (quais tenham sido noutro tempo, não se me dá; Deus não aceita a aparência do homem), esses, digo, que pareciam ser alguma coisa, nada me comunicaram;'),
('acf','gl',2,7,'Antes, pelo contrário, quando viram que o evangelho da incircuncisão me estava confiado, como a Pedro o da circuncisão'),
('acf','gl',2,8,'(Porque aquele que operou eficazmente em Pedro para o apostolado da circuncisão, esse operou também em mim com eficácia para com os gentios),'),
('acf','gl',2,9,'E conhecendo Tiago, Cefas e João, que eram considerados como as colunas, a graça que me havia sido dada, deram-nos as destras, em comunhão comigo e com Barnabé, para que nós fôssemos aos gentios, e eles à circuncisão;'),
('acf','gl',2,10,'Recomendando-nos somente que nos lembrássemos dos pobres, o que também procurei fazer com diligência.'),
('acf','gl',2,11,'E, chegando Pedro à Antioquia, lhe resisti na cara, porque era repreensível.'),
('acf','gl',2,12,'Porque, antes que alguns tivessem chegado da parte de Tiago, comia com os gentios; mas, depois que chegaram, se foi retirando, e se apartou deles, temendo os que eram da circuncisão.'),
('acf','gl',2,13,'E os outros judeus também dissimulavam com ele, de maneira que até Barnabé se deixou levar pela sua dissimulação.'),
('acf','gl',2,14,'Mas, quando vi que não andavam bem e direitamente conforme a verdade do evangelho, disse a Pedro na presença de todos: Se tu, sendo judeu, vives como os gentios, e não como judeu, por que obrigas os gentios a viverem como judeus?'),
('acf','gl',2,15,'Nós somos judeus por natureza, e não pecadores dentre os gentios.'),
('acf','gl',2,16,'Sabendo que o homem não é justificado pelas obras da lei, mas pela fé em Jesus Cristo, temos também crido em Jesus Cristo, para sermos justificados pela fé em Cristo, e não pelas obras da lei; porquanto pelas obras da lei nenhuma carne será justificada.'),
('acf','gl',2,17,'Pois, se nós, que procuramos ser justificados em Cristo, nós mesmos também somos achados pecadores, é porventura Cristo ministro do pecado? De maneira nenhuma.'),
('acf','gl',2,18,'Porque, se torno a edificar aquilo que destruí, constituo-me a mim mesmo transgressor.'),
('acf','gl',2,19,'Porque eu, pela lei, estou morto para a lei, para viver para Deus.'),
('acf','gl',2,20,'Já estou crucificado com Cristo; e vivo, não mais eu, mas Cristo vive em mim; e a vida que agora vivo na carne, vivo-a pela fé do Filho de Deus, o qual me amou, e se entregou a si mesmo por mim.'),
('acf','gl',2,21,'Não aniquilo a graça de Deus; porque, se a justiça provém da lei, segue-se que Cristo morreu debalde.'),
('acf','gl',3,1,'Ó insensatos gálatas! quem vos fascinou para não obedecerdes à verdade, a vós, perante os olhos de quem Jesus Cristo foi evidenciado, crucificado, entre vós?'),
('acf','gl',3,2,'Só quisera saber isto de vós: recebestes o Espírito pelas obras da lei ou pela pregação da fé?'),
('acf','gl',3,3,'Sois vós tão insensatos que, tendo começado pelo Espírito, acabeis agora pela carne?'),
('acf','gl',3,4,'Será em vão que tenhais padecido tanto? Se é que isso também foi em vão.'),
('acf','gl',3,5,'Aquele, pois, que vos dá o Espírito, e que opera maravilhas entre vós, o faz pelas obras da lei, ou pela pregação da fé?'),
('acf','gl',3,6,'Assim como Abraão creu em Deus, e isso lhe foi imputado como justiça.'),
('acf','gl',3,7,'Sabei, pois, que os que são da fé são filhos de Abraão.'),
('acf','gl',3,8,'Ora, tendo a Escritura previsto que Deus havia de justificar pela fé os gentios, anunciou primeiro o evangelho a Abraão, dizendo: Todas as nações serão benditas em ti.'),
('acf','gl',3,9,'De sorte que os que são da fé são benditos com o crente Abraão.'),
('acf','gl',3,10,'Todos aqueles, pois, que são das obras da lei estão debaixo da maldição; porque está escrito: Maldito todo aquele que não permanecer em todas as coisas que estão escritas no livro da lei, para fazê-las.'),
('acf','gl',3,11,'E é evidente que pela lei ninguém será justificado diante de Deus, porque o justo viverá pela fé.'),
('acf','gl',3,12,'Ora, a lei não é da fé; mas o homem, que fizer estas coisas, por elas viverá.'),
('acf','gl',3,13,'Cristo nos resgatou da maldição da lei, fazendo-se maldição por nós; porque está escrito: Maldito todo aquele que for pendurado no madeiro;'),
('acf','gl',3,14,'Para que a bênção de Abraão chegasse aos gentios por Jesus Cristo, e para que pela fé nós recebamos a promessa do Espírito.'),
('acf','gl',3,15,'Irmãos, como homem falo; se a aliança de um homem for confirmada, ninguém a anula nem a acrescenta.'),
('acf','gl',3,16,'Ora, as promessas foram feitas a Abraão e à sua descendência. Não diz: E às descendências, como falando de muitas, mas como de uma só: E à tua descendência, que é Cristo.'),
('acf','gl',3,17,'Mas digo isto: Que tendo sido a aliança anteriormente confirmada por Deus em Cristo, a lei, que veio quatrocentos e trinta anos depois, não a invalida, de forma a abolir a promessa.'),
('acf','gl',3,18,'Porque, se a herança provém da lei, já não provém da promessa; mas Deus pela promessa a deu gratuitamente a Abraão.'),
('acf','gl',3,19,'Logo, para que é a lei? Foi ordenada por causa das transgressões, até que viesse a posteridade a quem a promessa tinha sido feita; e foi posta pelos anjos na mão de um medianeiro.'),
('acf','gl',3,20,'Ora, o medianeiro não o é de um só, mas Deus é um.'),
('acf','gl',3,21,'Logo, a lei é contra as promessas de Deus? De nenhuma sorte; porque, se fosse dada uma lei que pudesse vivificar, a justiça, na verdade, teria sido pela lei.'),
('acf','gl',3,22,'Mas a Escritura encerrou tudo debaixo do pecado, para que a promessa pela fé em Jesus Cristo fosse dada aos crentes.'),
('acf','gl',3,23,'Mas, antes que a fé viesse, estávamos guardados debaixo da lei, e encerrados para aquela fé que se havia de manifestar.'),
('acf','gl',3,24,'De maneira que a lei nos serviu de aio, para nos conduzir a Cristo, para que pela fé fôssemos justificados.'),
('acf','gl',3,25,'Mas, depois que veio a fé, já não estamos debaixo de aio.'),
('acf','gl',3,26,'Porque todos sois filhos de Deus pela fé em Cristo Jesus.'),
('acf','gl',3,27,'Porque todos quantos fostes batizados em Cristo já vos revestistes de Cristo.'),
('acf','gl',3,28,'Nisto não há judeu nem grego; não há servo nem livre; não há macho nem fêmea; porque todos vós sois um em Cristo Jesus.'),
('acf','gl',3,29,'E, se sois de Cristo, então sois descendência de Abraão, e herdeiros conforme a promessa.'),
('acf','gl',4,1,'Digo, pois, que todo o tempo que o herdeiro é menino em nada difere do servo, ainda que seja senhor de tudo;'),
('acf','gl',4,2,'Mas está debaixo de tutores e curadores até ao tempo determinado pelo pai.'),
('acf','gl',4,3,'Assim também nós, quando éramos meninos, estávamos reduzidos à servidão debaixo dos primeiros rudimentos do mundo.'),
('acf','gl',4,4,'Mas, vindo a plenitude dos tempos, Deus enviou seu Filho, nascido de mulher, nascido sob a lei,'),
('acf','gl',4,5,'Para remir os que estavam debaixo da lei, a fim de recebermos a adoção de filhos.'),
('acf','gl',4,6,'E, porque sois filhos, Deus enviou aos vossos corações o Espírito de seu Filho, que clama: Aba, Pai.'),
('acf','gl',4,7,'Assim que já não és mais servo, mas filho; e, se és filho, és também herdeiro de Deus por Cristo.'),
('acf','gl',4,8,'Mas, quando não conhecíeis a Deus, servíeis aos que por natureza não são deuses.'),
('acf','gl',4,9,'Mas agora, conhecendo a Deus, ou, antes, sendo conhecidos por Deus, como tornais outra vez a esses rudimentos fracos e pobres, aos quais de novo quereis servir?'),
('acf','gl',4,10,'Guardais dias, e meses, e tempos, e anos.'),
('acf','gl',4,11,'Receio de vós, que não haja trabalhado em vão para convosco.'),
('acf','gl',4,12,'Irmãos, rogo-vos que sejais como eu, porque também eu sou como vós; nenhum mal me fizestes.'),
('acf','gl',4,13,'E vós sabeis que primeiro vos anunciei o evangelho estando em fraqueza da carne;'),
('acf','gl',4,14,'E não rejeitastes, nem desprezastes isso que era uma tentação na minha carne, antes me recebestes como um anjo de Deus, como Jesus Cristo mesmo.'),
('acf','gl',4,15,'Qual é, logo, a vossa bem-aventurança? Porque vos dou testemunho de que, se possível fora, arrancaríeis os vossos olhos, e mos daríeis.'),
('acf','gl',4,16,'Fiz-me acaso vosso inimigo, dizendo a verdade?'),
('acf','gl',4,17,'Eles têm zelo por vós, não como convém; mas querem excluir-vos, para que vós tenhais zelo por eles.'),
('acf','gl',4,18,'É bom ser zeloso, mas sempre do bem, e não somente quando estou presente convosco.'),
('acf','gl',4,19,'Meus filhinhos, por quem de novo sinto as dores de parto, até que Cristo seja formado em vós;'),
('acf','gl',4,20,'Eu bem quisera agora estar presente convosco, e mudar a minha voz; porque estou perplexo a vosso respeito.'),
('acf','gl',4,21,'Dizei-me, os que quereis estar debaixo da lei, não ouvis vós a lei?'),
('acf','gl',4,22,'Porque está escrito que Abraão teve dois filhos, um da escrava, e outro da livre.'),
('acf','gl',4,23,'Todavia, o que era da escrava nasceu segundo a carne, mas, o que era da livre, por promessa.'),
('acf','gl',4,24,'O que se entende por alegoria; porque estas são as duas alianças; uma, do monte Sinai, gerando filhos para a servidão, que é Agar.'),
('acf','gl',4,25,'Ora, esta Agar é Sinai, um monte da Arábia, que corresponde à Jerusalém que agora existe, pois é escrava com seus filhos.'),
('acf','gl',4,26,'Mas a Jerusalém que é de cima é livre; a qual é mãe de todos nós.'),
('acf','gl',4,27,'Porque está escrito: Alegra-te, estéril, que não dás à luz; Esforça-te e clama, tu que não estás de parto; Porque os filhos da solitária são mais do que os da que tem marido.'),
('acf','gl',4,28,'Mas nós, irmãos, somos filhos da promessa como Isaque.'),
('acf','gl',4,29,'Mas, como então aquele que era gerado segundo a carne perseguia o que o era segundo o Espírito, assim é também agora.'),
('acf','gl',4,30,'Mas que diz a Escritura? Lança fora a escrava e seu filho, porque de modo algum o filho da escrava herdará com o filho da livre.'),
('acf','gl',4,31,'De maneira que, irmãos, somos filhos, não da escrava, mas da livre.'),
('acf','gl',5,1,'Estai, pois, firmes na liberdade com que Cristo nos libertou, e não torneis a colocar-vos debaixo do jugo da servidão.'),
('acf','gl',5,2,'Eis que eu, Paulo, vos digo que, se vos deixardes circuncidar, Cristo de nada vos aproveitará.'),
('acf','gl',5,3,'E de novo protesto a todo o homem, que se deixa circuncidar, que está obrigado a guardar toda a lei.'),
('acf','gl',5,4,'Separados estais de Cristo, vós os que vos justificais pela lei; da graça tendes caído.'),
('acf','gl',5,5,'Porque nós pelo Espírito da fé aguardamos a esperança da justiça.'),
('acf','gl',5,6,'Porque em Jesus Cristo nem a circuncisão nem a incircuncisão tem valor algum; mas sim a fé que opera pelo amor.'),
('acf','gl',5,7,'Corríeis bem; quem vos impediu, para que não obedeçais à verdade?'),
('acf','gl',5,8,'Esta persuasão não vem daquele que vos chamou.'),
('acf','gl',5,9,'Um pouco de fermento leveda toda a massa.'),
('acf','gl',5,10,'Confio de vós, no Senhor, que nenhuma outra coisa sentireis; mas aquele que vos inquieta, seja ele quem for, sofrerá a condenação.'),
('acf','gl',5,11,'Eu, porém, irmãos, se prego ainda a circuncisão, por que sou, pois, perseguido? Logo o escândalo da cruz está aniquilado.'),
('acf','gl',5,12,'Eu quereria que fossem cortados aqueles que vos andam inquietando.'),
('acf','gl',5,13,'Porque vós, irmãos, fostes chamados à liberdade. Não useis então da liberdade para dar ocasião à carne, mas servi-vos uns aos outros pelo amor.'),
('acf','gl',5,14,'Porque toda a lei se cumpre numa só palavra, nesta: Amarás ao teu próximo como a ti mesmo.'),
('acf','gl',5,15,'Se vós, porém, vos mordeis e devorais uns aos outros, vede não vos consumais também uns aos outros.'),
('acf','gl',5,16,'Digo, porém: Andai em Espírito, e não cumprireis a concupiscência da carne.'),
('acf','gl',5,17,'Porque a carne cobiça contra o Espírito, e o Espírito contra a carne; e estes opõem-se um ao outro, para que não façais o que quereis.'),
('acf','gl',5,18,'Mas, se sois guiados pelo Espírito, não estais debaixo da lei.'),
('acf','gl',5,19,'Porque as obras da carne são manifestas, as quais são: adultério, fornicação, impureza, lascívia,'),
('acf','gl',5,20,'Idolatria, feitiçaria, inimizades, porfias, emulações, iras, pelejas, dissensões, heresias,'),
('acf','gl',5,21,'Invejas, homicídios, bebedices, glutonarias, e coisas semelhantes a estas, acerca das quais vos declaro, como já antes vos disse, que os que cometem tais coisas não herdarão o reino de Deus.'),
('acf','gl',5,22,'Mas o fruto do Espírito é: amor, gozo, paz, longanimidade, benignidade, bondade, fé, mansidão, temperança.'),
('acf','gl',5,23,'Contra estas coisas não há lei.'),
('acf','gl',5,24,'E os que são de Cristo crucificaram a carne com as suas paixões e concupiscências.'),
('acf','gl',5,25,'Se vivemos em Espírito, andemos também em Espírito.'),
('acf','gl',5,26,'Não sejamos cobiçosos de vanglórias, irritando-nos uns aos outros, invejando-nos uns aos outros.'),
('acf','gl',6,1,'Irmãos, se algum homem chegar a ser surpreendido nalguma ofensa, vós, que sois espirituais, encaminhai o tal com espírito de mansidão; olhando por ti mesmo, para que não sejas também tentado.'),
('acf','gl',6,2,'Levai as cargas uns dos outros, e assim cumprireis a lei de Cristo.'),
('acf','gl',6,3,'Porque, se alguém cuida ser alguma coisa, não sendo nada, engana-se a si mesmo.'),
('acf','gl',6,4,'Mas prove cada um a sua própria obra, e terá glória só em si mesmo, e não noutro.'),
('acf','gl',6,5,'Porque cada qual levará a sua própria carga.'),
('acf','gl',6,6,'E o que é instruído na palavra reparta de todos os seus bens com aquele que o instrui.'),
('acf','gl',6,7,'Não erreis: Deus não se deixa escarnecer; porque tudo o que o homem semear, isso também ceifará.'),
('acf','gl',6,8,'Porque o que semeia na sua carne, da carne ceifará a corrupção; mas o que semeia no Espírito, do Espírito ceifará a vida eterna.'),
('acf','gl',6,9,'E não nos cansemos de fazer bem, porque a seu tempo ceifaremos, se não houvermos desfalecido.'),
('acf','gl',6,10,'Então, enquanto temos tempo, façamos bem a todos, mas principalmente aos domésticos da fé.'),
('acf','gl',6,11,'Vede com que grandes letras vos escrevi por minha mão.'),
('acf','gl',6,12,'Todos os que querem mostrar boa aparência na carne, esses vos obrigam a circuncidar-vos, somente para não serem perseguidos por causa da cruz de Cristo.'),
('acf','gl',6,13,'Porque nem ainda esses mesmos que se circuncidam guardam a lei, mas querem que vos circuncideis, para se gloriarem na vossa carne.'),
('acf','gl',6,14,'Mas longe esteja de mim gloriar-me, a não ser na cruz de nosso Senhor Jesus Cristo, pela qual o mundo está crucificado para mim e eu para o mundo.'),
('acf','gl',6,15,'Porque em Cristo Jesus nem a circuncisão, nem a incircuncisão tem virtude alguma, mas sim o ser uma nova criatura.'),
('acf','gl',6,16,'E a todos quantos andarem conforme esta regra, paz e misericórdia sobre eles e sobre o Israel de Deus.'),
('acf','gl',6,17,'Desde agora ninguém me inquiete; porque trago no meu corpo as marcas do Senhor Jesus.'),
('acf','gl',6,18,'A graça de nosso Senhor Jesus Cristo seja, irmãos, com o vosso espírito! Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ef',1,1,'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, aos santos que estão em Éfeso, e fiéis em Cristo Jesus:'),
('acf','ef',1,2,'A vós graça, e paz da parte de Deus nosso Pai e do Senhor Jesus Cristo!'),
('acf','ef',1,3,'Bendito o Deus e Pai de nosso Senhor Jesus Cristo, o qual nos abençoou com todas as bênçãos espirituais nos lugares celestiais em Cristo;'),
('acf','ef',1,4,'Como também nos elegeu nele antes da fundação do mundo, para que fôssemos santos e irrepreensíveis diante dele em amor;'),
('acf','ef',1,5,'E nos predestinou para filhos de adoção por Jesus Cristo, para si mesmo, segundo o beneplácito de sua vontade,'),
('acf','ef',1,6,'Para louvor da glória de sua graça, pela qual nos fez agradáveis a si no Amado,'),
('acf','ef',1,7,'Em quem temos a redenção pelo seu sangue, a remissão das ofensas, segundo as riquezas da sua graça,'),
('acf','ef',1,8,'Que ele fez abundar para conosco em toda a sabedoria e prudência;'),
('acf','ef',1,9,'Descobrindo-nos o mistério da sua vontade, segundo o seu beneplácito, que propusera em si mesmo,'),
('acf','ef',1,10,'De tornar a congregar em Cristo todas as coisas, na dispensação da plenitude dos tempos, tanto as que estão nos céus como as que estão na terra;'),
('acf','ef',1,11,'Nele, digo, em quem também fomos feitos herança, havendo sido predestinados, conforme o propósito daquele que faz todas as coisas, segundo o conselho da sua vontade;'),
('acf','ef',1,12,'Com o fim de sermos para louvor da sua glória, nós os que primeiro esperamos em Cristo;'),
('acf','ef',1,13,'Em quem também vós estais, depois que ouvistes a palavra da verdade, o evangelho da vossa salvação; e, tendo nele também crido, fostes selados com o Espírito Santo da promessa;'),
('acf','ef',1,14,'O qual é o penhor da nossa herança, para redenção da possessão adquirida, para louvor da sua glória.'),
('acf','ef',1,15,'Por isso, ouvindo eu também a fé que entre vós há no Senhor Jesus, e o vosso amor para com todos os santos,'),
('acf','ef',1,16,'Não cesso de dar graças a Deus por vós, lembrando-me de vós nas minhas orações:'),
('acf','ef',1,17,'Para que o Deus de nosso Senhor Jesus Cristo, o Pai da glória, vos dê em seu conhecimento o espírito de sabedoria e de revelação;'),
('acf','ef',1,18,'Tendo iluminados os olhos do vosso entendimento, para que saibais qual seja a esperança da sua vocação, e quais as riquezas da glória da sua herança nos santos;'),
('acf','ef',1,19,'E qual a sobreexcelente grandeza do seu poder sobre nós, os que cremos, segundo a operação da força do seu poder,'),
('acf','ef',1,20,'Que manifestou em Cristo, ressuscitando-o dentre os mortos, e pondo-o à sua direita nos céus,'),
('acf','ef',1,21,'Acima de todo o principado, e poder, e potestade, e domínio, e de todo o nome que se nomeia, não só neste século, mas também no vindouro;'),
('acf','ef',1,22,'E sujeitou todas as coisas a seus pés, e sobre todas as coisas o constituiu como cabeça da igreja,'),
('acf','ef',1,23,'Que é o seu corpo, a plenitude daquele que cumpre tudo em todos.'),
('acf','ef',2,1,'E vos vivificou, estando vós mortos em ofensas e pecados,'),
('acf','ef',2,2,'Em que noutro tempo andastes segundo o curso deste mundo, segundo o príncipe das potestades do ar, do espírito que agora opera nos filhos da desobediência;'),
('acf','ef',2,3,'Entre os quais todos nós também antes andávamos nos desejos da nossa carne, fazendo a vontade da carne e dos pensamentos; e éramos por natureza filhos da ira, como os outros também.'),
('acf','ef',2,4,'Mas Deus, que é riquíssimo em misericórdia, pelo seu muito amor com que nos amou,'),
('acf','ef',2,5,'Estando nós ainda mortos em nossas ofensas, nos vivificou juntamente com Cristo (pela graça sois salvos),'),
('acf','ef',2,6,'E nos ressuscitou juntamente com ele e nos fez assentar nos lugares celestiais, em Cristo Jesus;'),
('acf','ef',2,7,'Para mostrar nos séculos vindouros as abundantes riquezas da sua graça pela sua benignidade para conosco em Cristo Jesus.'),
('acf','ef',2,8,'Porque pela graça sois salvos, por meio da fé; e isto não vem de vós, é dom de Deus.'),
('acf','ef',2,9,'Não vem das obras, para que ninguém se glorie;'),
('acf','ef',2,10,'Porque somos feitura sua, criados em Cristo Jesus para as boas obras, as quais Deus preparou para que andássemos nelas.'),
('acf','ef',2,11,'Portanto, lembrai-vos de que vós noutro tempo éreis gentios na carne, e chamados incircuncisão pelos que na carne se chamam circuncisão feita pela mão dos homens;'),
('acf','ef',2,12,'Que naquele tempo estáveis sem Cristo, separados da comunidade de Israel, e estranhos às alianças da promessa, não tendo esperança, e sem Deus no mundo.'),
('acf','ef',2,13,'Mas agora em Cristo Jesus, vós, que antes estáveis longe, já pelo sangue de Cristo chegastes perto.'),
('acf','ef',2,14,'Porque ele é a nossa paz, o qual de ambos os povos fez um; e, derrubando a parede de separação que estava no meio,'),
('acf','ef',2,15,'Na sua carne desfez a inimizade, isto é, a lei dos mandamentos, que consistia em ordenanças, para criar em si mesmo dos dois um novo homem, fazendo a paz,'),
('acf','ef',2,16,'E pela cruz reconciliar ambos com Deus em um corpo, matando com ela as inimizades.'),
('acf','ef',2,17,'E, vindo, ele evangelizou a paz, a vós que estáveis longe, e aos que estavam perto;'),
('acf','ef',2,18,'Porque por ele ambos temos acesso ao Pai em um mesmo Espírito.'),
('acf','ef',2,19,'Assim que já não sois estrangeiros, nem forasteiros, mas concidadãos dos santos, e da família de Deus;'),
('acf','ef',2,20,'Edificados sobre o fundamento dos apóstolos e dos profetas, de que Jesus Cristo é a principal pedra da esquina;'),
('acf','ef',2,21,'No qual todo o edifício, bem ajustado, cresce para templo santo no Senhor.'),
('acf','ef',2,22,'No qual também vós juntamente sois edificados para morada de Deus em Espírito.'),
('acf','ef',3,1,'Por esta causa eu, Paulo, sou o prisioneiro de Jesus Cristo por vós, os gentios;'),
('acf','ef',3,2,'Se é que tendes ouvido a dispensação da graça de Deus, que para convosco me foi dada;'),
('acf','ef',3,3,'Como me foi este mistério manifestado pela revelação, como antes um pouco vos escrevi;'),
('acf','ef',3,4,'Por isso, quando ledes, podeis perceber a minha compreensão do mistério de Cristo,'),
('acf','ef',3,5,'O qual noutros séculos não foi manifestado aos filhos dos homens, como agora tem sido revelado pelo Espírito aos seus santos apóstolos e profetas;'),
('acf','ef',3,6,'A saber, que os gentios são co-herdeiros, e de um mesmo corpo, e participantes da promessa em Cristo pelo evangelho;'),
('acf','ef',3,7,'Do qual fui feito ministro, pelo dom da graça de Deus, que me foi dado segundo a operação do seu poder.'),
('acf','ef',3,8,'A mim, o mínimo de todos os santos, me foi dada esta graça de anunciar entre os gentios, por meio do evangelho, as riquezas incompreensíveis de Cristo,'),
('acf','ef',3,9,'E demonstrar a todos qual seja a comunhão do mistério, que desde os séculos esteve oculto em Deus, que tudo criou por meio de Jesus Cristo;'),
('acf','ef',3,10,'Para que agora, pela igreja, a multiforme sabedoria de Deus seja conhecida dos principados e potestades nos céus,'),
('acf','ef',3,11,'Segundo o eterno propósito que fez em Cristo Jesus nosso Senhor,'),
('acf','ef',3,12,'No qual temos ousadia e acesso com confiança, pela nossa fé nele.'),
('acf','ef',3,13,'Portanto, vos peço que não desfaleçais nas minhas tribulações por vós, que são a vossa glória.'),
('acf','ef',3,14,'Por causa disto me ponho de joelhos perante o Pai de nosso Senhor Jesus Cristo,'),
('acf','ef',3,15,'Do qual toda a família nos céus e na terra toma o nome,'),
('acf','ef',3,16,'Para que, segundo as riquezas da sua glória, vos conceda que sejais corroborados com poder pelo seu Espírito no homem interior;'),
('acf','ef',3,17,'Para que Cristo habite pela fé nos vossos corações; a fim de, estando arraigados e fundados em amor,'),
('acf','ef',3,18,'Poderdes perfeitamente compreender, com todos os santos, qual seja a largura, e o comprimento, e a altura, e a profundidade,'),
('acf','ef',3,19,'E conhecer o amor de Cristo, que excede todo o entendimento, para que sejais cheios de toda a plenitude de Deus.'),
('acf','ef',3,20,'Ora, àquele que é poderoso para fazer tudo muito mais abundantemente além daquilo que pedimos ou pensamos, segundo o poder que em nós opera,'),
('acf','ef',3,21,'A esse glória na igreja, por Jesus Cristo, em todas as gerações, para todo o sempre. Amém.'),
('acf','ef',4,1,'Rogo-vos, pois, eu, o preso do Senhor, que andeis como é digno da vocação com que fostes chamados,'),
('acf','ef',4,2,'Com toda a humildade e mansidão, com longanimidade, suportando-vos uns aos outros em amor,'),
('acf','ef',4,3,'Procurando guardar a unidade do Espírito pelo vínculo da paz.'),
('acf','ef',4,4,'Há um só corpo e um só Espírito, como também fostes chamados em uma só esperança da vossa vocação;'),
('acf','ef',4,5,'Um só Senhor, uma só fé, um só batismo;'),
('acf','ef',4,6,'Um só Deus e Pai de todos, o qual é sobre todos, e por todos e em todos vós.'),
('acf','ef',4,7,'Mas a graça foi dada a cada um de nós segundo a medida do dom de Cristo.'),
('acf','ef',4,8,'Por isso diz:Subindo ao alto, levou cativo o cativeiro,e deu dons aos homens.'),
('acf','ef',4,9,'Ora, istoele subiuque é, senão que também antes tinha descido às partes mais baixas da terra?'),
('acf','ef',4,10,'Aquele que desceu é também o mesmo que subiu acima de todos os céus, para cumprir todas as coisas.'),
('acf','ef',4,11,'E ele mesmo deu uns para apóstolos, e outros para profetas, e outros para evangelistas, e outros para pastores e doutores,'),
('acf','ef',4,12,'Querendo o aperfeiçoamento dos santos, para a obra do ministério, para edificação do corpo de Cristo;'),
('acf','ef',4,13,'Até que todos cheguemos à unidade da fé, e ao conhecimento do Filho de Deus, a homem perfeito, à medida da estatura completa de Cristo,'),
('acf','ef',4,14,'Para que não sejamos mais meninos inconstantes, levados em roda por todo o vento de doutrina, pelo engano dos homens que com astúcia enganam fraudulosamente.'),
('acf','ef',4,15,'Antes, seguindo a verdade em amor, cresçamos em tudo naquele que é a cabeça, Cristo,'),
('acf','ef',4,16,'Do qual todo o corpo, bem ajustado, e ligado pelo auxílio de todas as juntas, segundo a justa operação de cada parte, faz o aumento do corpo, para sua edificação em amor.'),
('acf','ef',4,17,'E digo isto, e testifico no Senhor, para que não andeis mais como andam também os outros gentios, na vaidade da sua mente.'),
('acf','ef',4,18,'Entenebrecidos no entendimento, separados da vida de Deus pela ignorância que há neles, pela dureza do seu coração;'),
('acf','ef',4,19,'Os quais, havendo perdido todo o sentimento, se entregaram à dissolução, para com avidez cometerem toda a impureza.'),
('acf','ef',4,20,'Mas vós não aprendestes assim a Cristo,'),
('acf','ef',4,21,'Se é que o tendes ouvido, e nele fostes ensinados, como está a verdade em Jesus;'),
('acf','ef',4,22,'Que, quanto ao trato passado, vos despojeis do velho homem, que se corrompe pelas concupiscências do engano;'),
('acf','ef',4,23,'E vos renoveis no espírito da vossa mente;'),
('acf','ef',4,24,'E vos revistais do novo homem, que segundo Deus é criado em verdadeira justiça e santidade.'),
('acf','ef',4,25,'Por isso deixai a mentira, e falai a verdade cada um com o seu próximo; porque somos membros uns dos outros.'),
('acf','ef',4,26,'Irai-vos, e não pequeis; não se ponha o sol sobre a vossa ira.'),
('acf','ef',4,27,'Não deis lugar ao diabo.'),
('acf','ef',4,28,'Aquele que furtava, não furte mais; antes trabalhe, fazendo com as mãos o que é bom, para que tenha o que repartir com o que tiver necessidade.'),
('acf','ef',4,29,'Não saia da vossa boca nenhuma palavra torpe, mas só a que for boa para promover a edificação, para que dê graça aos que a ouvem.'),
('acf','ef',4,30,'E não entristeçais o Espírito Santo de Deus, no qual estais selados para o dia da redenção.'),
('acf','ef',4,31,'Toda a amargura, e ira, e cólera, e gritaria, e blasfêmia e toda a malícia sejam tiradas dentre vós,'),
('acf','ef',4,32,'Antes sede uns para com os outros benignos, misericordiosos, perdoando-vos uns aos outros, como também Deus vos perdoou em Cristo.'),
('acf','ef',5,1,'Sede, pois, imitadores de Deus, como filhos amados;'),
('acf','ef',5,2,'E andai em amor, como também Cristo vos amou, e se entregou a si mesmo por nós, em oferta e sacrifício a Deus, em cheiro suave.'),
('acf','ef',5,3,'Mas a fornicação, e toda a impureza ou avareza, nem ainda se nomeie entre vós, como convém a santos;'),
('acf','ef',5,4,'Nem torpezas, nem parvoíces, nem chocarrices, que não convêm; mas antes, ações de graças.'),
('acf','ef',5,5,'Porque bem sabeis isto: que nenhum devasso, ou impuro, ou avarento, o qual é idólatra, tem herança no reino de Cristo e de Deus.'),
('acf','ef',5,6,'Ninguém vos engane com palavras vãs; porque por estas coisas vem a ira de Deus sobre os filhos da desobediência.'),
('acf','ef',5,7,'Portanto, não sejais seus companheiros.'),
('acf','ef',5,8,'Porque noutro tempo éreis trevas, mas agora sois luz no Senhor; andai como filhos da luz'),
('acf','ef',5,9,'(Porque o fruto do Espírito está em toda a bondade, e justiça e verdade);'),
('acf','ef',5,10,'Aprovando o que é agradável ao Senhor.'),
('acf','ef',5,11,'E não comuniqueis com as obras infrutuosas das trevas, mas antes condenai-as.'),
('acf','ef',5,12,'Porque o que eles fazem em oculto até dizê-lo é torpe.'),
('acf','ef',5,13,'Mas todas estas coisas se manifestam, sendo condenadas pela luz, porque a luz tudo manifesta.'),
('acf','ef',5,14,'Por isso diz: Desperta, tu que dormes, e levanta-te dentre os mortos, e Cristo te esclarecerá.'),
('acf','ef',5,15,'Portanto, vede prudentemente como andais, não como néscios, mas como sábios,'),
('acf','ef',5,16,'Remindo o tempo; porquanto os dias são maus.'),
('acf','ef',5,17,'Por isso não sejais insensatos, mas entendei qual seja a vontade do Senhor.'),
('acf','ef',5,18,'E não vos embriagueis com vinho, em que há contenda, mas enchei-vos do Espírito;'),
('acf','ef',5,19,'Falando entre vós em salmos, e hinos, e cânticos espirituais; cantando e salmodiando ao Senhor no vosso coração;'),
('acf','ef',5,20,'Dando sempre graças por tudo a nosso Deus e Pai, em nome de nosso Senhor Jesus Cristo;'),
('acf','ef',5,21,'Sujeitando-vos uns aos outros no temor de Deus.'),
('acf','ef',5,22,'Vós, mulheres, sujeitai-vos a vossos maridos, como ao Senhor;'),
('acf','ef',5,23,'Porque o marido é a cabeça da mulher, como também Cristo é a cabeça da igreja, sendo ele próprio o salvador do corpo.'),
('acf','ef',5,24,'De sorte que, assim como a igreja está sujeita a Cristo, assim também as mulheres sejam em tudo sujeitas a seus maridos.'),
('acf','ef',5,25,'Vós, maridos, amai vossas mulheres, como também Cristo amou a igreja, e a si mesmo se entregou por ela,'),
('acf','ef',5,26,'Para a santificar, purificando-a com a lavagem da água, pela palavra,'),
('acf','ef',5,27,'Para a apresentar a si mesmo igreja gloriosa, sem mácula, nem ruga, nem coisa semelhante, mas santa e irrepreensível.'),
('acf','ef',5,28,'Assim devem os maridos amar as suas próprias mulheres, como a seus próprios corpos. Quem ama a sua mulher, ama-se a si mesmo.'),
('acf','ef',5,29,'Porque nunca ninguém odiou a sua própria carne; antes a alimenta e sustenta, como também o Senhor à igreja;'),
('acf','ef',5,30,'Porque somos membros do seu corpo, da sua carne, e dos seus ossos.'),
('acf','ef',5,31,'Por isso deixará o homem seu pai e sua mãe, e se unirá a sua mulher; e serão dois numa carne.'),
('acf','ef',5,32,'Grande é este mistério; digo-o, porém, a respeito de Cristo e da igreja.'),
('acf','ef',5,33,'Assim também vós, cada um em particular, ame a sua própria mulher como a si mesmo, e a mulher reverencie o marido.'),
('acf','ef',6,1,'Vós, filhos, sede obedientes a vossos pais no Senhor, porque isto é justo.'),
('acf','ef',6,2,'Honra a teu pai e a tua mãe, que é o primeiro mandamento com promessa;'),
('acf','ef',6,3,'Para que te vá bem, e vivas muito tempo sobre a terra.'),
('acf','ef',6,4,'E vós, pais, não provoqueis à ira a vossos filhos, mas criai-os na doutrina e admoestação do Senhor.'),
('acf','ef',6,5,'Vós, servos, obedecei a vossos senhores segundo a carne, com temor e tremor, na sinceridade de vosso coração, como a Cristo;'),
('acf','ef',6,6,'Não servindo à vista, como para agradar aos homens, mas como servos de Cristo, fazendo de coração a vontade de Deus;'),
('acf','ef',6,7,'Servindo de boa vontade como ao Senhor, e não como aos homens.'),
('acf','ef',6,8,'Sabendo que cada um receberá do Senhor todo o bem que fizer, seja servo, seja livre.'),
('acf','ef',6,9,'E vós, senhores, fazei o mesmo para com eles, deixando as ameaças, sabendo também que o Senhor deles e vosso está no céu, e que para com ele não há acepção de pessoas.'),
('acf','ef',6,10,'No demais, irmãos meus, fortalecei-vos no Senhor e na força do seu poder.'),
('acf','ef',6,11,'Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as astutas ciladas do diabo.'),
('acf','ef',6,12,'Porque não temos que lutar contra a carne e o sangue, mas, sim, contra os principados, contra as potestades, contra os príncipes das trevas deste século, contra as hostes espirituais da maldade, nos lugares celestiais.'),
('acf','ef',6,13,'Portanto, tomai toda a armadura de Deus, para que possais resistir no dia mau e, havendo feito tudo, ficar firmes.'),
('acf','ef',6,14,'Estai, pois, firmes, tendo cingidos os vossos lombos com a verdade, e vestida a couraça da justiça;'),
('acf','ef',6,15,'E calçados os pés na preparação do evangelho da paz;'),
('acf','ef',6,16,'Tomando sobretudo o escudo da fé, com o qual podereis apagar todos os dardos inflamados do maligno.'),
('acf','ef',6,17,'Tomai também o capacete da salvação, e a espada do Espírito, que é a palavra de Deus;'),
('acf','ef',6,18,'Orando em todo o tempo com toda a oração e súplica no Espírito, e vigiando nisto com toda a perseverança e súplica por todos os santos,'),
('acf','ef',6,19,'E por mim; para que me seja dada, no abrir da minha boca, a palavra com confiança, para fazer notório o mistério do evangelho,'),
('acf','ef',6,20,'Pelo qual sou embaixador em cadeias; para que possa falar dele livremente, como me convém falar.'),
('acf','ef',6,21,'Ora, para que vós também possais saber dos meus negócios, e o que eu faço, Tíquico, irmão amado, e fiel ministro do Senhor, vos informará de tudo.'),
('acf','ef',6,22,'O qual vos enviei para o mesmo fim, para que saibais do nosso estado, e ele console os vossos corações.'),
('acf','ef',6,23,'Paz seja com os irmãos, e amor com fé da parte de Deus Pai e da do Senhor Jesus Cristo.'),
('acf','ef',6,24,'A graça seja com todos os que amam a nosso Senhor Jesus Cristo em sinceridade. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','fp',1,1,'Paulo e Timóteo, servos de Jesus Cristo, a todos os santos em Cristo Jesus, que estão em Filipos, com os bispos e diáconos:'),
('acf','fp',1,2,'Graça a vós, e paz da parte de Deus nosso Pai e da do Senhor Jesus Cristo.'),
('acf','fp',1,3,'Dou graças ao meu Deus todas as vezes que me lembro de vós,'),
('acf','fp',1,4,'Fazendo sempre com alegria oração por vós em todas as minhas súplicas,'),
('acf','fp',1,5,'Pela vossa cooperação no evangelho desde o primeiro dia até agora.'),
('acf','fp',1,6,'Tendo por certo isto mesmo, que aquele que em vós começou a boa obra a aperfeiçoará até ao dia de Jesus Cristo;'),
('acf','fp',1,7,'Como tenho por justo sentir isto de vós todos, porque vos retenho em meu coração, pois todos vós fostes participantes da minha graça, tanto nas minhas prisões como na minha defesa e confirmação do evangelho.'),
('acf','fp',1,8,'Porque Deus me é testemunha das saudades que de todos vós tenho, em entranhável afeição de Jesus Cristo.'),
('acf','fp',1,9,'E peço isto: que o vosso amor cresça mais e mais em ciência e em todo o conhecimento,'),
('acf','fp',1,10,'Para que aproveis as coisas excelentes, para que sejais sinceros, e sem escândalo algum até ao dia de Cristo;'),
('acf','fp',1,11,'Cheios dos frutos de justiça, que são por Jesus Cristo, para glória e louvor de Deus.'),
('acf','fp',1,12,'E quero, irmãos, que saibais que as coisas que me aconteceram contribuíram para maior proveito do evangelho;'),
('acf','fp',1,13,'De maneira que as minhas prisões em Cristo foram manifestas por toda a guarda pretoriana, e por todos os demais lugares;'),
('acf','fp',1,14,'E muitos dos irmãos no Senhor, tomando ânimo com as minhas prisões, ousam falar a palavra mais confiadamente, sem temor.'),
('acf','fp',1,15,'Verdade é que também alguns pregam a Cristo por inveja e porfia, mas outros de boa vontade;'),
('acf','fp',1,16,'Uns, na verdade, anunciam a Cristo por contenção, não puramente, julgando acrescentar aflição às minhas prisões.'),
('acf','fp',1,17,'Mas outros, por amor, sabendo que fui posto para defesa do evangelho.'),
('acf','fp',1,18,'Mas que importa? Contanto que Cristo seja anunciado de toda a maneira, ou com fingimento ou em verdade, nisto me regozijo, e me regozijarei ainda.'),
('acf','fp',1,19,'Porque sei que disto me resultará salvação, pela vossa oração e pelo socorro do Espírito de Jesus Cristo,'),
('acf','fp',1,20,'Segundo a minha intensa expectação e esperança, de que em nada serei confundido; antes, com toda a confiança, Cristo será, tanto agora como sempre, engrandecido no meu corpo, seja pela vida, seja pela morte.'),
('acf','fp',1,21,'Porque para mim o viver é Cristo, e o morrer é ganho.'),
('acf','fp',1,22,'Mas, se o viver na carne me der fruto da minha obra, não sei então o que deva escolher.'),
('acf','fp',1,23,'Mas de ambos os lados estou em aperto, tendo desejo de partir, e estar com Cristo, porque isto é ainda muito melhor.'),
('acf','fp',1,24,'Mas julgo mais necessário, por amor de vós, ficar na carne.'),
('acf','fp',1,25,'E, tendo esta confiança, sei que ficarei, e permanecerei com todos vós para proveito vosso e gozo da fé,'),
('acf','fp',1,26,'Para que a vossa glória cresça por mim em Cristo Jesus, pela minha nova ida a vós.'),
('acf','fp',1,27,'Somente deveis portar-vos dignamente conforme o evangelho de Cristo, para que, quer vá e vos veja, quer esteja ausente, ouça acerca de vós que estais num mesmo espírito, combatendo juntamente com o mesmo ânimo pela fé do evangelho.'),
('acf','fp',1,28,'E em nada vos espanteis dos que resistem, o que para eles, na verdade, é indício de perdição, mas para vós de salvação, e isto de Deus.'),
('acf','fp',1,29,'Porque a vós vos foi concedido, em relação a Cristo, não somente crer nele, como também padecer por ele,'),
('acf','fp',1,30,'Tendo o mesmo combate que já em mim tendes visto e agora ouvis estar em mim.'),
('acf','fp',2,1,'Portanto, se há algum conforto em Cristo, se alguma consolação de amor, se alguma comunhão no Espírito, se alguns entranháveis afetos e compaixões,'),
('acf','fp',2,2,'Completai o meu gozo, para que sintais o mesmo, tendo o mesmo amor, o mesmo ânimo, sentindo uma mesma coisa.'),
('acf','fp',2,3,'Nada façais por contenda ou por vanglória, mas por humildade; cada um considere os outros superiores a si mesmo.'),
('acf','fp',2,4,'Não atente cada um para o que é propriamente seu, mas cada qual também para o que é dos outros.'),
('acf','fp',2,5,'De sorte que haja em vós o mesmo sentimento que houve também em Cristo Jesus,'),
('acf','fp',2,6,'Que, sendo em forma de Deus, não teve por usurpação ser igual a Deus,'),
('acf','fp',2,7,'Mas esvaziou-se a si mesmo, tomando a forma de servo, fazendo-se semelhante aos homens;'),
('acf','fp',2,8,'E, achado na forma de homem, humilhou-se a si mesmo, sendo obediente até à morte, e morte de cruz.'),
('acf','fp',2,9,'Por isso, também Deus o exaltou soberanamente, e lhe deu um nome que é sobre todo o nome;'),
('acf','fp',2,10,'Para que ao nome de Jesus se dobre todo o joelho dos que estão nos céus, e na terra, e debaixo da terra,'),
('acf','fp',2,11,'E toda a língua confesse que Jesus Cristo é o Senhor, para glória de Deus Pai.'),
('acf','fp',2,12,'De sorte que, meus amados, assim como sempre obedecestes, não só na minha presença, mas muito mais agora na minha ausência, assim também operai a vossa salvação com temor e tremor;'),
('acf','fp',2,13,'Porque Deus é o que opera em vós tanto o querer como o efetuar, segundo a sua boa vontade.'),
('acf','fp',2,14,'Fazei todas as coisas sem murmurações nem contendas;'),
('acf','fp',2,15,'Para que sejais irrepreensíveis e sinceros, filhos de Deus inculpáveis, no meio de uma geração corrompida e perversa, entre a qual resplandeceis como astros no mundo;'),
('acf','fp',2,16,'Retendo a palavra da vida, para que no dia de Cristo possa gloriar-me de não ter corrido nem trabalhado em vão.'),
('acf','fp',2,17,'E, ainda que seja oferecido por libação sobre o sacrifício e serviço da vossa fé, folgo e me regozijo com todos vós.'),
('acf','fp',2,18,'E vós também regozijai-vos e alegrai-vos comigo por isto mesmo.'),
('acf','fp',2,19,'E espero no Senhor Jesus que em breve vos mandarei Timóteo, para que também eu esteja de bom ânimo, sabendo dos vossos negócios.'),
('acf','fp',2,20,'Porque a ninguém tenho de igual sentimento, que sinceramente cuide do vosso estado;'),
('acf','fp',2,21,'Porque todos buscam o que é seu, e não o que é de Cristo Jesus.'),
('acf','fp',2,22,'Mas bem sabeis qual a sua experiência, e que serviu comigo no evangelho, como filho ao pai.'),
('acf','fp',2,23,'De sorte que espero vo-lo enviar logo que tenha provido a meus negócios.'),
('acf','fp',2,24,'Mas confio no Senhor, que também eu mesmo em breve irei ter convosco.'),
('acf','fp',2,25,'Julguei, contudo, necessário mandar-vos Epafrodito, meu irmão e cooperador, e companheiro nos combates, e vosso enviado para prover às minhas necessidades.'),
('acf','fp',2,26,'Porquanto tinha muitas saudades de vós todos, e estava muito angustiado de que tivésseis ouvido que ele estivera doente.'),
('acf','fp',2,27,'E de fato esteve doente, e quase à morte; mas Deus se apiedou dele, e não somente dele, mas também de mim, para que eu não tivesse tristeza sobre tristeza.'),
('acf','fp',2,28,'Por isso vo-lo enviei mais depressa, para que, vendo-o outra vez, vos regozijeis, e eu tenha menos tristeza.'),
('acf','fp',2,29,'Recebei-o, pois, no Senhor com todo o gozo, e tende-o em honra;'),
('acf','fp',2,30,'Porque pela obra de Cristo chegou até bem próximo da morte, não fazendo caso da vida para suprir para comigo a falta do vosso serviço.'),
('acf','fp',3,1,'Resta, irmãos meus, que vos regozijeis no Senhor. Não me aborreço de escrever-vos as mesmas coisas, e é segurança para vós.'),
('acf','fp',3,2,'Guardai-vos dos cães, guardai-vos dos maus obreiros, guardai-vos da circuncisão;'),
('acf','fp',3,3,'Porque a circuncisão somos nós, que servimos a Deus em espírito, e nos gloriamos em Jesus Cristo, e não confiamos na carne.'),
('acf','fp',3,4,'Ainda que também podia confiar na carne; se algum outro cuida que pode confiar na carne, ainda mais eu:'),
('acf','fp',3,5,'Circuncidado ao oitavo dia, da linhagem de Israel, da tribo de Benjamim, hebreu de hebreus; segundo a lei, fui fariseu;'),
('acf','fp',3,6,'Segundo o zelo, perseguidor da igreja, segundo a justiça que há na lei, irrepreensível.'),
('acf','fp',3,7,'Mas o que para mim era ganho reputei-o perda por Cristo.'),
('acf','fp',3,8,'E, na verdade, tenho também por perda todas as coisas, pela excelência do conhecimento de Cristo Jesus, meu Senhor; pelo qual sofri a perda de todas estas coisas, e as considero como escória, para que possa ganhar a Cristo,'),
('acf','fp',3,9,'E seja achado nele, não tendo a minha justiça que vem da lei, mas a que vem pela fé em Cristo, a saber, a justiça que vem de Deus pela fé;'),
('acf','fp',3,10,'Para conhecê-lo, e à virtude da sua ressurreição, e à comunicação de suas aflições, sendo feito conforme à sua morte;'),
('acf','fp',3,11,'Para ver se de alguma maneira posso chegar à ressurreição dentre os mortos.'),
('acf','fp',3,12,'Não que já a tenha alcançado, ou que seja perfeito; mas prossigo para alcançar aquilo para o que fui também preso por Cristo Jesus.'),
('acf','fp',3,13,'Irmãos, quanto a mim, não julgo que o haja alcançado; mas uma coisa faço, e é que, esquecendo-me das coisas que atrás ficam, e avançando para as que estão diante de mim,'),
('acf','fp',3,14,'Prossigo para o alvo, pelo prêmio da soberana vocação de Deus em Cristo Jesus.'),
('acf','fp',3,15,'Por isso todos quantos já somos perfeitos, sintamos isto mesmo; e, se sentis alguma coisa de outra maneira, também Deus vo-lo revelará.'),
('acf','fp',3,16,'Mas, naquilo a que já chegamos, andemos segundo a mesma regra, e sintamos o mesmo.'),
('acf','fp',3,17,'Sede também meus imitadores, irmãos, e tende cuidado, segundo o exemplo que tendes em nós, pelos que assim andam.'),
('acf','fp',3,18,'Porque muitos há, dos quais muitas vezes vos disse, e agora também digo, chorando, que são inimigos da cruz de Cristo,'),
('acf','fp',3,19,'Cujo fim é a perdição; cujo Deus é o ventre, e cuja glória é para confusão deles, que só pensam nas coisas terrenas.'),
('acf','fp',3,20,'Mas a nossa cidade está nos céus, de onde também esperamos o Salvador, o Senhor Jesus Cristo,'),
('acf','fp',3,21,'Que transformará o nosso corpo abatido, para ser conforme o seu corpo glorioso, segundo o seu eficaz poder de sujeitar também a si todas as coisas.'),
('acf','fp',4,1,'Portanto, meus amados e mui queridos irmãos, minha alegria e coroa, estai assim firmes no Senhor, amados.'),
('acf','fp',4,2,'Rogo a Evódia, e rogo a Síntique, que sintam o mesmo no Senhor.'),
('acf','fp',4,3,'E peço-te também a ti, meu verdadeiro companheiro, que ajudes essas mulheres que trabalharam comigo no evangelho, e com Clemente, e com os meus outros cooperadores, cujos nomes estão no livro da vida.'),
('acf','fp',4,4,'Regozijai-vos sempre no Senhor; outra vez digo, regozijai-vos.'),
('acf','fp',4,5,'Seja a vossa eqüidade notória a todos os homens. Perto está o Senhor.'),
('acf','fp',4,6,'Não estejais inquietos por coisa alguma; antes as vossas petições sejam em tudo conhecidas diante de Deus pela oração e súplica, com ação de graças.'),
('acf','fp',4,7,'E a paz de Deus, que excede todo o entendimento, guardará os vossos corações e os vossos pensamentos em Cristo Jesus.'),
('acf','fp',4,8,'Quanto ao mais, irmãos, tudo o que é verdadeiro, tudo o que é honesto, tudo o que é justo, tudo o que é puro, tudo o que é amável, tudo o que é de boa fama, se há alguma virtude, e se há algum louvor, nisso pensai.'),
('acf','fp',4,9,'O que também aprendestes, e recebestes, e ouvistes, e vistes em mim, isso fazei; e o Deus de paz será convosco.'),
('acf','fp',4,10,'Ora, muito me regozijei no Senhor por finalmente reviver a vossa lembrança de mim; pois já vos tínheis lembrado, mas não tínheis tido oportunidade.'),
('acf','fp',4,11,'Não digo isto como por necessidade, porque já aprendi a contentar-me com o que tenho.'),
('acf','fp',4,12,'Sei estar abatido, e sei também ter abundância; em toda a maneira, e em todas as coisas estou instruído, tanto a ter fartura, como a ter fome; tanto a ter abundância, como a padecer necessidade.'),
('acf','fp',4,13,'Posso todas as coisas em Cristo que me fortalece.'),
('acf','fp',4,14,'Todavia fizestes bem em tomar parte na minha aflição.'),
('acf','fp',4,15,'E bem sabeis também, ó filipenses, que, no princípio do evangelho, quando parti da macedônia, nenhuma igreja comunicou comigo com respeito a dar e a receber, senão vós somente;'),
('acf','fp',4,16,'Porque também uma e outra vez me mandastes o necessário a tessalônica.'),
('acf','fp',4,17,'Não que procure dádivas, mas procuro o fruto que cresça para a vossa conta.'),
('acf','fp',4,18,'Mas bastante tenho recebido, e tenho abundância. Cheio estou, depois que recebi de Epafrodito o que da vossa parte me foi enviado, como cheiro de suavidade e sacrifício agradável e aprazível a Deus.'),
('acf','fp',4,19,'O meu Deus, segundo as suas riquezas, suprirá todas as vossas necessidades em glória, por Cristo Jesus.'),
('acf','fp',4,20,'Ora, a nosso Deus e Pai seja dada glória para todo o sempre. Amém.'),
('acf','fp',4,21,'Saudai a todos os santos em Cristo Jesus. Os irmãos que estão comigo vos saúdam.'),
('acf','fp',4,22,'Todos os santos vos saúdam, mas principalmente os que são da casa de César.'),
('acf','fp',4,23,'A graça de nosso Senhor Jesus Cristo seja com vós todos. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','cl',1,1,'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, e o irmão Timóteo,'),
('acf','cl',1,2,'Aos santos e irmãos fiéis em Cristo, que estão em Colossos: Graça a vós, e paz da parte de Deus nosso Pai e do Senhor Jesus Cristo.'),
('acf','cl',1,3,'Graças damos a Deus, Pai de nosso Senhor Jesus Cristo, orando sempre por vós,'),
('acf','cl',1,4,'Porquanto ouvimos da vossa fé em Cristo Jesus, e do amor que tendes para com todos os santos;'),
('acf','cl',1,5,'Por causa da esperança que vos está reservada nos céus, da qual já antes ouvistes pela palavra da verdade do evangelho,'),
('acf','cl',1,6,'Que já chegou a vós, como também está em todo o mundo; e já vai frutificando, como também entre vós, desde o dia em que ouvistes e conhecestes a graça de Deus em verdade;'),
('acf','cl',1,7,'Como aprendestes de Epafras, nosso amado conservo, que para vós é um fiel ministro de Cristo,'),
('acf','cl',1,8,'O qual nos declarou também o vosso amor no Espírito.'),
('acf','cl',1,9,'Por esta razão, nós também, desde o dia em que o ouvimos, não cessamos de orar por vós, e de pedir que sejais cheios do conhecimento da sua vontade, em toda a sabedoria e inteligência espiritual;'),
('acf','cl',1,10,'Para que possais andar dignamente diante do Senhor, agradando-lhe em tudo, frutificando em toda a boa obra, e crescendo no conhecimento de Deus;'),
('acf','cl',1,11,'Corroborados em toda a fortaleza, segundo a força da sua glória, em toda a paciência, e longanimidade com gozo;'),
('acf','cl',1,12,'Dando graças ao Pai que nos fez idôneos para participar da herança dos santos na luz;'),
('acf','cl',1,13,'O qual nos tirou da potestade das trevas, e nos transportou para o reino do Filho do seu amor;'),
('acf','cl',1,14,'Em quem temos a redenção pelo seu sangue, a saber, a remissão dos pecados;'),
('acf','cl',1,15,'O qual é imagem do Deus invisível, o primogênito de toda a criação;'),
('acf','cl',1,16,'Porque nele foram criadas todas as coisas que há nos céus e na terra, visíveis e invisíveis, sejam tronos, sejam dominações, sejam principados, sejam potestades. Tudo foi criado por ele e para ele.'),
('acf','cl',1,17,'E ele é antes de todas as coisas, e todas as coisas subsistem por ele.'),
('acf','cl',1,18,'E ele é a cabeça do corpo, da igreja; é o princípio e o primogênito dentre os mortos, para que em tudo tenha a preeminência.'),
('acf','cl',1,19,'Porque foi do agrado do Pai que toda a plenitude nele habitasse,'),
('acf','cl',1,20,'E que, havendo por ele feito a paz pelo sangue da sua cruz, por meio dele reconciliasse consigo mesmo todas as coisas, tanto as que estão na terra, como as que estão nos céus.'),
('acf','cl',1,21,'A vós também, que noutro tempo éreis estranhos, e inimigos no entendimento pelas vossas obras más, agora contudo vos reconciliou'),
('acf','cl',1,22,'No corpo da sua carne, pela morte, para perante ele vos apresentar santos, e irrepreensíveis, e inculpáveis,'),
('acf','cl',1,23,'Se, na verdade, permanecerdes fundados e firmes na fé, e não vos moverdes da esperança do evangelho que tendes ouvido, o qual foi pregado a toda criatura que há debaixo do céu, e do qual eu, Paulo, estou feito ministro.'),
('acf','cl',1,24,'Regozijo-me agora no que padeço por vós, e na minha carne cumpro o resto das aflições de Cristo, pelo seu corpo, que é a igreja;'),
('acf','cl',1,25,'Da qual eu estou feito ministro segundo a dispensação de Deus, que me foi concedida para convosco, para cumprir a palavra de Deus;'),
('acf','cl',1,26,'O mistério que esteve oculto desde todos os séculos, e em todas as gerações, e que agora foi manifesto aos seus santos;'),
('acf','cl',1,27,'Aos quais Deus quis fazer conhecer quais são as riquezas da glória deste mistério entre os gentios, que é Cristo em vós, esperança da glória;'),
('acf','cl',1,28,'A quem anunciamos, admoestando a todo o homem, e ensinando a todo o homem em toda a sabedoria; para que apresentemos todo o homem perfeito em Jesus Cristo;'),
('acf','cl',1,29,'E para isto também trabalho, combatendo segundo a sua eficácia, que opera em mim poderosamente.'),
('acf','cl',2,1,'Porque quero que saibais quão grande combate tenho por vós, e pelos que estão em Laodicéia, e por quantos não viram o meu rosto em carne;'),
('acf','cl',2,2,'Para que os seus corações sejam consolados, e estejam unidos em amor, e enriquecidos da plenitude da inteligência, para conhecimento do mistério de Deus e Pai, e de Cristo,'),
('acf','cl',2,3,'Em quem estão escondidos todos os tesouros da sabedoria e da ciência.'),
('acf','cl',2,4,'E digo isto, para que ninguém vos engane com palavras persuasivas.'),
('acf','cl',2,5,'Porque, ainda que esteja ausente quanto ao corpo, contudo, em espírito estou convosco, regozijando-me e vendo a vossa ordem e a firmeza da vossa fé em Cristo.'),
('acf','cl',2,6,'Como, pois, recebestes o Senhor Jesus Cristo, assim também andai nele,'),
('acf','cl',2,7,'Arraigados e sobreedificados nele, e confirmados na fé, assim como fostes ensinados, nela abundando em ação de graças.'),
('acf','cl',2,8,'Tende cuidado, para que ninguém vos faça presa sua, por meio de filosofias e vãs sutilezas, segundo a tradição dos homens, segundo os rudimentos do mundo, e não segundo Cristo;'),
('acf','cl',2,9,'Porque nele habita corporalmente toda a plenitude da divindade;'),
('acf','cl',2,10,'E estais perfeitos nele, que é a cabeça de todo o principado e potestade;'),
('acf','cl',2,11,'No qual também estais circuncidados com a circuncisão não feita por mão no despojo do corpo dos pecados da carne, pela circuncisão de Cristo;'),
('acf','cl',2,12,'Sepultados com ele no batismo, nele também ressuscitastes pela fé no poder de Deus, que o ressuscitou dentre os mortos.'),
('acf','cl',2,13,'E, quando vós estáveis mortos nos pecados, e na incircuncisão da vossa carne, vos vivificou juntamente com ele, perdoando-vos todas as ofensas,'),
('acf','cl',2,14,'Havendo riscado a cédula que era contra nós nas suas ordenanças, a qual de alguma maneira nos era contrária, e a tirou do meio de nós, cravando-a na cruz.'),
('acf','cl',2,15,'E, despojando os principados e potestades, os expôs publicamente e deles triunfou em si mesmo.'),
('acf','cl',2,16,'Portanto, ninguém vos julgue pelo comer, ou pelo beber, ou por causa dos dias de festa, ou da lua nova, ou dos sábados,'),
('acf','cl',2,17,'Que são sombras das coisas futuras, mas o corpo é de Cristo.'),
('acf','cl',2,18,'Ninguém vos domine a seu bel-prazer com pretexto de humildade e culto dos anjos, envolvendo-se em coisas que não viu; estando debalde inchado na sua carnal compreensão,'),
('acf','cl',2,19,'E não ligado à cabeça, da qual todo o corpo, provido e organizado pelas juntas e ligaduras, vai crescendo em aumento de Deus.'),
('acf','cl',2,20,'Se, pois, estais mortos com Cristo quanto aos rudimentos do mundo, por que vos carregam ainda de ordenanças, como se vivêsseis no mundo, tais como:'),
('acf','cl',2,21,'Não toques, não proves, não manuseies?'),
('acf','cl',2,22,'As quais coisas todas perecem pelo uso, segundo os preceitos e doutrinas dos homens;'),
('acf','cl',2,23,'As quais têm, na verdade, alguma aparência de sabedoria, em devoção voluntária, humildade, e em disciplina do corpo, mas não são de valor algum senão para a satisfação da carne.'),
('acf','cl',3,1,'Portanto, se já ressuscitastes com Cristo, buscai as coisas que são de cima, onde Cristo está assentado à destra de Deus.'),
('acf','cl',3,2,'Pensai nas coisas que são de cima, e não nas que são da terra;'),
('acf','cl',3,3,'Porque já estais mortos, e a vossa vida está escondida com Cristo em Deus.'),
('acf','cl',3,4,'Quando Cristo, que é a nossa vida, se manifestar, então também vós vos manifestareis com ele em glória.'),
('acf','cl',3,5,'Mortificai, pois, os vossos membros, que estão sobre a terra: a fornicação, a impureza, o afeição desordenada, a vil concupiscência, e a avareza, que é idolatria;'),
('acf','cl',3,6,'Pelas quais coisas vem a ira de Deus sobre os filhos da desobediência;'),
('acf','cl',3,7,'Nas quais, também, em outro tempo andastes, quando vivíeis nelas.'),
('acf','cl',3,8,'Mas agora, despojai-vos também de tudo: da ira, da cólera, da malícia, da maledicência, das palavras torpes da vossa boca.'),
('acf','cl',3,9,'Não mintais uns aos outros, pois que já vos despistes do velho homem com os seus feitos,'),
('acf','cl',3,10,'E vos vestistes do novo, que se renova para o conhecimento, segundo a imagem daquele que o criou;'),
('acf','cl',3,11,'Onde não há grego, nem judeu, circuncisão, nem incircuncisão, bárbaro, cita, servo ou livre; mas Cristo é tudo, e em todos.'),
('acf','cl',3,12,'Revesti-vos, pois, como eleitos de Deus, santos e amados, de entranhas de misericórdia, de benignidade, humildade, mansidão, longanimidade;'),
('acf','cl',3,13,'Suportando-vos uns aos outros, e perdoando-vos uns aos outros, se alguém tiver queixa contra outro; assim como Cristo vos perdoou, assim fazei vós também.'),
('acf','cl',3,14,'E, sobre tudo isto, revesti-vos de amor, que é o vínculo da perfeição.'),
('acf','cl',3,15,'E a paz de Deus, para a qual também fostes chamados em um corpo, domine em vossos corações; e sede agradecidos.'),
('acf','cl',3,16,'A palavra de Cristo habite em vós abundantemente, em toda a sabedoria, ensinando-vos e admoestando-vos uns aos outros, com salmos, hinos e cânticos espirituais, cantando ao Senhor com graça em vosso coração.'),
('acf','cl',3,17,'E, quanto fizerdes por palavras ou por obras, fazei tudo em nome do Senhor Jesus, dando por ele graças a Deus Pai.'),
('acf','cl',3,18,'Vós, mulheres, estai sujeitas a vossos próprios maridos, como convém no Senhor.'),
('acf','cl',3,19,'Vós, maridos, amai a vossas mulheres, e não vos irriteis contra elas.'),
('acf','cl',3,20,'Vós, filhos, obedecei em tudo a vossos pais, porque isto é agradável ao Senhor.'),
('acf','cl',3,21,'Vós, pais, não irriteis a vossos filhos, para que não percam o ânimo.'),
('acf','cl',3,22,'Vós, servos, obedecei em tudo a vossos senhores segundo a carne, não servindo só na aparência, como para agradar aos homens, mas em simplicidade de coração, temendo a Deus.'),
('acf','cl',3,23,'E tudo quanto fizerdes, fazei-o de todo o coração, como ao Senhor, e não aos homens,'),
('acf','cl',3,24,'Sabendo que recebereis do Senhor o galardão da herança, porque a Cristo, o Senhor, servis.'),
('acf','cl',3,25,'Mas quem fizer agravo receberá o agravo que fizer; pois não há acepção de pessoas.'),
('acf','cl',4,1,'Vós, senhores, fazei o que for de justiça e eqüidade a vossos servos, sabendo que também tendes um Senhor nos céus.'),
('acf','cl',4,2,'Perseverai em oração, velando nela com ação de graças;'),
('acf','cl',4,3,'Orando também juntamente por nós, para que Deus nos abra a porta da palavra, a fim de falarmos do mistério de Cristo, pelo qual estou também preso;'),
('acf','cl',4,4,'Para que o manifeste, como me convém falar.'),
('acf','cl',4,5,'Andai com sabedoria para com os que estão de fora, remindo o tempo.'),
('acf','cl',4,6,'A vossa palavra seja sempre agradável, temperada com sal, para que saibais como vos convém responder a cada um.'),
('acf','cl',4,7,'Tíquico, irmão amado e fiel ministro, e conservo no Senhor, vos fará saber o meu estado;'),
('acf','cl',4,8,'O qual vos enviei para o mesmo fim, para que saiba do vosso estado e console os vossos corações;'),
('acf','cl',4,9,'Juntamente com Onésimo, amado e fiel irmão, que é dos vossos; eles vos farão saber tudo o que por aqui se passa.'),
('acf','cl',4,10,'Aristarco, que está preso comigo, vos saúda, e Marcos, o sobrinho de Barnabé, acerca do qual já recebestes mandamentos; se ele for ter convosco, recebei-o;'),
('acf','cl',4,11,'E Jesus, chamado Justo; os quais são da circuncisão; são estes unicamente os meus cooperadores no reino de Deus; e para mim têm sido consolação.'),
('acf','cl',4,12,'Saúda-vos Epafras, que é dos vossos, servo de Cristo, combatendo sempre por vós em orações, para que vos conserveis firmes, perfeitos e consumados em toda a vontade de Deus.'),
('acf','cl',4,13,'Pois eu lhe dou testemunho de que tem grande zelo por vós, e pelos que estão em Laodicéia, e pelos que estão em Hierápolis.'),
('acf','cl',4,14,'Saúda-vos Lucas, o médico amado, e Demas.'),
('acf','cl',4,15,'Saudai aos irmãos que estão em Laodicéia e a Ninfa e à igreja que está em sua casa.'),
('acf','cl',4,16,'E, quando esta epístola tiver sido lida entre vós, fazei que também o seja na igreja dos laodicenses, e a que veio de Laodicéia lede-a vós também.'),
('acf','cl',4,17,'E dizei a Arquipo: Atenta para o ministério que recebeste no Senhor, para que o cumpras.'),
('acf','cl',4,18,'Saudação de minha mão, de Paulo. Lembrai-vos das minhas prisões. A graça seja convosco. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1ts',1,1,'Paulo, e Silvano, e Timóteo, à igreja dos tessalonicenses em Deus, o Pai, e no Senhor Jesus Cristo: Graça e paz tenhais de Deus nosso Pai e do Senhor Jesus Cristo.'),
('acf','1ts',1,2,'Sempre damos graças a Deus por vós todos, fazendo menção de vós em nossas orações,'),
('acf','1ts',1,3,'Lembrando-nos sem cessar da obra da vossa fé, do trabalho do amor, e da paciência da esperança em nosso Senhor Jesus Cristo, diante de nosso Deus e Pai,'),
('acf','1ts',1,4,'Sabendo, amados irmãos, que a vossa eleição é de Deus;'),
('acf','1ts',1,5,'Porque o nosso evangelho não foi a vós somente em palavras, mas também em poder, e no Espírito Santo, e em muita certeza, como bem sabeis quais fomos entre vós, por amor de vós.'),
('acf','1ts',1,6,'E vós fostes feitos nossos imitadores, e do Senhor, recebendo a palavra em muita tribulação, com gozo do Espírito Santo.'),
('acf','1ts',1,7,'De maneira que fostes exemplo para todos os fiéis na macedônia e Acaia.'),
('acf','1ts',1,8,'Porque por vós soou a palavra do Senhor, não somente na macedônia e Acaia, mas também em todos os lugares a vossa fé para com Deus se espalhou, de tal maneira que já dela não temos necessidade de falar coisa alguma;'),
('acf','1ts',1,9,'Porque eles mesmos anunciam de nós qual a entrada que tivemos para convosco, e como dos ídolos vos convertestes a Deus, para servir o Deus vivo e verdadeiro,'),
('acf','1ts',1,10,'E esperar dos céus o seu Filho, a quem ressuscitou dentre os mortos, a saber, Jesus, que nos livra da ira futura.'),
('acf','1ts',2,1,'Porque vós mesmos, irmãos, bem sabeis que a nossa entrada para convosco não foi vã;'),
('acf','1ts',2,2,'Mas, mesmo depois de termos antes padecido, e sido agravados em Filipos, como sabeis, tornamo-nos ousados em nosso Deus, para vos falar o evangelho de Deus com grande combate.'),
('acf','1ts',2,3,'Porque a nossa exortação não foi com engano, nem com imundícia, nem com fraudulência;'),
('acf','1ts',2,4,'Mas, como fomos aprovados de Deus para que o evangelho nos fosse confiado, assim falamos, não como para agradar aos homens, mas a Deus, que prova os nossos corações.'),
('acf','1ts',2,5,'Porque, como bem sabeis, nunca usamos de palavras lisonjeiras, nem houve um pretexto de avareza; Deus é testemunha;'),
('acf','1ts',2,6,'E não buscamos glória dos homens, nem de vós, nem de outros, ainda que podíamos, como apóstolos de Cristo, ser-vos pesados;'),
('acf','1ts',2,7,'Antes fomos brandos entre vós, como a ama que cria seus filhos.'),
('acf','1ts',2,8,'Assim nós, sendo-vos tão afeiçoados, de boa vontade quiséramos comunicar-vos, não somente o evangelho de Deus, mas ainda as nossas próprias almas; porquanto nos éreis muito queridos.'),
('acf','1ts',2,9,'Porque bem vos lembrais, irmãos, do nosso trabalho e fadiga; pois, trabalhando noite e dia, para não sermos pesados a nenhum de vós, vos pregamos o evangelho de Deus.'),
('acf','1ts',2,10,'Vós e Deus sois testemunhas de quão santa, e justa, e irrepreensivelmente nos houvemos para convosco, os que crestes.'),
('acf','1ts',2,11,'Assim como bem sabeis de que modo vos exortávamos e consolávamos e testemunhávamos, a cada um de vós, como o pai a seus filhos;'),
('acf','1ts',2,12,'Para que vos conduzísseis dignamente para com Deus, que vos chama para o seu reino e glória.'),
('acf','1ts',2,13,'Por isso também damos, sem cessar, graças a Deus, pois, havendo recebido de nós a palavra da pregação de Deus, a recebestes, não como palavra de homens, mas (segundo é, na verdade), como palavra de Deus, a qual também opera em vós, os que crestes.'),
('acf','1ts',2,14,'Porque vós, irmãos, haveis sido feitos imitadores das igrejas de Deus que na Judéia estão em Jesus Cristo; porquanto também padecestes de vossos próprios concidadãos o mesmo que os judeus lhes fizeram a eles,'),
('acf','1ts',2,15,'Os quais também mataram o Senhor Jesus e os seus próprios profetas, e nos têm perseguido; e não agradam a Deus, e são contrários a todos os homens,'),
('acf','1ts',2,16,'E nos impedem de pregar aos gentios as palavras da salvação, a fim de encherem sempre a medida de seus pecados; mas a ira de Deus caiu sobre eles até ao fim.'),
('acf','1ts',2,17,'Nós, porém, irmãos, sendo privados de vós por um momento de tempo, de vista, mas não do coração, tanto mais procuramos com grande desejo ver o vosso rosto;'),
('acf','1ts',2,18,'Por isso bem quisemos uma e outra vez ir ter convosco, pelo menos eu, Paulo, mas Satanás no-lo impediu.'),
('acf','1ts',2,19,'Porque, qual é a nossa esperança, ou gozo, ou coroa de glória? Porventura não o sois vós também diante de nosso Senhor Jesus Cristo em sua vinda?'),
('acf','1ts',2,20,'Na verdade vós sois a nossa glória e gozo.'),
('acf','1ts',3,1,'Por isso, não podendo esperar mais, achamos por bem ficar sozinhos em Atenas;'),
('acf','1ts',3,2,'E enviamos Timóteo, nosso irmão, e ministro de Deus, e nosso cooperador no evangelho de Cristo, para vos confortar e vos exortar acerca da vossa fé;'),
('acf','1ts',3,3,'Para que ninguém se comova por estas tribulações; porque vós mesmos sabeis que para isto fomos ordenados,'),
('acf','1ts',3,4,'Pois, estando ainda convosco, vos predizíamos que havíamos de ser afligidos, como sucedeu, e vós o sabeis.'),
('acf','1ts',3,5,'Portanto, não podendo eu também esperar mais, mandei-o saber da vossa fé, temendo que o tentador vos tentasse, e o nosso trabalho viesse a ser inútil.'),
('acf','1ts',3,6,'Vindo, porém, agora Timóteo de vós para nós, e trazendo-nos boas novas da vossa fé e amor, e de como sempre tendes boa lembrança de nós, desejando muito ver-nos, como nós também a vós;'),
('acf','1ts',3,7,'Por esta razão, irmãos, ficamos consolados acerca de vós, em toda a nossa aflição e necessidade, pela vossa fé,'),
('acf','1ts',3,8,'Porque agora vivemos, se estais firmes no Senhor.'),
('acf','1ts',3,9,'Porque, que ação de graças poderemos dar a Deus por vós, por todo o gozo com que nos regozijamos por vossa causa diante do nosso Deus,'),
('acf','1ts',3,10,'Orando abundantemente dia e noite, para que possamos ver o vosso rosto, e supramos o que falta à vossa fé?'),
('acf','1ts',3,11,'Ora, o mesmo nosso Deus e Pai, e nosso Senhor Jesus Cristo, encaminhem a nossa viagem para vós.'),
('acf','1ts',3,12,'E o Senhor vos aumente, e faça crescer em amor uns para com os outros, e para com todos, como também o fazemos para convosco;'),
('acf','1ts',3,13,'Para confirmar os vossos corações, para que sejais irrepreensíveis em santidade diante de nosso Deus e Pai, na vinda de nosso Senhor Jesus Cristo com todos os seus santos.'),
('acf','1ts',4,1,'Finalmente, irmãos, vos rogamos e exortamos no Senhor Jesus, que assim como recebestes de nós, de que maneira convém andar e agradar a Deus, assim andai, para que possais progredir cada vez mais.'),
('acf','1ts',4,2,'Porque vós bem sabeis que mandamentos vos temos dado pelo Senhor Jesus.'),
('acf','1ts',4,3,'Porque esta é a vontade de Deus, a vossa santificação; que vos abstenhais da fornicação;'),
('acf','1ts',4,4,'Que cada um de vós saiba possuir o seu vaso em santificação e honra;'),
('acf','1ts',4,5,'Não na paixão da concupiscência, como os gentios, que não conhecem a Deus.'),
('acf','1ts',4,6,'Ninguém oprima ou engane a seu irmão em negócio algum, porque o Senhor é vingador de todas estas coisas, como também antes vo-lo dissemos e testificamos.'),
('acf','1ts',4,7,'Porque não nos chamou Deus para a imundícia, mas para a santificação.'),
('acf','1ts',4,8,'Portanto, quem despreza isto não despreza ao homem, mas sim a Deus, que nos deu também o seu Espírito Santo.'),
('acf','1ts',4,9,'Quanto, porém, ao amor fraternal, não necessitais de que vos escreva, visto que vós mesmos estais instruídos por Deus que vos ameis uns aos outros;'),
('acf','1ts',4,10,'Porque também já assim o fazeis para com todos os irmãos que estão por toda a macedônia. Exortamo-vos, porém, a que ainda nisto aumenteis cada vez mais.'),
('acf','1ts',4,11,'E procureis viver quietos, e tratar dos vossos próprios negócios, e trabalhar com vossas próprias mãos, como já vo-lo temos mandado;'),
('acf','1ts',4,12,'Para que andeis honestamente para com os que estão de fora, e não necessiteis de coisa alguma.'),
('acf','1ts',4,13,'Não quero, porém, irmãos, que sejais ignorantes acerca dos que já dormem, para que não vos entristeçais, como os demais, que não têm esperança.'),
('acf','1ts',4,14,'Porque, se cremos que Jesus morreu e ressuscitou, assim também aos que em Jesus dormem, Deus os tornará a trazer com ele.'),
('acf','1ts',4,15,'Dizemo-vos, pois, isto, pela palavra do Senhor: que nós, os que ficarmos vivos para a vinda do Senhor, não precederemos os que dormem.'),
('acf','1ts',4,16,'Porque o mesmo Senhor descerá do céu com alarido, e com voz de arcanjo, e com a trombeta de Deus; e os que morreram em Cristo ressuscitarão primeiro.'),
('acf','1ts',4,17,'Depois nós, os que ficarmos vivos, seremos arrebatados juntamente com eles nas nuvens, a encontrar o Senhor nos ares, e assim estaremos sempre com o Senhor.'),
('acf','1ts',4,18,'Portanto, consolai-vos uns aos outros com estas palavras.'),
('acf','1ts',5,1,'Mas, irmãos, acerca dos tempos e das estações, não necessitais de que se vos escreva;'),
('acf','1ts',5,2,'Porque vós mesmos sabeis muito bem que o dia do Senhor virá como o ladrão de noite;'),
('acf','1ts',5,3,'Pois que, quando disserem: Há paz e segurança, então lhes sobrevirá repentina destruição, como as dores de parto àquela que está grávida, e de modo nenhum escaparão.'),
('acf','1ts',5,4,'Mas vós, irmãos, já não estais em trevas, para que aquele dia vos surpreenda como um ladrão;'),
('acf','1ts',5,5,'Porque todos vós sois filhos da luz e filhos do dia; nós não somos da noite nem das trevas.'),
('acf','1ts',5,6,'Não durmamos, pois, como os demais, mas vigiemos, e sejamos sóbrios;'),
('acf','1ts',5,7,'Porque os que dormem, dormem de noite, e os que se embebedam, embebedam-se de noite.'),
('acf','1ts',5,8,'Mas nós, que somos do dia, sejamos sóbrios, vestindo-nos da couraça da fé e do amor, e tendo por capacete a esperança da salvação;'),
('acf','1ts',5,9,'Porque Deus não nos destinou para a ira, mas para a aquisição da salvação, por nosso Senhor Jesus Cristo,'),
('acf','1ts',5,10,'Que morreu por nós, para que, quer vigiemos, quer durmamos, vivamos juntamente com ele.'),
('acf','1ts',5,11,'Por isso exortai-vos uns aos outros, e edificai-vos uns aos outros, como também o fazeis.'),
('acf','1ts',5,12,'E rogamo-vos, irmãos, que reconheçais os que trabalham entre vós e que presidem sobre vós no Senhor, e vos admoestam;'),
('acf','1ts',5,13,'E que os tenhais em grande estima e amor, por causa da sua obra. Tende paz entre vós.'),
('acf','1ts',5,14,'Rogamo-vos, também, irmãos, que admoesteis os desordeiros, consoleis os de pouco ânimo, sustenteis os fracos, e sejais pacientes para com todos.'),
('acf','1ts',5,15,'Vede que ninguém dê a outrem mal por mal, mas segui sempre o bem, tanto uns para com os outros, como para com todos.'),
('acf','1ts',5,16,'Regozijai-vos sempre.'),
('acf','1ts',5,17,'Orai sem cessar.'),
('acf','1ts',5,18,'Em tudo dai graças, porque esta é a vontade de Deus em Cristo Jesus para convosco.'),
('acf','1ts',5,19,'Não extingais o Espírito.'),
('acf','1ts',5,20,'Não desprezeis as profecias.'),
('acf','1ts',5,21,'Examinai tudo. Retende o bem.'),
('acf','1ts',5,22,'Abstende-vos de toda a aparência do mal.'),
('acf','1ts',5,23,'E o mesmo Deus de paz vos santifique em tudo; e todo o vosso espírito, e alma, e corpo, sejam plenamente conservados irrepreensíveis para a vinda de nosso Senhor Jesus Cristo.'),
('acf','1ts',5,24,'Fiel é o que vos chama, o qual também o fará.'),
('acf','1ts',5,25,'Irmãos, orai por nós.'),
('acf','1ts',5,26,'Saudai a todos os irmãos com ósculo santo.'),
('acf','1ts',5,27,'Pelo Senhor vos conjuro que esta epístola seja lida a todos os santos irmãos.'),
('acf','1ts',5,28,'A graça de nosso Senhor Jesus Cristo seja convosco. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2ts',1,1,'Paulo, e Silvano, e Timóteo, à igreja dos tessalonicenses, em Deus nosso Pai, e no Senhor Jesus Cristo:'),
('acf','2ts',1,2,'Graça e paz a vós da parte de Deus nosso Pai, e da do Senhor Jesus Cristo.'),
('acf','2ts',1,3,'Sempre devemos, irmãos, dar graças a Deus por vós, como é justo, porque a vossa fé cresce muitíssimo e o amor de cada um de vós aumenta de uns para com os outros,'),
('acf','2ts',1,4,'De maneira que nós mesmos nos gloriamos de vós nas igrejas de Deus por causa da vossa paciência e fé, e em todas as vossas perseguições e aflições que suportais;'),
('acf','2ts',1,5,'Prova clara do justo juízo de Deus, para que sejais havidos por dignos do reino de Deus, pelo qual também padeceis;'),
('acf','2ts',1,6,'Se de fato é justo diante de Deus que dê em paga tribulação aos que vos atribulam,'),
('acf','2ts',1,7,'E a vós, que sois atribulados, descanso conosco, quando se manifestar o Senhor Jesus desde o céu com os anjos do seu poder,'),
('acf','2ts',1,8,'Com labareda de fogo, tomando vingança dos que não conhecem a Deus e dos que não obedecem ao evangelho de nosso Senhor Jesus Cristo;'),
('acf','2ts',1,9,'Os quais, por castigo, padecerão eterna perdição, longe da face do Senhor e da glória do seu poder,'),
('acf','2ts',1,10,'Quando vier para ser glorificado nos seus santos, e para se fazer admirável naquele dia em todos os que crêem (porquanto o nosso testemunho foi crido entre vós).'),
('acf','2ts',1,11,'Por isso também rogamos sempre por vós, para que o nosso Deus vos faça dignos da sua vocação, e cumpra todo o desejo da sua bondade, e a obra da fé com poder;'),
('acf','2ts',1,12,'Para que o nome de nosso Senhor Jesus Cristo seja em vós glorificado, e vós nele, segundo a graça de nosso Deus e do Senhor Jesus Cristo.'),
('acf','2ts',2,1,'Ora, irmãos, rogamo-vos, pela vinda de nosso Senhor Jesus Cristo, e pela nossa reunião com ele,'),
('acf','2ts',2,2,'Que não vos movais facilmente do vosso entendimento, nem vos perturbeis, quer por espírito, quer por palavra, quer por epístola, como de nós, como se o dia de Cristo estivesse já perto.'),
('acf','2ts',2,3,'Ninguém de maneira alguma vos engane; porque não será assim sem que antes venha a apostasia, e se manifeste o homem do pecado, o filho da perdição,'),
('acf','2ts',2,4,'O qual se opõe, e se levanta contra tudo o que se chama Deus, ou se adora; de sorte que se assentará, como Deus, no templo de Deus, querendo parecer Deus.'),
('acf','2ts',2,5,'Não vos lembrais de que estas coisas vos dizia quando ainda estava convosco?'),
('acf','2ts',2,6,'E agora vós sabeis o que o detém, para que a seu próprio tempo seja manifestado.'),
('acf','2ts',2,7,'Porque já o mistério da injustiça opera; somente há um que agora o retém até que do meio seja tirado;'),
('acf','2ts',2,8,'E então será revelado o iníquo, a quem o Senhor desfará pelo assopro da sua boca, e aniquilará pelo esplendor da sua vinda;'),
('acf','2ts',2,9,'A esse cuja vinda é segundo a eficácia de Satanás, com todo o poder, e sinais e prodígios de mentira,'),
('acf','2ts',2,10,'E com todo o engano da injustiça para os que perecem, porque não receberam o amor da verdade para se salvarem.'),
('acf','2ts',2,11,'E por isso Deus lhes enviará a operação do erro, para que creiam a mentira;'),
('acf','2ts',2,12,'Para que sejam julgados todos os que não creram a verdade, antes tiveram prazer na iniqüidade.'),
('acf','2ts',2,13,'Mas devemos sempre dar graças a Deus por vós, irmãos amados do Senhor, por vos ter Deus elegido desde o princípio para a salvação, em santificação do Espírito, e fé da verdade;'),
('acf','2ts',2,14,'Para o que pelo nosso evangelho vos chamou, para alcançardes a glória de nosso Senhor Jesus Cristo.'),
('acf','2ts',2,15,'Então, irmãos, estai firmes e retende as tradições que vos foram ensinadas, seja por palavra, seja por epístola nossa.'),
('acf','2ts',2,16,'E o próprio nosso Senhor Jesus Cristo e nosso Deus e Pai, que nos amou, e em graça nos deu uma eterna consolação e boa esperança,'),
('acf','2ts',2,17,'Console os vossos corações, e vos confirme em toda a boa palavra e obra.'),
('acf','2ts',3,1,'No demais, irmãos, rogai por nós, para que a palavra do Senhor tenha livre curso e seja glorificada, como também o é entre vós;'),
('acf','2ts',3,2,'E para que sejamos livres de homens dissolutos e maus; porque a fé não é de todos.'),
('acf','2ts',3,3,'Mas fiel é o Senhor, que vos confirmará, e guardará do maligno.'),
('acf','2ts',3,4,'E confiamos quanto a vós no Senhor, que não só fazeis como fareis o que vos mandamos.'),
('acf','2ts',3,5,'Ora o Senhor encaminhe os vossos corações no amor de Deus, e na paciência de Cristo.'),
('acf','2ts',3,6,'Mandamo-vos, porém, irmãos, em nome de nosso Senhor Jesus Cristo, que vos aparteis de todo o irmão que anda desordenadamente, e não segundo a tradição que de nós recebeu.'),
('acf','2ts',3,7,'Porque vós mesmos sabeis como convém imitar-nos, pois que não nos houvemos desordenadamente entre vós,'),
('acf','2ts',3,8,'Nem de graça comemos o pão de homem algum, mas com trabalho e fadiga, trabalhando noite e dia, para não sermos pesados a nenhum de vós.'),
('acf','2ts',3,9,'Não porque não tivéssemos autoridade, mas para vos dar em nós mesmos exemplo, para nos imitardes.'),
('acf','2ts',3,10,'Porque, quando ainda estávamos convosco, vos mandamos isto, que, se alguém não quiser trabalhar, não coma também.'),
('acf','2ts',3,11,'Porquanto ouvimos que alguns entre vós andam desordenadamente, não trabalhando, antes fazendo coisas vãs.'),
('acf','2ts',3,12,'A esses tais, porém, mandamos, e exortamos por nosso Senhor Jesus Cristo, que, trabalhando com sossego, comam o seu próprio pão.'),
('acf','2ts',3,13,'E vós, irmãos, não vos canseis de fazer o bem.'),
('acf','2ts',3,14,'Mas, se alguém não obedecer à nossa palavra por esta carta, notai o tal, e não vos mistureis com ele, para que se envergonhe.'),
('acf','2ts',3,15,'Todavia não o tenhais como inimigo, mas admoestai-o como irmão.'),
('acf','2ts',3,16,'Ora, o mesmo Senhor da paz vos dê sempre paz de toda a maneira.O Senhor seja com todos vós.'),
('acf','2ts',3,17,'Saudação da minha própria mão, de mim, Paulo, que é o sinal em todas as epístolas; assim escrevo.'),
('acf','2ts',3,18,'A graça de nosso Senhor Jesus Cristo seja com todos vós. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1tm',1,1,'Paulo, apóstolo de Jesus Cristo, segundo o mandado de Deus, nosso Salvador, e do Senhor Jesus Cristo, esperança nossa,'),
('acf','1tm',1,2,'A Timóteo meu verdadeiro filho na fé: Graça, misericórdia e paz da parte de Deus nosso Pai, e da de Cristo Jesus, nosso Senhor.'),
('acf','1tm',1,3,'Como te roguei, quando parti para a macedônia, que ficasses em Éfeso, para advertires a alguns, que não ensinem outra doutrina,'),
('acf','1tm',1,4,'Nem se dêem a fábulas ou a genealogias intermináveis, que mais produzem questões do que edificação de Deus, que consiste na fé; assim o faço agora.'),
('acf','1tm',1,5,'Ora, o fim do mandamento é o amor de um coração puro, e de uma boa consciência, e de uma fé não fingida.'),
('acf','1tm',1,6,'Do que, desviando-se alguns, se entregaram a vãs contendas;'),
('acf','1tm',1,7,'Querendo ser mestres da lei, e não entendendo nem o que dizem nem o que afirmam.'),
('acf','1tm',1,8,'Sabemos, porém, que a lei é boa, se alguém dela usa legitimamente;'),
('acf','1tm',1,9,'Sabendo isto, que a lei não é feita para o justo, mas para os injustos e obstinados, para os ímpios e pecadores, para os profanos e irreligiosos, para os parricidas e matricidas, para os homicidas,'),
('acf','1tm',1,10,'Para os devassos, para os sodomitas, para os roubadores de homens, para os mentirosos, para os perjuros, e para o que for contrário à sã doutrina,'),
('acf','1tm',1,11,'Conforme o evangelho da glória de Deus bem-aventurado, que me foi confiado.'),
('acf','1tm',1,12,'E dou graças ao que me tem confortado, a Cristo Jesus Senhor nosso, porque me teve por fiel, pondo-me no ministério;'),
('acf','1tm',1,13,'A mim, que dantes fui blasfemo, e perseguidor, e injurioso; mas alcancei misericórdia, porque o fiz ignorantemente, na incredulidade.'),
('acf','1tm',1,14,'E a graça de nosso Senhor superabundou com a fé e amor que há em Jesus Cristo.'),
('acf','1tm',1,15,'Esta é uma palavra fiel, e digna de toda a aceitação, que Cristo Jesus veio ao mundo, para salvar os pecadores, dos quais eu sou o principal.'),
('acf','1tm',1,16,'Mas por isso alcancei misericórdia, para que em mim, que sou o principal, Jesus Cristo mostrasse toda a sua longanimidade, para exemplo dos que haviam de crer nele para a vida eterna.'),
('acf','1tm',1,17,'Ora, ao Rei dos séculos, imortal, invisível, ao único Deus sábio, seja honra e glória para todo o sempre. Amém.'),
('acf','1tm',1,18,'Este mandamento te dou, meu filho Timóteo, que, segundo as profecias que houve acerca de ti, milites por elas boa milícia;'),
('acf','1tm',1,19,'Conservando a fé, e a boa consciência, a qual alguns, rejeitando, fizeram naufrágio na fé.'),
('acf','1tm',1,20,'E entre esses foram Himeneu e Alexandre, os quais entreguei a Satanás, para que aprendam a não blasfemar.'),
('acf','1tm',2,1,'Admoesto-te, pois, antes de tudo, que se façam deprecações, orações, intercessões, e ações de graças, por todos os homens;'),
('acf','1tm',2,2,'Pelos reis, e por todos os que estão em eminência, para que tenhamos uma vida quieta e sossegada, em toda a piedade e honestidade;'),
('acf','1tm',2,3,'Porque isto é bom e agradável diante de Deus nosso Salvador,'),
('acf','1tm',2,4,'Que quer que todos os homens se salvem, e venham ao conhecimento da verdade.'),
('acf','1tm',2,5,'Porque há um só Deus, e um só Mediador entre Deus e os homens, Jesus Cristo homem.'),
('acf','1tm',2,6,'O qual se deu a si mesmo em preço de redenção por todos, para servir de testemunho a seu tempo.'),
('acf','1tm',2,7,'Para o que (digo a verdade em Cristo, não minto) fui constituído pregador, e apóstolo, e doutor dos gentios na fé e na verdade.'),
('acf','1tm',2,8,'Quero, pois, que os homens orem em todo o lugar, levantando mãos santas, sem ira nem contenda.'),
('acf','1tm',2,9,'Que do mesmo modo as mulheres se ataviem em traje honesto, com pudor e modéstia, não com tranças, ou com ouro, ou pérolas, ou vestidos preciosos,'),
('acf','1tm',2,10,'Mas (como convém a mulheres que fazem profissão de servir a Deus) com boas obras.'),
('acf','1tm',2,11,'A mulher aprenda em silêncio, com toda a sujeição.'),
('acf','1tm',2,12,'Não permito, porém, que a mulher ensine, nem use de autoridade sobre o marido, mas que esteja em silêncio.'),
('acf','1tm',2,13,'Porque primeiro foi formado Adão, depois Eva.'),
('acf','1tm',2,14,'E Adão não foi enganado, mas a mulher, sendo enganada, caiu em transgressão.'),
('acf','1tm',2,15,'Salvar-se-á, porém, dando à luz filhos, se permanecer com modéstia na fé, no amor e na santificação.'),
('acf','1tm',3,1,'Esta é uma palavra fiel: se alguém deseja o episcopado, excelente obra deseja.'),
('acf','1tm',3,2,'Convém, pois, que o bispo seja irrepreensível, marido de uma mulher, vigilante, sóbrio, honesto, hospitaleiro, apto para ensinar;'),
('acf','1tm',3,3,'Não dado ao vinho, não espancador, não cobiçoso de torpe ganância, mas moderado, não contencioso, não avarento;'),
('acf','1tm',3,4,'Que governe bem a sua própria casa, tendo seus filhos em sujeição, com toda a modéstia'),
('acf','1tm',3,5,'(Porque, se alguém não sabe governar a sua própria casa, terá cuidado da igreja de Deus? );'),
('acf','1tm',3,6,'Não neófito, para que, ensoberbecendo-se, não caia na condenação do diabo.'),
('acf','1tm',3,7,'Convém também que tenha bom testemunho dos que estão de fora, para que não caia em afronta, e no laço do diabo.'),
('acf','1tm',3,8,'Da mesma sorte os diáconos sejam honestos, não de língua dobre, não dados a muito vinho, não cobiçosos de torpe ganância;'),
('acf','1tm',3,9,'Guardando o mistério da fé numa consciência pura.'),
('acf','1tm',3,10,'E também estes sejam primeiro provados, depois sirvam, se forem irrepreensíveis.'),
('acf','1tm',3,11,'Da mesma sorte as esposas sejam honestas, não maldizentes, sóbrias e fiéis em tudo.'),
('acf','1tm',3,12,'Os diáconos sejam maridos de uma só mulher, e governem bem a seus filhos e suas próprias casas.'),
('acf','1tm',3,13,'Porque os que servirem bem como diáconos, adquirirão para si uma boa posição e muita confiança na fé que há em Cristo Jesus.'),
('acf','1tm',3,14,'Escrevo-te estas coisas, esperando ir ver-te bem depressa;'),
('acf','1tm',3,15,'Mas, se tardar, para que saibas como convém andar na casa de Deus, que é a igreja do Deus vivo, a coluna e firmeza da verdade.'),
('acf','1tm',3,16,'E, sem dúvida alguma, grande é o mistério da piedade: Deus se manifestou em carne, foi justificado no Espírito, visto dos anjos, pregado aos gentios, crido no mundo, recebido acima na glória.'),
('acf','1tm',4,1,'Mas o Espírito expressamente diz que nos últimos tempos apostatarão alguns da fé, dando ouvidos a espíritos enganadores, e a doutrinas de demônios;'),
('acf','1tm',4,2,'Pela hipocrisia de homens que falam mentiras, tendo cauterizada a sua própria consciência;'),
('acf','1tm',4,3,'Proibindo o casamento, e ordenando a abstinência dos alimentos que Deus criou para os fiéis, e para os que conhecem a verdade, a fim de usarem deles com ações de graças;'),
('acf','1tm',4,4,'Porque toda a criatura de Deus é boa, e não há nada que rejeitar, sendo recebido com ações de graças.'),
('acf','1tm',4,5,'Porque pela palavra de Deus e pela oração é santificada.'),
('acf','1tm',4,6,'Propondo estas coisas aos irmãos, serás bom ministro de Jesus Cristo, criado com as palavras da fé e da boa doutrina que tens seguido.'),
('acf','1tm',4,7,'Mas rejeita as fábulas profanas e de velhas, e exercita-te a ti mesmo em piedade;'),
('acf','1tm',4,8,'Porque o exercício corporal para pouco aproveita, mas a piedade para tudo é proveitosa, tendo a promessa da vida presente e da que há de vir.'),
('acf','1tm',4,9,'Esta palavra é fiel e digna de toda a aceitação;'),
('acf','1tm',4,10,'Porque para isto trabalhamos e somos injuriados, pois esperamos no Deus vivo, que é o Salvador de todos os homens, principalmente dos fiéis.'),
('acf','1tm',4,11,'Manda estas coisas e ensina-as.'),
('acf','1tm',4,12,'Ninguém despreze a tua mocidade; mas sê o exemplo dos fiéis, na palavra, no trato, no amor, no espírito, na fé, na pureza.'),
('acf','1tm',4,13,'Persiste em ler, exortar e ensinar, até que eu vá.'),
('acf','1tm',4,14,'Não desprezes o dom que há em ti, o qual te foi dado por profecia, com a imposição das mãos do presbitério.'),
('acf','1tm',4,15,'Medita estas coisas; ocupa-te nelas, para que o teu aproveitamento seja manifesto a todos.'),
('acf','1tm',4,16,'Tem cuidado de ti mesmo e da doutrina. Persevera nestas coisas; porque, fazendo isto, te salvarás, tanto a ti mesmo como aos que te ouvem.'),
('acf','1tm',5,1,'NÃO repreendas asperamente o ancião, mas admoesta-o como a pai; aos moços como a irmãos;'),
('acf','1tm',5,2,'As mulheres idosas, como a mães, às moças, como a irmãs, em toda a pureza.'),
('acf','1tm',5,3,'Honra as viúvas que verdadeiramente são viúvas.'),
('acf','1tm',5,4,'Mas, se alguma viúva tiver filhos, ou netos, aprendam primeiro a exercer piedade para com a sua própria família, e a recompensar seus pais; porque isto é bom e agradável diante de Deus.'),
('acf','1tm',5,5,'Ora, a que é verdadeiramente viúva e desamparada espera em Deus, e persevera de noite e de dia em rogos e orações;'),
('acf','1tm',5,6,'Mas a que vive em deleites, vivendo está morta.'),
('acf','1tm',5,7,'Manda, pois, estas coisas, para que elas sejam irrepreensíveis.'),
('acf','1tm',5,8,'Mas, se alguém não tem cuidado dos seus, e principalmente dos da sua família, negou a fé, e é pior do que o infiel.'),
('acf','1tm',5,9,'Nunca seja inscrita viúva com menos de sessenta anos, e só a que tenha sido mulher de um só marido;'),
('acf','1tm',5,10,'Tendo testemunho de boas obras: Se criou os filhos, se exercitou hospitalidade, se lavou os pés aos santos, se socorreu os aflitos, se praticou toda a boa obra.'),
('acf','1tm',5,11,'Mas não admitas as viúvas mais novas, porque, quando se tornam levianas contra Cristo, querem casar-se;'),
('acf','1tm',5,12,'Tendo já a sua condenação por haverem aniquilado a primeira fé.'),
('acf','1tm',5,13,'E, além disto, aprendem também a andar ociosas de casa em casa; e não só ociosas, mas também paroleiras e curiosas, falando o que não convém.'),
('acf','1tm',5,14,'Quero, pois, que as que são moças se casem, gerem filhos, governem a casa, e não dêem ocasião ao adversário de maldizer;'),
('acf','1tm',5,15,'Porque já algumas se desviaram, indo após Satanás.'),
('acf','1tm',5,16,'Se algum crente ou alguma crente tem viúvas, socorra-as, e não se sobrecarregue a igreja, para que se possam sustentar as que deveras são viúvas.'),
('acf','1tm',5,17,'Os presbíteros que governam bem sejam estimados por dignos de duplicada honra, principalmente os que trabalham na palavra e na doutrina;'),
('acf','1tm',5,18,'Porque diz a Escritura: Não ligarás a boca ao boi que debulha. E: Digno é o obreiro do seu salário.'),
('acf','1tm',5,19,'Não aceites acusação contra o presbítero, senão com duas ou três testemunhas.'),
('acf','1tm',5,20,'Aos que pecarem, repreende-os na presença de todos, para que também os outros tenham temor.'),
('acf','1tm',5,21,'Conjuro-te diante de Deus, e do Senhor Jesus Cristo, e dos anjos eleitos, que sem prevenção guardes estas coisas, nada fazendo por parcialidade.'),
('acf','1tm',5,22,'A ninguém imponhas precipitadamente as mãos, nem participes dos pecados alheios; conserva-te a ti mesmo puro.'),
('acf','1tm',5,23,'Não bebas mais água só, mas usa de um pouco de vinho, por causa do teu estômago e das tuas freqüentes enfermidades.'),
('acf','1tm',5,24,'Os pecados de alguns homens são manifestos, precedendo o juízo; e em alguns manifestam-se depois.'),
('acf','1tm',5,25,'Assim mesmo também as boas obras são manifestas, e as que são de outra maneira não podem ocultar-se.'),
('acf','1tm',6,1,'Todos os servos que estão debaixo do jugo estimem a seus senhores por dignos de toda a honra, para que o nome de Deus e a doutrina não sejam blasfemados.'),
('acf','1tm',6,2,'E os que têm senhores crentes não os desprezem, por serem irmãos; antes os sirvam melhor, porque eles, que participam do benefício, são crentes e amados. Isto ensina e exorta.'),
('acf','1tm',6,3,'Se alguém ensina alguma outra doutrina, e se não conforma com as sãs palavras de nosso Senhor Jesus Cristo, e com a doutrina que é segundo a piedade,'),
('acf','1tm',6,4,'É soberbo, e nada sabe, mas delira acerca de questões e contendas de palavras, das quais nascem invejas, porfias, blasfêmias, ruins suspeitas,'),
('acf','1tm',6,5,'Perversas contendas de homens corruptos de entendimento, e privados da verdade, cuidando que a piedade seja causa de ganho; aparta-te dos tais.'),
('acf','1tm',6,6,'Mas é grande ganho a piedade com contentamento.'),
('acf','1tm',6,7,'Porque nada trouxemos para este mundo, e manifesto é que nada podemos levar dele.'),
('acf','1tm',6,8,'Tendo, porém, sustento, e com que nos cobrirmos, estejamos com isso contentes.'),
('acf','1tm',6,9,'Mas os que querem ser ricos caem em tentação, e em laço, e em muitas concupiscências loucas e nocivas, que submergem os homens na perdição e ruína.'),
('acf','1tm',6,10,'Porque o amor ao dinheiro é a raiz de toda a espécie de males; e nessa cobiça alguns se desviaram da fé, e se traspassaram a si mesmos com muitas dores.'),
('acf','1tm',6,11,'Mas tu, ó homem de Deus, foge destas coisas, e segue a justiça, a piedade, a fé, o amor, a paciência, a mansidão.'),
('acf','1tm',6,12,'Milita a boa milícia da fé, toma posse da vida eterna, para a qual também foste chamado, tendo já feito boa confissão diante de muitas testemunhas.'),
('acf','1tm',6,13,'Mando-te diante de Deus, que todas as coisas vivifica, e de Cristo Jesus, que diante de Pôncio Pilatos deu o testemunho de boa confissão,'),
('acf','1tm',6,14,'Que guardes este mandamento sem mácula e repreensão, até à aparição de nosso Senhor Jesus Cristo;'),
('acf','1tm',6,15,'A qual a seu tempo mostrará o bem-aventurado, e único poderoso Senhor, Rei dos reis e Senhor dos senhores;'),
('acf','1tm',6,16,'Aquele que tem, ele só, a imortalidade, e habita na luz inacessível; a quem nenhum dos homens viu nem pode ver, ao qual seja honra e poder sempiterno. Amém.'),
('acf','1tm',6,17,'Manda aos ricos deste mundo que não sejam altivos, nem ponham a esperança na incerteza das riquezas, mas em Deus, que abundantemente nos dá todas as coisas para delas gozarmos;'),
('acf','1tm',6,18,'Que façam bem, enriqueçam em boas obras, repartam de boa mente, e sejam comunicáveis;'),
('acf','1tm',6,19,'Que entesourem para si mesmos um bom fundamento para o futuro, para que possam se apoderar da vida eterna.'),
('acf','1tm',6,20,'Ó Timóteo, guarda o depósito que te foi confiado, tendo horror aos clamores vãos e profanos e às oposições da falsamente chamada ciência,'),
('acf','1tm',6,21,'A qual professando-a alguns, se desviaram da fé. A graça seja contigo. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2tm',1,1,'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, segundo a promessa da vida que está em Cristo Jesus,'),
('acf','2tm',1,2,'A Timóteo, meu amado filho: Graça, misericórdia, e paz da parte de Deus Pai, e da de Cristo Jesus, Senhor nosso.'),
('acf','2tm',1,3,'Dou graças a Deus, a quem desde os meus antepassados sirvo com uma consciência pura, de que sem cessar faço memória de ti nas minhas orações noite e dia;'),
('acf','2tm',1,4,'Desejando muito ver-te, lembrando-me das tuas lágrimas, para me encher de gozo;'),
('acf','2tm',1,5,'Trazendo à memória a fé não fingida que em ti há, a qual habitou primeiro em tua avó Lóide, e em tua mãe Eunice, e estou certo de que também habita em ti.'),
('acf','2tm',1,6,'Por cujo motivo te lembro que despertes o dom de Deus que existe em ti pela imposição das minhas mãos.'),
('acf','2tm',1,7,'Porque Deus não nos deu o espírito de temor, mas de fortaleza, e de amor, e de moderação.'),
('acf','2tm',1,8,'Portanto, não te envergonhes do testemunho de nosso Senhor, nem de mim, que sou prisioneiro seu; antes participa das aflições do evangelho segundo o poder de Deus,'),
('acf','2tm',1,9,'Que nos salvou, e chamou com uma santa vocação; não segundo as nossas obras, mas segundo o seu próprio propósito e graça que nos foi dada em Cristo Jesus antes dos tempos dos séculos;'),
('acf','2tm',1,10,'E que é manifesta agora pela aparição de nosso Salvador Jesus Cristo, o qual aboliu a morte, e trouxe à luz a vida e a incorrupção pelo evangelho;'),
('acf','2tm',1,11,'Para o que fui constituído pregador, e apóstolo, e doutor dos gentios.'),
('acf','2tm',1,12,'Por cuja causa padeço também isto, mas não me envergonho; porque eu sei em quem tenho crido, e estou certo de que é poderoso para guardar o meu depósito até àquele dia.'),
('acf','2tm',1,13,'Conserva o modelo das sãs palavras que de mim tens ouvido, na fé e no amor que há em Cristo Jesus.'),
('acf','2tm',1,14,'Guarda o bom depósito pelo Espírito Santo que habita em nós.'),
('acf','2tm',1,15,'Bem sabes isto, que os que estão na Ásia todos se apartaram de mim; entre os quais foram Figelo e Hermógenes.'),
('acf','2tm',1,16,'O Senhor conceda misericórdia à casa de Onesíforo, porque muitas vezes me recreou, e não se envergonhou das minhas cadeias.'),
('acf','2tm',1,17,'Antes, vindo ele a Roma, com muito cuidado me procurou e me achou.'),
('acf','2tm',1,18,'O Senhor lhe conceda que naquele dia ache misericórdia diante do Senhor. E, quanto me ajudou em Éfeso, melhor o sabes tu.'),
('acf','2tm',2,1,'Tu, pois, meu filho, fortifica-te na graça que há em Cristo Jesus.'),
('acf','2tm',2,2,'E o que de mim, entre muitas testemunhas, ouviste, confia-o a homens fiéis, que sejam idôneos para também ensinarem os outros.'),
('acf','2tm',2,3,'Tu pois, sofre as aflições, como bom soldado de Jesus Cristo.'),
('acf','2tm',2,4,'Ninguém que milita se embaraça com negócios desta vida, a fim de agradar àquele que o alistou para a guerra.'),
('acf','2tm',2,5,'E, se alguém também milita, não é coroado se não militar legitimamente.'),
('acf','2tm',2,6,'O lavrador que trabalha deve ser o primeiro a gozar dos frutos.'),
('acf','2tm',2,7,'Considera o que digo, e o Senhor te dê entendimento em tudo.'),
('acf','2tm',2,8,'Lembra-te de que Jesus Cristo, que é da descendência de Davi, ressuscitou dentre os mortos, segundo o meu evangelho;'),
('acf','2tm',2,9,'Por isso sofro trabalhos e até prisões, como um malfeitor; mas a palavra de Deus não está presa.'),
('acf','2tm',2,10,'Portanto, tudo sofro por amor dos escolhidos, para que também eles alcancem a salvação que está em Cristo Jesus com glória eterna.'),
('acf','2tm',2,11,'Palavra fiel é esta: que, se morrermos com ele, também com ele viveremos;'),
('acf','2tm',2,12,'Se sofrermos, também com ele reinaremos; se o negarmos, também ele nos negará;'),
('acf','2tm',2,13,'Se formos infiéis, ele permanece fiel; não pode negar-se a si mesmo.'),
('acf','2tm',2,14,'Traze estas coisas à memória, ordenando-lhes diante do Senhor que não tenham contendas de palavras, que para nada aproveitam e são para perversão dos ouvintes.'),
('acf','2tm',2,15,'Procura apresentar-te a Deus aprovado, como obreiro que não tem de que se envergonhar, que maneja bem a palavra da verdade.'),
('acf','2tm',2,16,'Mas evita os falatórios profanos, porque produzirão maior impiedade.'),
('acf','2tm',2,17,'E a palavra desses roerá como gangrena; entre os quais são Himeneu e Fileto;'),
('acf','2tm',2,18,'Os quais se desviaram da verdade, dizendo que a ressurreição era já feita, e perverteram a fé de alguns.'),
('acf','2tm',2,19,'Todavia o fundamento de Deus fica firme, tendo este selo: O Senhor conhece os que são seus, e qualquer que profere o nome de Cristo aparte-se da iniqüidade.'),
('acf','2tm',2,20,'Ora, numa grande casa não somente há vasos de ouro e de prata, mas também de pau e de barro; uns para honra, outros, porém, para desonra.'),
('acf','2tm',2,21,'De sorte que, se alguém se purificar destas coisas, será vaso para honra, santificado e idôneo para uso do Senhor, e preparado para toda a boa obra.'),
('acf','2tm',2,22,'Foge também das paixões da mocidade; e segue a justiça, a fé, o amor, e a paz com os que, com um coração puro, invocam o Senhor.'),
('acf','2tm',2,23,'E rejeita as questões loucas, e sem instrução, sabendo que produzem contendas.'),
('acf','2tm',2,24,'E ao servo do Senhor não convém contender, mas sim, ser manso para com todos, apto para ensinar, sofredor;'),
('acf','2tm',2,25,'Instruindo com mansidão os que resistem, a ver se porventura Deus lhes dará arrependimento para conhecerem a verdade,'),
('acf','2tm',2,26,'E tornarem a despertar, desprendendo-se dos laços do diabo, em que à vontade dele estão presos.'),
('acf','2tm',3,1,'Sabe, porém, isto: que nos últimos dias sobrevirão tempos trabalhosos.'),
('acf','2tm',3,2,'Porque haverá homens amantes de si mesmos, avarentos, presunçosos, soberbos, blasfemos, desobedientes a pais e mães, ingratos, profanos,'),
('acf','2tm',3,3,'Sem afeto natural, irreconciliáveis, caluniadores, incontinentes, cruéis, sem amor para com os bons,'),
('acf','2tm',3,4,'Traidores, obstinados, orgulhosos, mais amigos dos deleites do que amigos de Deus,'),
('acf','2tm',3,5,'Tendo aparência de piedade, mas negando a eficácia dela. Destes afasta-te.'),
('acf','2tm',3,6,'Porque deste número são os que se introduzem pelas casas, e levam cativas mulheres néscias carregadas de pecados, levadas de várias concupiscências;'),
('acf','2tm',3,7,'Que aprendem sempre, e nunca podem chegar ao conhecimento da verdade.'),
('acf','2tm',3,8,'E, como Janes e Jambres resistiram a Moisés, assim também estes resistem à verdade, sendo homens corruptos de entendimento e réprobos quanto à fé.'),
('acf','2tm',3,9,'Não irão, porém, avante; porque a todos será manifesto o seu desvario, como também o foi o daqueles.'),
('acf','2tm',3,10,'Tu, porém, tens seguido a minha doutrina, modo de viver, intenção, fé, longanimidade, amor, paciência,'),
('acf','2tm',3,11,'Perseguições e aflições tais quais me aconteceram em Antioquia, em Icônio, e em Listra; quantas perseguições sofri, e o Senhor de todas me livrou;'),
('acf','2tm',3,12,'E também todos os que piamente querem viver em Cristo Jesus padecerão perseguições.'),
('acf','2tm',3,13,'Mas os homens maus e enganadores irão de mal para pior, enganando e sendo enganados.'),
('acf','2tm',3,14,'Tu, porém, permanece naquilo que aprendeste, e de que foste inteirado, sabendo de quem o tens aprendido,'),
('acf','2tm',3,15,'E que desde a tua meninice sabes as sagradas Escrituras, que podem fazer-te sábio para a salvação, pela fé que há em Cristo Jesus.'),
('acf','2tm',3,16,'Toda a Escritura é divinamente inspirada, e proveitosa para ensinar, para redargüir, para corrigir, para instruir em justiça;'),
('acf','2tm',3,17,'Para que o homem de Deus seja perfeito, e perfeitamente instruído para toda a boa obra.'),
('acf','2tm',4,1,'Conjuro-te, pois, diante de Deus, e do Senhor Jesus Cristo, que há de julgar os vivos e os mortos, na sua vinda e no seu reino,'),
('acf','2tm',4,2,'Que pregues a palavra, instes a tempo e fora de tempo, redarguas, repreendas, exortes, com toda a longanimidade e doutrina.'),
('acf','2tm',4,3,'Porque virá tempo em que não suportarão a sã doutrina; mas, tendo comichão nos ouvidos, amontoarão para si doutores conforme as suas próprias concupiscências;'),
('acf','2tm',4,4,'E desviarão os ouvidos da verdade, voltando às fábulas.'),
('acf','2tm',4,5,'Mas tu, sê sóbrio em tudo, sofre as aflições, faze a obra de um evangelista, cumpre o teu ministério.'),
('acf','2tm',4,6,'Porque eu já estou sendo oferecido por aspersão de sacrifício, e o tempo da minha partida está próximo.'),
('acf','2tm',4,7,'Combati o bom combate, acabei a carreira, guardei a fé.'),
('acf','2tm',4,8,'Desde agora, a coroa da justiça me está guardada, a qual o Senhor, justo juiz, me dará naquele dia; e não somente a mim, mas também a todos os que amarem a sua vinda.'),
('acf','2tm',4,9,'Procura vir ter comigo depressa,'),
('acf','2tm',4,10,'Porque Demas me desamparou, amando o presente século, e foi para Tessalônica, Crescente para Galácia, Tito para Dalmácia.'),
('acf','2tm',4,11,'Só Lucas está comigo. Toma Marcos, e traze-o contigo, porque me é muito útil para o ministério.'),
('acf','2tm',4,12,'Também enviei Tíquico a Éfeso.'),
('acf','2tm',4,13,'Quando vieres, traze a capa que deixei em Trôade, em casa de Carpo, e os livros, principalmente os pergaminhos.'),
('acf','2tm',4,14,'Alexandre, o latoeiro, causoume muitos males; o Senhor lhe pague segundo as suas obras.'),
('acf','2tm',4,15,'Tu, guarda-te também dele, porque resistiu muito às nossas palavras.'),
('acf','2tm',4,16,'Ninguém me assistiu na minha primeira defesa, antes todos me desampararam. Que isto lhes não seja imputado.'),
('acf','2tm',4,17,'Mas o Senhor assistiu-me e fortaleceu-me, para que por mim fosse cumprida a pregação, e todos os gentios a ouvissem; e fiquei livre da boca do leão.'),
('acf','2tm',4,18,'E o Senhor me livrará de toda a má obra, e guardar-me-á para o seu reino celestial; a quem seja glória para todo o sempre. Amém.'),
('acf','2tm',4,19,'Saúda a Prisca e a Áqüila, e à casa de Onesíforo.'),
('acf','2tm',4,20,'Erasto ficou em Corinto, e deixei Trófimo doente em Mileto.'),
('acf','2tm',4,21,'Procura vir antes do inverno. Eubulo, e Prudente, e Lino, e Cláudia, e todos os irmãos te saúdam.'),
('acf','2tm',4,22,'O Senhor Jesus Cristo seja com o teu espírito. A graça seja convosco. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','tt',1,1,'Paulo, servo de Deus, e apóstolo de Jesus Cristo, segundo a fé dos eleitos de Deus, e o conhecimento da verdade, que é segundo a piedade,'),
('acf','tt',1,2,'Em esperança da vida eterna, a qual Deus, que não pode mentir, prometeu antes dos tempos dos séculos;'),
('acf','tt',1,3,'Mas a seu tempo manifestou a sua palavra pela pregação que me foi confiada segundo o mandamento de Deus, nosso Salvador;'),
('acf','tt',1,4,'A Tito, meu verdadeiro filho, segundo a fé comum: Graça, misericórdia, e paz da parte de Deus Pai, e da do Senhor Jesus Cristo, nosso Salvador.'),
('acf','tt',1,5,'Por esta causa te deixei em Creta, para que pusesses em boa ordem as coisas que ainda restam, e de cidade em cidade estabelecesses presbíteros, como já te mandei:'),
('acf','tt',1,6,'Aquele que for irrepreensível, marido de uma mulher, que tenha filhos fiéis, que não possam ser acusados de dissolução nem são desobedientes.'),
('acf','tt',1,7,'Porque convém que o bispo seja irrepreensível, como despenseiro da casa de Deus, não soberbo, nem iracundo, nem dado ao vinho, nem espancador, nem cobiçoso de torpe ganância;'),
('acf','tt',1,8,'Mas dado à hospitalidade, amigo do bem, moderado, justo, santo, temperante;'),
('acf','tt',1,9,'Retendo firme a fiel palavra, que é conforme a doutrina, para que seja poderoso, tanto para admoestar com a sã doutrina, como para convencer os contradizentes.'),
('acf','tt',1,10,'Porque há muitos desordenados, faladores, vãos e enganadores, principalmente os da circuncisão,'),
('acf','tt',1,11,'Aos quais convém tapar a boca; homens que transtornam casas inteiras ensinando o que não convém, por torpe ganância.'),
('acf','tt',1,12,'Um deles, seu próprio profeta, disse: Os cretenses são sempre mentirosos, bestas ruins, ventres preguiçosos.'),
('acf','tt',1,13,'Este testemunho é verdadeiro. Portanto, repreende-os severamente, para que sejam sãos na fé.'),
('acf','tt',1,14,'Não dando ouvidos às fábulas judaicas, nem aos mandamentos de homens que se desviam da verdade.'),
('acf','tt',1,15,'Todas as coisas são puras para os puros, mas nada é puro para os contaminados e infiéis; antes o seu entendimento e consciência estão contaminados.'),
('acf','tt',1,16,'Confessam que conhecem a Deus, mas negam-no com as obras, sendo abomináveis, e desobedientes, e reprovados para toda a boa obra.'),
('acf','tt',2,1,'Tu, porém, fala o que convém à sã doutrina.'),
('acf','tt',2,2,'Os velhos, que sejam sóbrios, graves, prudentes, sãos na fé, no amor, e na paciência;'),
('acf','tt',2,3,'As mulheres idosas, semelhantemente, que sejam sérias no seu viver, como convém a santas, não caluniadoras, não dadas a muito vinho, mestras no bem;'),
('acf','tt',2,4,'Para que ensinem as mulheres novas a serem prudentes, a amarem seus maridos, a amarem seus filhos,'),
('acf','tt',2,5,'A serem moderadas, castas, boas donas de casa, sujeitas a seus maridos, a fim de que a palavra de Deus não seja blasfemada.'),
('acf','tt',2,6,'Exorta semelhantemente os jovens a que sejam moderados.'),
('acf','tt',2,7,'Em tudo te dá por exemplo de boas obras; na doutrina mostra incorrupção, gravidade, sinceridade,'),
('acf','tt',2,8,'Linguagem sã e irrepreensível, para que o adversário se envergonhe, não tendo nenhum mal que dizer de nós.'),
('acf','tt',2,9,'Exorta os servos a que se sujeitem a seus senhores, e em tudo agradem, não contradizendo,'),
('acf','tt',2,10,'Não defraudando, antes mostrando toda a boa lealdade, para que em tudo sejam ornamento da doutrina de Deus, nosso Salvador.'),
('acf','tt',2,11,'Porque a graça salvadora de Deus se há manifestado a todos os homens,'),
('acf','tt',2,12,'Ensinando-nos que, renunciando à impiedade e às concupiscências mundanas, vivamos neste presente século sóbria, e justa, e piamente,'),
('acf','tt',2,13,'Aguardando a bem-aventurada esperança e o aparecimento da glória do grande Deus e nosso Senhor Jesus Cristo;'),
('acf','tt',2,14,'O qual se deu a si mesmo por nós para nos remir de toda a iniqüidade, e purificar para si um povo seu especial, zeloso de boas obras.'),
('acf','tt',2,15,'Fala disto, e exorta e repreende com toda a autoridade. Ninguém te despreze.'),
('acf','tt',3,1,'Admoesta-os a que se sujeitem aos principados e potestades, que lhes obedeçam, e estejam preparados para toda a boa obra;'),
('acf','tt',3,2,'Que a ninguém infamem, nem sejam contenciosos, mas modestos, mostrando toda a mansidão para com todos os homens.'),
('acf','tt',3,3,'Porque também nós éramos noutro tempo insensatos, desobedientes, extraviados, servindo a várias concupiscências e deleites, vivendo em malícia e inveja, odiosos, odiando-nos uns aos outros.'),
('acf','tt',3,4,'Mas quando apareceu a benignidade e amor de Deus, nosso Salvador, para com os homens,'),
('acf','tt',3,5,'Não pelas obras de justiça que houvéssemos feito, mas segundo a sua misericórdia, nos salvou pela lavagem da regeneração e da renovação do Espírito Santo,'),
('acf','tt',3,6,'Que abundantemente ele derramou sobre nós por Jesus Cristo nosso Salvador;'),
('acf','tt',3,7,'Para que, sendo justificados pela sua graça, sejamos feitos herdeiros segundo a esperança da vida eterna.'),
('acf','tt',3,8,'Fiel é a palavra, e isto quero que deveras afirmes, para que os que crêem em Deus procurem aplicar-se às boas obras; estas coisas são boas e proveitosas aos homens.'),
('acf','tt',3,9,'Mas não entres em questões loucas, genealogias e contendas, e nos debates acerca da lei; porque são coisas inúteis e vãs.'),
('acf','tt',3,10,'Ao homem hereje, depois de uma e outra admoestação, evita-o,'),
('acf','tt',3,11,'Sabendo que esse tal está pervertido, e peca, estando já em si mesmo condenado.'),
('acf','tt',3,12,'Quando te enviar Ártemas, ou Tíquico, procura vir ter comigo a Nicópolis; porque deliberei invernar ali.'),
('acf','tt',3,13,'Acompanha com muito cuidado Zenas, doutor da lei, e Apolo, para que nada lhes falte.'),
('acf','tt',3,14,'E os nossos aprendam também a aplicar-se às boas obras, nas coisas necessárias, para que não sejam infrutuosos.'),
('acf','tt',3,15,'Saúdam-te todos os que estão comigo. Saúda tu os que nos amam na fé. A graça seja com vós todos. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','fm',1,1,'Paulo, prisioneiro de Jesus Cristo, e o irmão Timóteo, ao amado Filemom, nosso cooperador,'),
('acf','fm',1,2,'E à nossa amada Áfia, e a Arquipo, nosso camarada, e à igreja que está em tua casa:'),
('acf','fm',1,3,'Graça a vós e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.'),
('acf','fm',1,4,'Graças dou ao meu Deus, lembrando-me sempre de ti nas minhas orações;'),
('acf','fm',1,5,'Ouvindo do teu amor e da fé que tens para com o Senhor Jesus Cristo, e para com todos os santos;'),
('acf','fm',1,6,'Para que a comunicação da tua fé seja eficaz no conhecimento de todo o bem que em vós há por Cristo Jesus.'),
('acf','fm',1,7,'Porque temos grande gozo e consolação do teu amor, porque por ti, ó irmão, as entranhas dos santos foram recreadas.'),
('acf','fm',1,8,'Por isso, ainda que tenha em Cristo grande confiança para te mandar o que te convém,'),
('acf','fm',1,9,'Todavia peço-te antes por amor, sendo eu tal como sou, Paulo o velho, e também agora prisioneiro de Jesus Cristo.'),
('acf','fm',1,10,'Peço-te por meu filho Onésimo, que gerei nas minhas prisões;'),
('acf','fm',1,11,'O qual noutro tempo te foi inútil, mas agora a ti e a mim muito útil; eu to tornei a enviar.'),
('acf','fm',1,12,'E tu torna a recebê-lo como às minhas entranhas.'),
('acf','fm',1,13,'Eu bem o quisera conservar comigo, para que por ti me servisse nas prisões do evangelho;'),
('acf','fm',1,14,'Mas nada quis fazer sem o teu parecer, para que o teu benefício não fosse como por força, mas, voluntário.'),
('acf','fm',1,15,'Porque bem pode ser que ele se tenha separado de ti por algum tempo, para que o retivesses para sempre,'),
('acf','fm',1,16,'Não já como servo, antes, mais do que servo, como irmão amado, particularmente de mim, e quanto mais de ti, assim na carne como no Senhor?'),
('acf','fm',1,17,'Assim, pois, se me tens por companheiro, recebe-o como a mim mesmo.'),
('acf','fm',1,18,'E, se te fez algum dano, ou te deve alguma coisa, põe isso à minha conta.'),
('acf','fm',1,19,'Eu, Paulo, de minha própria mão o escrevi; eu o pagarei, para te não dizer que ainda mesmo a ti próprio a mim te deves.'),
('acf','fm',1,20,'Sim, irmão, eu me regozijarei de ti no Senhor; recreia as minhas entranhas no Senhor.'),
('acf','fm',1,21,'Escrevi-te confiado na tua obediência, sabendo que ainda farás mais do que digo.'),
('acf','fm',1,22,'E juntamente prepara-me também pousada, porque espero que pelas vossas orações vos hei de ser concedido.'),
('acf','fm',1,23,'Saúdam-te Epafras, meu companheiro de prisão por Cristo Jesus,'),
('acf','fm',1,24,'Marcos, Aristarco, Demas e Lucas, meus cooperadores.'),
('acf','fm',1,25,'A graça de nosso Senhor Jesus Cristo seja com o vosso espírito. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','hb',1,1,'Havendo Deus antigamente falado muitas vezes, e de muitas maneiras, aos pais, pelos profetas, a nós falou-nos nestes últimos dias pelo Filho,'),
('acf','hb',1,2,'A quem constituiu herdeiro de tudo, por quem fez também o mundo.'),
('acf','hb',1,3,'O qual, sendo o resplendor da sua glória, e a expressa imagem da sua pessoa, e sustentando todas as coisas pela palavra do seu poder, havendo feito por si mesmo a purificação dos nossos pecados, assentou-se à destra da majestade nas alturas;'),
('acf','hb',1,4,'Feito tanto mais excelente do que os anjos, quanto herdou mais excelente nome do que eles.'),
('acf','hb',1,5,'Porque, a qual dos anjos disse jamais: Tu és meu Filho, Hoje te gerei? E outra vez: Eu lhe serei por Pai, E ele me será por Filho?'),
('acf','hb',1,6,'E outra vez, quando introduz no mundo o primogênito, diz:E todos os anjos de Deus o adorem.'),
('acf','hb',1,7,'E, quanto aos anjos, diz: Faz dos seus anjos espíritos, E de seus ministros labareda de fogo.'),
('acf','hb',1,8,'Mas, do Filho, diz: Ó Deus, o teu trono subsiste pelos séculos dos séculos; Cetro de eqüidade é o cetro do teu reino.'),
('acf','hb',1,9,'Amaste a justiça e odiaste a iniqüidade; por isso Deus, o teu Deus, te ungiuCom óleo de alegria mais do que a teus companheiros.'),
('acf','hb',1,10,'E: Tu, Senhor, no princípio fundaste a terra, E os céus são obra de tuas mãos.'),
('acf','hb',1,11,'Eles perecerão, mas tu permanecerás; E todos eles, como roupa, envelhecerão,'),
('acf','hb',1,12,'E como um manto os enrolarás, e serão mudados. Mas tu és o mesmo, E os teus anos não acabarão.'),
('acf','hb',1,13,'E a qual dos anjos disse jamais: Assenta-te à minha destra, Até que ponha a teus inimigos por escabelo de teus pés?'),
('acf','hb',1,14,'Não são porventura todos eles espíritos ministradores, enviados para servir a favor daqueles que hão de herdar a salvação?'),
('acf','hb',2,1,'Portanto, convém-nos atentar com mais diligência para as coisas que já temos ouvido, para que em tempo algum nos desviemos delas.'),
('acf','hb',2,2,'Porque, se a palavra falada pelos anjos permaneceu firme, e toda a transgressão e desobediência recebeu a justa retribuição,'),
('acf','hb',2,3,'Como escaparemos nós, se não atentarmos para uma tão grande salvação, a qual, começando a ser anunciada pelo Senhor, foi-nos depois confirmada pelos que a ouviram;'),
('acf','hb',2,4,'Testificando também Deus com eles, por sinais, e milagres, e várias maravilhas e dons do Espírito Santo, distribuídos por sua vontade?'),
('acf','hb',2,5,'Porque não foi aos anjos que sujeitou o mundo futuro, de que falamos.'),
('acf','hb',2,6,'Mas em certo lugar testificou alguém, dizendo:Que é o homem, para que dele te lembres?Ou o filho do homem, para que o visites?'),
('acf','hb',2,7,'Tu o fizeste um pouco menor do que os anjos,De glória e de honra o coroaste,E o constituíste sobre as obras de tuas mãos;'),
('acf','hb',2,8,'Todas as coisas lhe sujeitaste debaixo dos pés.Ora, visto que lhe sujeitou todas as coisas, nada deixou que lhe não esteja sujeito. Mas agora ainda não vemos que todas as coisas lhe estejam sujeitas.'),
('acf','hb',2,9,'Vemos, porém, coroado de glória e de honra aquele Jesus que fora feito um pouco menor do que os anjos, por causa da paixão da morte, para que, pela graça de Deus, provasse a morte por todos.'),
('acf','hb',2,10,'Porque convinha que aquele, para quem são todas as coisas, e mediante quem tudo existe, trazendo muitos filhos à glória, consagrasse pelas aflições o príncipe da salvação deles.'),
('acf','hb',2,11,'Porque, assim o que santifica, como os que são santificados, são todos de um; por cuja causa não se envergonha de lhes chamar irmãos,'),
('acf','hb',2,12,'Dizendo:Anunciarei o teu nome a meus irmãos,Cantar-te-ei louvores no meio da congregação.'),
('acf','hb',2,13,'E outra vez: Porei nele a minha confiança. E outra vez: Eis-me aqui a mim, e aos filhos que Deus me deu.'),
('acf','hb',2,14,'E, visto como os filhos participam da carne e do sangue, também ele participou das mesmas coisas, para que pela morte aniquilasse o que tinha o império da morte, isto é, o diabo;'),
('acf','hb',2,15,'E livrasse todos os que, com medo da morte, estavam por toda a vida sujeitos à servidão.'),
('acf','hb',2,16,'Porque, na verdade, ele não tomou os anjos, mas tomou a descendência de Abraão.'),
('acf','hb',2,17,'Por isso convinha que em tudo fosse semelhante aos irmãos, para ser misericordioso e fiel sumo sacerdote naquilo que é de Deus, para expiar os pecados do povo.'),
('acf','hb',2,18,'Porque naquilo que ele mesmo, sendo tentado, padeceu, pode socorrer aos que são tentados.'),
('acf','hb',3,1,'Por isso, irmãos santos, participantes da vocação celestial, considerai a Jesus Cristo, apóstolo e sumo sacerdote da nossa confissão,'),
('acf','hb',3,2,'Sendo fiel ao que o constituiu, como também o foi Moisés em toda a sua casa.'),
('acf','hb',3,3,'Porque ele é tido por digno de tanto maior glória do que Moisés, quanto maior honra do que a casa tem aquele que a edificou.'),
('acf','hb',3,4,'Porque toda a casa é edificada por alguém, mas o que edificou todas as coisas é Deus.'),
('acf','hb',3,5,'E, na verdade, Moisés foi fiel em toda a sua casa, como servo, para testemunho das coisas que se haviam de anunciar;'),
('acf','hb',3,6,'Mas Cristo, como Filho, sobre a sua própria casa; a qual casa somos nós, se tão somente conservarmos firme a confiança e a glória da esperança até ao fim.'),
('acf','hb',3,7,'Portanto, como diz o Espírito Santo: Se ouvirdes hoje a sua voz,'),
('acf','hb',3,8,'Não endureçais os vossos corações,Como na provocação, no dia da tentação no deserto.'),
('acf','hb',3,9,'Onde vossos pais me tentaram, me provaram,E viram por quarenta anos as minhas obras.'),
('acf','hb',3,10,'Por isso me indignei contra esta geração, E disse: Estes sempre erram em seu coração, E não conheceram os meus caminhos.'),
('acf','hb',3,11,'Assim jurei na minha ira Que não entrarão no meu repouso.'),
('acf','hb',3,12,'Vede, irmãos, que nunca haja em qualquer de vós um coração mau e infiel, para se apartar do Deus vivo.'),
('acf','hb',3,13,'Antes, exortai-vos uns aos outros todos os dias, durante o tempo que se chama Hoje, para que nenhum de vós se endureça pelo engano do pecado;'),
('acf','hb',3,14,'Porque nos tornamos participantes de Cristo, se retivermos firmemente o princípio da nossa confiança até ao fim.'),
('acf','hb',3,15,'Enquanto se diz: Hoje, se ouvirdes a sua voz, Não endureçais os vossos corações, como na provocação.'),
('acf','hb',3,16,'Porque, havendo-a alguns ouvido, o provocaram; mas não todos os que saíram do Egito por meio de Moisés.'),
('acf','hb',3,17,'Mas com quem se indignou por quarenta anos? Não foi porventura com os que pecaram, cujos corpos caíram no deserto?'),
('acf','hb',3,18,'E a quem jurou que não entrariam no seu repouso, senão aos que foram desobedientes?'),
('acf','hb',3,19,'E vemos que não puderam entrar por causa da sua incredulidade.'),
('acf','hb',4,1,'Temamos, pois, que, porventura, deixada a promessa de entrar no seu repouso, pareça que algum de vós fica para trás.'),
('acf','hb',4,2,'Porque também a nós foram pregadas as boas novas, como a eles, mas a palavra da pregação nada lhes aproveitou, porquanto não estava misturada com a fé naqueles que a ouviram.'),
('acf','hb',4,3,'Porque nós, os que temos crido, entramos no repouso, tal como disse:Assim jurei na minha ira Que não entrarão no meu repouso; embora as suas obras estivessem acabadas desde a fundação do mundo.'),
('acf','hb',4,4,'Porque em certo lugar disse assim do dia sétimo: E repousou Deus de todas as suas obras no sétimo dia.'),
('acf','hb',4,5,'E outra vez neste lugar:Não entrarão no meu repouso.'),
('acf','hb',4,6,'Visto, pois, que resta que alguns entrem nele, e que aqueles a quem primeiro foram pregadas as boas novas não entraram por causa da desobediência,'),
('acf','hb',4,7,'Determina outra vez um certo dia, Hoje, dizendo por Davi, muito tempo depois, como está dito: Hoje, se ouvirdes a sua voz, Não endureçais os vossos corações.'),
('acf','hb',4,8,'Porque, se Josué lhes houvesse dado repouso, não falaria depois disso de outro dia.'),
('acf','hb',4,9,'Portanto, resta ainda um repouso para o povo de Deus.'),
('acf','hb',4,10,'Porque aquele que entrou no seu repouso, ele próprio repousou de suas obras, como Deus das suas.'),
('acf','hb',4,11,'Procuremos, pois, entrar naquele repouso, para que ninguém caia no mesmo exemplo de desobediência.'),
('acf','hb',4,12,'Porque a palavra de Deus é viva e eficaz, e mais penetrante do que espada alguma de dois gumes, e penetra até à divisão da alma e do espírito, e das juntas e medulas, e é apta para discernir os pensamentos e intenções do coração.'),
('acf','hb',4,13,'E não há criatura alguma encoberta diante dele; antes todas as coisas estão nuas e patentes aos olhos daquele com quem temos de tratar.'),
('acf','hb',4,14,'Visto que temos um grande sumo sacerdote, Jesus, Filho de Deus, que penetrou nos céus, retenhamos firmemente a nossa confissão.'),
('acf','hb',4,15,'Porque não temos um sumo sacerdote que não possa compadecer-se das nossas fraquezas; porém, um que, como nós, em tudo foi tentado, mas sem pecado.'),
('acf','hb',4,16,'Cheguemos, pois, com confiança ao trono da graça, para que possamos alcançar misericórdia e achar graça, a fim de sermos ajudados em tempo oportuno.'),
('acf','hb',5,1,'Porque todo o sumo sacerdote, tomado dentre os homens, é constituído a favor dos homens nas coisas concernentes a Deus, para que ofereça dons e sacrifícios pelos pecados;'),
('acf','hb',5,2,'E possa compadecer-se ternamente dos ignorantes e errados; pois também ele mesmo está rodeado de fraqueza.'),
('acf','hb',5,3,'E por esta causa deve ele, tanto pelo povo, como também por si mesmo, fazer oferta pelos pecados.'),
('acf','hb',5,4,'E ninguém toma para si esta honra, senão o que é chamado por Deus, como Arão.'),
('acf','hb',5,5,'Assim também Cristo não se glorificou a si mesmo, para se fazer sumo sacerdote, mas aquele que lhe disse: Tu és meu Filho,Hoje te gerei.'),
('acf','hb',5,6,'Como também diz, noutro lugar: Tu és sacerdote eternamente, Segundo a ordem de Melquisedeque.'),
('acf','hb',5,7,'O qual, nos dias da sua carne, oferecendo, com grande clamor e lágrimas, orações e súplicas ao que o podia livrar da morte, foi ouvido quanto ao que temia.'),
('acf','hb',5,8,'Ainda que era Filho, aprendeu a obediência, por aquilo que padeceu.'),
('acf','hb',5,9,'E, sendo ele consumado, veio a ser a causa da eterna salvação para todos os que lhe obedecem;'),
('acf','hb',5,10,'Chamado por Deus sumo sacerdote, segundo a ordem de Melquisedeque.'),
('acf','hb',5,11,'Do qual muito temos que dizer, de difícil interpretação; porquanto vos fizestes negligentes para ouvir.'),
('acf','hb',5,12,'Porque, devendo já ser mestres pelo tempo, ainda necessitais de que se vos torne a ensinar quais sejam os primeiros rudimentos das palavras de Deus; e vos haveis feito tais que necessitais de leite, e não de sólido mantimento.'),
('acf','hb',5,13,'Porque qualquer que ainda se alimenta de leite não está experimentado na palavra da justiça, porque é menino.'),
('acf','hb',5,14,'Mas o mantimento sólido é para os perfeitos, os quais, em razão do costume, têm os sentidos exercitados para discernir tanto o bem como o mal.'),
('acf','hb',6,1,'Por isso, deixando os rudimentos da doutrina de Cristo, prossigamos até à perfeição, não lançando de novo o fundamento do arrependimento de obras mortas e de fé em Deus,'),
('acf','hb',6,2,'E da doutrina dos batismos, e da imposição das mãos, e da ressurreição dos mortos, e do juízo eterno.'),
('acf','hb',6,3,'E isto faremos, se Deus o permitir.'),
('acf','hb',6,4,'Porque é impossível que os que já uma vez foram iluminados, e provaram o dom celestial, e se fizeram participantes do Espírito Santo,'),
('acf','hb',6,5,'E provaram a boa palavra de Deus, e as virtudes do século futuro,'),
('acf','hb',6,6,'E recaíram, sejam outra vez renovados para arrependimento; pois assim, quanto a eles, de novo crucificam o Filho de Deus, e o expõem ao vitupério.'),
('acf','hb',6,7,'Porque a terra que embebe a chuva, que muitas vezes cai sobre ela, e produz erva proveitosa para aqueles por quem é lavrada, recebe a bênção de Deus;'),
('acf','hb',6,8,'Mas a que produz espinhos e abrolhos, é reprovada, e perto está da maldição; o seu fim é ser queimada.'),
('acf','hb',6,9,'Mas de vós, ó amados, esperamos coisas melhores, e coisas que acompanham a salvação, ainda que assim falamos.'),
('acf','hb',6,10,'Porque Deus não é injusto para se esquecer da vossa obra, e do trabalho do amor que para com o seu nome mostrastes, enquanto servistes aos santos; e ainda servis.'),
('acf','hb',6,11,'Mas desejamos que cada um de vós mostre o mesmo cuidado até ao fim, para completa certeza da esperança;'),
('acf','hb',6,12,'Para que vos não façais negligentes, mas sejais imitadores dos que pela fé e paciência herdam as promessas.'),
('acf','hb',6,13,'Porque, quando Deus fez a promessa a Abraão, como não tinha outro maior por quem jurasse, jurou por si mesmo,'),
('acf','hb',6,14,'Dizendo: Certamente, abençoando te abençoarei, e multiplicando te multiplicarei.'),
('acf','hb',6,15,'E assim, esperando com paciência, alcançou a promessa.'),
('acf','hb',6,16,'Porque os homens certamente juram por alguém superior a eles, e o juramento para confirmação é, para eles, o fim de toda a contenda.'),
('acf','hb',6,17,'Por isso, querendo Deus mostrar mais abundantemente a imutabilidade do seu conselho aos herdeiros da promessa, se interpôs com juramento;'),
('acf','hb',6,18,'Para que por duas coisas imutáveis, nas quais é impossível que Deus minta, tenhamos a firme consolação, nós, os que pomos o nosso refúgio em reter a esperança proposta;'),
('acf','hb',6,19,'A qual temos como âncora da alma, segura e firme, e que penetra até ao interior do véu,'),
('acf','hb',6,20,'Onde Jesus, nosso precursor, entrou por nós, feito eternamente sumo sacerdote, segundo a ordem de Melquisedeque.'),
('acf','hb',7,1,'Porque este Melquisedeque, que era rei de Salém, sacerdote do Deus Altíssimo, e que saiu ao encontro de Abraão quando ele regressava da matança dos reis, e o abençoou;'),
('acf','hb',7,2,'A quem também Abraão deu o dízimo de tudo, e primeiramente é, por interpretação, rei de justiça, e depois também rei de Salém, que é rei de paz;'),
('acf','hb',7,3,'Sem pai, sem mãe, sem genealogia, não tendo princípio de dias nem fim de vida, mas sendo feito semelhante ao Filho de Deus, permanece sacerdote para sempre.'),
('acf','hb',7,4,'Considerai, pois, quão grande era este, a quem até o patriarca Abraão deu os dízimos dos despojos.'),
('acf','hb',7,5,'E os que dentre os filhos de Levi recebem o sacerdócio têm ordem, segundo a lei, de tomar o dízimo do povo, isto é, de seus irmãos, ainda que tenham saído dos lombos de Abraão.'),
('acf','hb',7,6,'Mas aquele, cuja genealogia não é contada entre eles, tomou dízimos de Abraão, e abençoou o que tinha as promessas.'),
('acf','hb',7,7,'Ora, sem contradição alguma, o menor é abençoado pelo maior.'),
('acf','hb',7,8,'E aqui certamente tomam dízimos homens que morrem; ali, porém, aquele de quem se testifica que vive.'),
('acf','hb',7,9,'E, por assim dizer, por meio de Abraão, até Levi, que recebe dízimos, pagou dízimos.'),
('acf','hb',7,10,'Porque ainda ele estava nos lombos de seu pai quando Melquisedeque lhe saiu ao encontro.'),
('acf','hb',7,11,'De sorte que, se a perfeição fosse pelo sacerdócio levítico (porque sob ele o povo recebeu a lei), que necessidade havia logo de que outro sacerdote se levantasse, segundo a ordem de Melquisedeque, e não fosse chamado segundo a ordem de Arão?'),
('acf','hb',7,12,'Porque, mudando-se o sacerdócio, necessariamente se faz também mudança da lei.'),
('acf','hb',7,13,'Porque aquele de quem estas coisas se dizem pertence a outra tribo, da qual ninguém serviu ao altar,'),
('acf','hb',7,14,'Visto ser manifesto que nosso Senhor procedeu de Judá, e concernente a essa tribo nunca Moisés falou de sacerdócio.'),
('acf','hb',7,15,'E muito mais manifesto é ainda, se à semelhança de Melquisedeque se levantar outro sacerdote,'),
('acf','hb',7,16,'Que não foi feito segundo a lei do mandamento carnal, mas segundo a virtude da vida incorruptível.'),
('acf','hb',7,17,'Porque ele assim testifica: Tu és sacerdote eternamente, Segundo a ordem de Melquisedeque.'),
('acf','hb',7,18,'Porque o precedente mandamento é abrogado por causa da sua fraqueza e inutilidade'),
('acf','hb',7,19,'(Pois a lei nenhuma coisa aperfeiçoou) e desta sorte é introduzida uma melhor esperança, pela qual chegamos a Deus.'),
('acf','hb',7,20,'E visto como não é sem prestar juramento (porque certamente aqueles, sem juramento, foram feitos sacerdotes,'),
('acf','hb',7,21,'Mas este com juramento por aquele que lhe disse: Jurou o Senhor, e não se arrependerá; Tu és sacerdote eternamente, Segundo a ordem de Melquisedeque,'),
('acf','hb',7,22,'De tanto melhor aliança Jesus foi feito fiador.'),
('acf','hb',7,23,'E, na verdade, aqueles foram feitos sacerdotes em grande número, porque pela morte foram impedidos de permanecer,'),
('acf','hb',7,24,'Mas este, porque permanece eternamente, tem um sacerdócio perpétuo.'),
('acf','hb',7,25,'Portanto, pode também salvar perfeitamente os que por ele se chegam a Deus, vivendo sempre para interceder por eles.'),
('acf','hb',7,26,'Porque nos convinha tal sumo sacerdote, santo, inocente, imaculado, separado dos pecadores, e feito mais sublime do que os céus;'),
('acf','hb',7,27,'Que não necessitasse, como os sumos sacerdotes, de oferecer cada dia sacrifícios, primeiramente por seus próprios pecados, e depois pelos do povo; porque isto fez ele, uma vez, oferecendo-se a si mesmo.'),
('acf','hb',7,28,'Porque a lei constitui sumos sacerdotes a homens fracos, mas a palavra do juramento, que veio depois da lei, constitui ao Filho, perfeito para sempre.'),
('acf','hb',8,1,'Ora, a suma do que temos dito é que temos um sumo sacerdote tal, que está assentado nos céus à destra do trono da majestade,'),
('acf','hb',8,2,'Ministro do santuário, e do verdadeiro tabernáculo, o qual o Senhor fundou, e não o homem.'),
('acf','hb',8,3,'Porque todo o sumo sacerdote é constituído para oferecer dons e sacrifícios; por isso era necessário que este também tivesse alguma coisa que oferecer.'),
('acf','hb',8,4,'Ora, se ele estivesse na terra, nem tão pouco sacerdote seria, havendo ainda sacerdotes que oferecem dons segundo a lei,'),
('acf','hb',8,5,'Os quais servem de exemplo e sombra das coisas celestiais, como Moisés divinamente foi avisado, estando já para acabar o tabernáculo; porque foi dito: Olha, faze tudo conforme o modelo que no monte se te mostrou.'),
('acf','hb',8,6,'Mas agora alcançou ele ministério tanto mais excelente, quanto é mediador de uma melhor aliança que está confirmada em melhores promessas.'),
('acf','hb',8,7,'Porque, se aquela primeira fora irrepreensível, nunca se teria buscado lugar para a segunda.'),
('acf','hb',8,8,'Porque, repreendendo-os, lhes diz: Eis que virão dias, diz o Senhor, Em que com a casa de Israel e com a casa de Judá estabelecerei uma nova aliança,'),
('acf','hb',8,9,'Não segundo a aliança que fiz com seus pais No dia em que os tomei pela mão, para os tirar da terra do Egito;Como não permaneceram naquela minha aliança,Eu para eles não atentei, diz o Senhor.'),
('acf','hb',8,10,'Porque esta é a aliança que depois daqueles diasFarei com a casa de Israel, diz o Senhor; Porei as minhas leis no seu entendimento, E em seu coração as escreverei; E eu lhes serei por Deus, E eles me serão por povo;'),
('acf','hb',8,11,'E não ensinará cada um a seu próximo, Nem cada um ao seu irmão, dizendo: Conhece o Senhor; Porque todos me conhecerão, Desde o menor deles até ao maior.'),
('acf','hb',8,12,'Porque serei misericordioso para com suas iniqüidades, E de seus pecados e de suas prevaricações não me lembrarei mais.'),
('acf','hb',8,13,'Dizendo Nova aliança, envelheceu a primeira. Ora, o que foi tornado velho, e se envelhece, perto está de acabar.'),
('acf','hb',9,1,'Ora, também a primeira tinha ordenanças de culto divino, e um santuário terrestre.'),
('acf','hb',9,2,'Porque um tabernáculo estava preparado, o primeiro, em que havia o candeeiro, e a mesa, e os pães da proposição; ao que se chama o santuário.'),
('acf','hb',9,3,'Mas depois do segundo véu estava o tabernáculo que se chama o santo dos santos,'),
('acf','hb',9,4,'Que tinha o incensário de ouro, e a arca da aliança, coberta de ouro toda em redor; em que estava um vaso de ouro, que continha o maná, e a vara de Arão, que tinha florescido, e as tábuas da aliança;'),
('acf','hb',9,5,'E sobre a arca os querubins da glória, que faziam sombra no propiciatório; das quais coisas não falaremos agora particularmente.'),
('acf','hb',9,6,'Ora, estando estas coisas assim preparadas, a todo o tempo entravam os sacerdotes no primeiro tabernáculo, cumprindo os serviços;'),
('acf','hb',9,7,'Mas, no segundo, só o sumo sacerdote, uma vez no ano, não sem sangue, que oferecia por si mesmo e pelas culpas do povo;'),
('acf','hb',9,8,'Dando nisto a entender o Espírito Santo que ainda o caminho do santuário não estava descoberto enquanto se conservava em pé o primeiro tabernáculo,'),
('acf','hb',9,9,'Que é uma alegoria para o tempo presente, em que se oferecem dons e sacrifícios que, quanto à consciência, não podem aperfeiçoar aquele que faz o serviço;'),
('acf','hb',9,10,'Consistindo somente em comidas, e bebidas, e várias abluções e justificações da carne, impostas até ao tempo da correção.'),
('acf','hb',9,11,'Mas, vindo Cristo, o sumo sacerdote dos bens futuros, por um maior e mais perfeito tabernáculo, não feito por mãos, isto é, não desta criação,'),
('acf','hb',9,12,'Nem por sangue de bodes e bezerros, mas por seu próprio sangue, entrou uma vez no santuário, havendo efetuado uma eterna redenção.'),
('acf','hb',9,13,'Porque, se o sangue dos touros e bodes, e a cinza de uma novilha esparzida sobre os imundos, os santifica, quanto à purificação da carne,'),
('acf','hb',9,14,'Quanto mais o sangue de Cristo, que pelo Espírito eterno se ofereceu a si mesmo imaculado a Deus, purificará as vossas consciências das obras mortas, para servirdes ao Deus vivo?'),
('acf','hb',9,15,'E por isso é Mediador de um novo testamento, para que, intervindo a morte para remissão das transgressões que havia debaixo do primeiro testamento, os chamados recebam a promessa da herança eterna.'),
('acf','hb',9,16,'Porque onde há testamento, é necessário que intervenha a morte do testador.'),
('acf','hb',9,17,'Porque um testamento tem força onde houve morte; ou terá ele algum valor enquanto o testador vive?'),
('acf','hb',9,18,'Por isso também o primeiro não foi consagrado sem sangue;'),
('acf','hb',9,19,'Porque, havendo Moisés anunciado a todo o povo todos os mandamentos segundo a lei, tomou o sangue dos bezerros e dos bodes, com água, lã purpúrea e hissopo, e aspergiu tanto o mesmo livro como todo o povo,'),
('acf','hb',9,20,'Dizendo: Este é o sangue do testamento que Deus vos tem mandado.'),
('acf','hb',9,21,'E semelhantemente aspergiu com sangue o tabernáculo e todos os vasos do ministério.'),
('acf','hb',9,22,'E quase todas as coisas, segundo a lei, se purificam com sangue; e sem derramamento de sangue não há remissão.'),
('acf','hb',9,23,'De sorte que era bem necessário que as figuras das coisas que estão no céu assim se purificassem; mas as próprias coisas celestiais com sacrifícios melhores do que estes.'),
('acf','hb',9,24,'Porque Cristo não entrou num santuário feito por mãos, figura do verdadeiro, porém no mesmo céu, para agora comparecer por nós perante a face de Deus;'),
('acf','hb',9,25,'Nem também para a si mesmo se oferecer muitas vezes, como o sumo sacerdote cada ano entra no santuário com sangue alheio;'),
('acf','hb',9,26,'De outra maneira, necessário lhe fora padecer muitas vezes desde a fundação do mundo. Mas agora na consumação dos séculos uma vez se manifestou, para aniquilar o pecado pelo sacrifício de si mesmo.'),
('acf','hb',9,27,'E, como aos homens está ordenado morrerem uma vez, vindo depois disso o juízo,'),
('acf','hb',9,28,'Assim também Cristo, oferecendo-se uma vez para tirar os pecados de muitos, aparecerá segunda vez, sem pecado, aos que o esperam para salvação.'),
('acf','hb',10,1,'Porque tendo a lei a sombra dos bens futuros, e não a imagem exata das coisas, nunca, pelos mesmos sacrifícios que continuamente se oferecem cada ano, pode aperfeiçoar os que a eles se chegam.'),
('acf','hb',10,2,'Doutra maneira, teriam deixado de se oferecer, porque, purificados uma vez os ministrantes, nunca mais teriam consciência de pecado.'),
('acf','hb',10,3,'Nesses sacrifícios, porém, cada ano se faz comemoração dos pecados,'),
('acf','hb',10,4,'Porque é impossível que o sangue dos touros e dos bodes tire os pecados.'),
('acf','hb',10,5,'Por isso, entrando no mundo, diz: Sacrifício e oferta não quiseste, Mas corpo me preparaste;'),
('acf','hb',10,6,'Holocaustos e oblações pelo pecado não te agradaram.'),
('acf','hb',10,7,'Então disse: Eis aqui venho(No princípio do livro está escrito de mim),Para fazer, ó Deus, a tua vontade.'),
('acf','hb',10,8,'Como acima diz: Sacrifício e oferta, e holocaustos e oblações pelo pecado não quiseste, nem te agradaram (os quais se oferecem segundo a lei).'),
('acf','hb',10,9,'Então disse: Eis aqui venho, para fazer, ó Deus, a tua vontade. Tira o primeiro, para estabelecer o segundo.'),
('acf','hb',10,10,'Na qual vontade temos sido santificados pela oblação do corpo de Jesus Cristo, feita uma vez.'),
('acf','hb',10,11,'E assim todo o sacerdote aparece cada dia, ministrando e oferecendo muitas vezes os mesmos sacrifícios, que nunca podem tirar os pecados;'),
('acf','hb',10,12,'Mas este, havendo oferecido para sempre um único sacrifício pelos pecados, está assentado à destra de Deus,'),
('acf','hb',10,13,'Daqui em diante esperando até que os seus inimigos sejam postos por escabelo de seus pés.'),
('acf','hb',10,14,'Porque com uma só oblação aperfeiçoou para sempre os que são santificados.'),
('acf','hb',10,15,'E também o Espírito Santo no-lo testifica, porque depois de haver dito:'),
('acf','hb',10,16,'Esta é a aliança que farei com eles Depois daqueles dias, diz o Senhor:Porei as minhas leis em seus corações,E as escreverei em seus entendimentos; acrescenta:'),
('acf','hb',10,17,'E jamais me lembrarei de seus pecados e de suas iniqüidades.'),
('acf','hb',10,18,'Ora, onde há remissão destes, não há mais oblação pelo pecado.'),
('acf','hb',10,19,'Tendo, pois, irmãos, ousadia para entrar no santuário, pelo sangue de Jesus,'),
('acf','hb',10,20,'Pelo novo e vivo caminho que ele nos consagrou, pelo véu, isto é, pela sua carne,'),
('acf','hb',10,21,'E tendo um grande sacerdote sobre a casa de Deus,'),
('acf','hb',10,22,'Cheguemo-nos com verdadeiro coração, em inteira certeza de fé, tendo os corações purificados da má consciência, e o corpo lavado com água limpa,'),
('acf','hb',10,23,'Retenhamos firmes a confissão da nossa esperança; porque fiel é o que prometeu.'),
('acf','hb',10,24,'E consideremo-nos uns aos outros, para nos estimularmos ao amor e às boas obras,'),
('acf','hb',10,25,'Não deixando a nossa congregação, como é costume de alguns, antes admoestando-nos uns aos outros; e tanto mais, quanto vedes que se vai aproximando aquele dia.'),
('acf','hb',10,26,'Porque, se pecarmos voluntariamente, depois de termos recebido o conhecimento da verdade, já não resta mais sacrifício pelos pecados,'),
('acf','hb',10,27,'Mas uma certa expectação horrível de juízo, e ardor de fogo, que há de devorar os adversários.'),
('acf','hb',10,28,'Quebrantando alguém a lei de Moisés, morre sem misericórdia, só pela palavra de duas ou três testemunhas.'),
('acf','hb',10,29,'De quanto maior castigo cuidais vós será julgado merecedor aquele que pisar o Filho de Deus, e tiver por profano o sangue da aliança com que foi santificado, e fizer agravo ao Espírito da graça?'),
('acf','hb',10,30,'Porque bem conhecemos aquele que disse: Minha é a vingança, eu darei a recompensa, diz o Senhor. E outra vez: O Senhor julgará o seu povo.'),
('acf','hb',10,31,'Horrenda coisa é cair nas mãos do Deus vivo.'),
('acf','hb',10,32,'Lembrai-vos, porém, dos dias passados, em que, depois de serdes iluminados, suportastes grande combate de aflições.'),
('acf','hb',10,33,'Em parte fostes feitos espetáculo com vitupérios e tribulações, e em parte fostes participantes com os que assim foram tratados.'),
('acf','hb',10,34,'Porque também vos compadecestes das minhas prisões, e com alegria permitistes o roubo dos vossos bens, sabendo que em vós mesmos tendes nos céus uma possessão melhor e permanente.'),
('acf','hb',10,35,'Não rejeiteis, pois, a vossa confiança, que tem grande e avultado galardão.'),
('acf','hb',10,36,'Porque necessitais de paciência, para que, depois de haverdes feito a vontade de Deus, possais alcançar a promessa.'),
('acf','hb',10,37,'Porque ainda um pouquinho de tempo, E o que há de vir virá, e não tardará.'),
('acf','hb',10,38,'Mas o justo viverá pela fé; E, se ele recuar, a minha alma não tem prazer nele.'),
('acf','hb',10,39,'Nós, porém, não somos daqueles que se retiram para a perdição, mas daqueles que crêem para a conservação da alma.'),
('acf','hb',11,1,'Ora, a fé é o firme fundamento das coisas que se esperam, e a prova das coisas que se não vêem.'),
('acf','hb',11,2,'Porque por ela os antigos alcançaram testemunho.'),
('acf','hb',11,3,'Pela fé entendemos que os mundos pela palavra de Deus foram criados; de maneira que aquilo que se vê não foi feito do que é aparente.'),
('acf','hb',11,4,'Pela fé Abel ofereceu a Deus maior sacrifício do que Caim, pelo qual alcançou testemunho de que era justo, dando Deus testemunho dos seus dons, e por ela, depois de morto, ainda fala.'),
('acf','hb',11,5,'Pela fé Enoque foi trasladado para não ver a morte, e não foi achado, porque Deus o trasladara; visto como antes da sua trasladação alcançou testemunho de que agradara a Deus.'),
('acf','hb',11,6,'Ora, sem fé é impossível agradar-lhe; porque é necessário que aquele que se aproxima de Deus creia que ele existe, e que é galardoador dos que o buscam.'),
('acf','hb',11,7,'Pela fé Noé, divinamente avisado das coisas que ainda não se viam, temeu e, para salvação da sua família, preparou a arca, pela qual condenou o mundo, e foi feito herdeiro da justiça que é segundo a fé.'),
('acf','hb',11,8,'Pela fé Abraão, sendo chamado, obedeceu, indo para um lugar que havia de receber por herança; e saiu, sem saber para onde ia.'),
('acf','hb',11,9,'Pela fé habitou na terra da promessa, como em terra alheia, morando em cabanas com Isaque e Jacó, herdeiros com ele da mesma promessa.'),
('acf','hb',11,10,'Porque esperava a cidade que tem fundamentos, da qual o artífice e construtor é Deus.'),
('acf','hb',11,11,'Pela fé também a mesma Sara recebeu a virtude de conceber, e deu à luz já fora da idade; porquanto teve por fiel aquele que lho tinha prometido.'),
('acf','hb',11,12,'Por isso também de um, e esse já amortecido, descenderam tantos, em multidão, como as estrelas do céu, e como a areia inumerável que está na praia do mar.'),
('acf','hb',11,13,'Todos estes morreram na fé, sem terem recebido as promessas; mas vendo-as de longe, e crendo-as e abraçando-as, confessaram que eram estrangeiros e peregrinos na terra.'),
('acf','hb',11,14,'Porque, os que isto dizem, claramente mostram que buscam uma pátria.'),
('acf','hb',11,15,'E se, na verdade, se lembrassem daquela de onde haviam saído, teriam oportunidade de tornar.'),
('acf','hb',11,16,'Mas agora desejam uma melhor, isto é, a celestial. Por isso também Deus não se envergonha deles, de se chamar seu Deus, porque já lhes preparou uma cidade.'),
('acf','hb',11,17,'Pela fé ofereceu Abraão a Isaque, quando foi provado; sim, aquele que recebera as promessas ofereceu o seu unigênito.'),
('acf','hb',11,18,'Sendo-lhe dito: Em Isaque será chamada a tua descendência, considerou que Deus era poderoso para até dentre os mortos o ressuscitar;'),
('acf','hb',11,19,'E daí também em figura ele o recobrou.'),
('acf','hb',11,20,'Pela fé Isaque abençoou Jacó e Esaú, no tocante às coisas futuras.'),
('acf','hb',11,21,'Pela fé Jacó, próximo da morte, abençoou cada um dos filhos de José, e adorou encostado à ponta do seu bordão.'),
('acf','hb',11,22,'Pela fé José, próximo da morte, fez menção da saída dos filhos de Israel, e deu ordem acerca de seus ossos.'),
('acf','hb',11,23,'Pela fé Moisés, já nascido, foi escondido três meses por seus pais, porque viram que era um menino formoso; e não temeram o mandamento do rei.'),
('acf','hb',11,24,'Pela fé Moisés, sendo já grande, recusou ser chamado filho da filha de Faraó,'),
('acf','hb',11,25,'Escolhendo antes ser maltratado com o povo de Deus, do que por um pouco de tempo ter o gozo do pecado;'),
('acf','hb',11,26,'Tendo por maiores riquezas o vitupério de Cristo do que os tesouros do Egito; porque tinha em vista a recompensa.'),
('acf','hb',11,27,'Pela fé deixou o Egito, não temendo a ira do rei; porque ficou firme, como vendo o invisível.'),
('acf','hb',11,28,'Pela fé celebrou a páscoa e a aspersão do sangue, para que o destruidor dos primogênitos lhes não tocasse.'),
('acf','hb',11,29,'Pela fé passaram o Mar Vermelho, como por terra seca; o que intentando os egípcios, se afogaram.'),
('acf','hb',11,30,'Pela fé caíram os muros de Jericó, sendo rodeados durante sete dias.'),
('acf','hb',11,31,'Pela fé Raabe, a meretriz, não pereceu com os incrédulos, acolhendo em paz os espias.'),
('acf','hb',11,32,'E que mais direi? Faltar-me-ia o tempo contando de Gideão, e de Baraque, e de Sansão, e de Jefté, e de Davi, e de Samuel e dos profetas,'),
('acf','hb',11,33,'Os quais pela fé venceram reinos, praticaram a justiça, alcançaram promessas, fecharam as bocas dos leões,'),
('acf','hb',11,34,'Apagaram a força do fogo, escaparam do fio da espada, da fraqueza tiraram forças, na batalha se esforçaram, puseram em fuga os exércitos dos estranhos.'),
('acf','hb',11,35,'As mulheres receberam pela ressurreição os seus mortos; uns foram torturados, não aceitando o seu livramento, para alcançarem uma melhor ressurreição;'),
('acf','hb',11,36,'E outros experimentaram escárnios e açoites, e até cadeias e prisões.'),
('acf','hb',11,37,'Foram apedrejados, serrados, tentados, mortos ao fio da espada; andaram vestidos de peles de ovelhas e de cabras, desamparados, aflitos e maltratados'),
('acf','hb',11,38,'(Dos quais o mundo não era digno), errantes pelos desertos, e montes, e pelas covas e cavernas da terra.'),
('acf','hb',11,39,'E todos estes, tendo tido testemunho pela fé, não alcançaram a promessa,'),
('acf','hb',11,40,'Provendo Deus alguma coisa melhor a nosso respeito, para que eles sem nós não fossem aperfeiçoados.'),
('acf','hb',12,1,'Portanto nós também, pois que estamos rodeados de uma tão grande nuvem de testemunhas, deixemos todo o embaraço, e o pecado que tão de perto nos rodeia, e corramos com paciência a carreira que nos está proposta,'),
('acf','hb',12,2,'Olhando para Jesus, autor e consumador da fé, o qual, pelo gozo que lhe estava proposto, suportou a cruz, desprezando a afronta, e assentou-se à destra do trono de Deus.'),
('acf','hb',12,3,'Considerai, pois, aquele que suportou tais contradições dos pecadores contra si mesmo, para que não enfraqueçais, desfalecendo em vossos ânimos.'),
('acf','hb',12,4,'Ainda não resististes até ao sangue, combatendo contra o pecado.'),
('acf','hb',12,5,'E já vos esquecestes da exortação que argumenta convosco como filhos: Filho meu, não desprezes a correção do Senhor, E não desmaies quando por ele fores repreendido;'),
('acf','hb',12,6,'Porque o Senhor corrige o que ama,E açoita a qualquer que recebe por filho.'),
('acf','hb',12,7,'Se suportais a correção, Deus vos trata como filhos; porque, que filho há a quem o pai não corrija?'),
('acf','hb',12,8,'Mas, se estais sem disciplina, da qual todos são feitos participantes, sois então bastardos, e não filhos.'),
('acf','hb',12,9,'Além do que, tivemos nossos pais segundo a carne, para nos corrigirem, e nós os reverenciamos; não nos sujeitaremos muito mais ao Pai dos espíritos, para vivermos?'),
('acf','hb',12,10,'Porque aqueles, na verdade, por um pouco de tempo, nos corrigiam como bem lhes parecia; mas este, para nosso proveito, para sermos participantes da sua santidade.'),
('acf','hb',12,11,'E, na verdade, toda a correção, ao presente, não parece ser de gozo, senão de tristeza, mas depois produz um fruto pacífico de justiça nos exercitados por ela.'),
('acf','hb',12,12,'Portanto, tornai a levantar as mãos cansadas, e os joelhos desconjuntados,'),
('acf','hb',12,13,'E fazei veredas direitas para os vossos pés, para que o que manqueja não se desvie inteiramente, antes seja sarado.'),
('acf','hb',12,14,'Segui a paz com todos, e a santificação, sem a qual ninguém verá o Senhor;'),
('acf','hb',12,15,'Tendo cuidado de que ninguém se prive da graça de Deus, e de que nenhuma raiz de amargura, brotando, vos perturbe, e por ela muitos se contaminem.'),
('acf','hb',12,16,'E ninguém seja devasso, ou profano, como Esaú, que por uma refeição vendeu o seu direito de primogenitura.'),
('acf','hb',12,17,'Porque bem sabeis que, querendo ele ainda depois herdar a bênção, foi rejeitado, porque não achou lugar de arrependimento, ainda que com lágrimas o buscou.'),
('acf','hb',12,18,'Porque não chegastes ao monte palpável, aceso em fogo, e à escuridão, e às trevas, e à tempestade,'),
('acf','hb',12,19,'E ao sonido da trombeta, e à voz das palavras, a qual os que a ouviram pediram que se lhes não falasse mais;'),
('acf','hb',12,20,'Porque não podiam suportar o que se lhes mandava: Se até um animal tocar o monte será apedrejado ou passado com um dardo.'),
('acf','hb',12,21,'E tão terrível era a visão, que Moisés disse: Estou todo assombrado, e tremendo.'),
('acf','hb',12,22,'Mas chegastes ao monte Sião, e à cidade do Deus vivo, à Jerusalém celestial, e aos muitos milhares de anjos;'),
('acf','hb',12,23,'À universal assembléia e igreja dos primogênitos, que estão inscritos nos céus, e a Deus, o juiz de todos, e aos espíritos dos justos aperfeiçoados;'),
('acf','hb',12,24,'E a Jesus, o Mediador de uma nova aliança, e ao sangue da aspersão, que fala melhor do que o de Abel.'),
('acf','hb',12,25,'Vede que não rejeiteis ao que fala; porque, se não escaparam aqueles que rejeitaram o que na terra os advertia, muito menos nós, se nos desviarmos daquele que é dos céus;'),
('acf','hb',12,26,'A voz do qual moveu então a terra, mas agora anunciou, dizendo: Ainda uma vez comoverei, não só a terra, senão também o céu.'),
('acf','hb',12,27,'E esta palavra: Ainda uma vez, mostra a mudança das coisas móveis, como coisas feitas, para que as imóveis permaneçam.'),
('acf','hb',12,28,'Por isso, tendo recebido um reino que não pode ser abalado, retenhamos a graça, pela qual sirvamos a Deus agradavelmente, com reverência e piedade;'),
('acf','hb',12,29,'Porque o nosso Deus é um fogo consumidor.'),
('acf','hb',13,1,'Permaneça o amor fraternal.'),
('acf','hb',13,2,'Não vos esqueçais da hospitalidade, porque por ela alguns, não o sabendo, hospedaram anjos.'),
('acf','hb',13,3,'Lembrai-vos dos presos, como se estivésseis presos com eles, e dos maltratados, como sendo-o vós mesmos também no corpo.'),
('acf','hb',13,4,'Venerado seja entre todos o matrimônio e o leito sem mácula; porém, aos que se dão à prostituição, e aos adúlteros, Deus os julgará.'),
('acf','hb',13,5,'Sejam vossos costumes sem avareza, contentando-vos com o que tendes; porque ele disse: Não te deixarei, nem te desampararei.'),
('acf','hb',13,6,'E assim com confiança ousemos dizer: O Senhor é o meu ajudador, e não temerei O que me possa fazer o homem.'),
('acf','hb',13,7,'Lembrai-vos dos vossos pastores, que vos falaram a palavra de Deus, a fé dos quais imitai, atentando para a sua maneira de viver.'),
('acf','hb',13,8,'Jesus Cristo é o mesmo, ontem, e hoje, e eternamente.'),
('acf','hb',13,9,'Não vos deixeis levar em redor por doutrinas várias e estranhas, porque bom é que o coração se fortifique com graça, e não com alimentos que de nada aproveitaram aos que a eles se entregaram.'),
('acf','hb',13,10,'Temos um altar, de que não têm direito de comer os que servem ao tabernáculo.'),
('acf','hb',13,11,'Porque os corpos dos animais, cujo sangue é, pelo pecado, trazido pelo sumo sacerdote para o santuário, são queimados fora do arraial.'),
('acf','hb',13,12,'E por isso também Jesus, para santificar o povo pelo seu próprio sangue, padeceu fora da porta.'),
('acf','hb',13,13,'Saiamos, pois, a ele fora do arraial, levando o seu vitupério.'),
('acf','hb',13,14,'Porque não temos aqui cidade permanente, mas buscamos a futura.'),
('acf','hb',13,15,'Portanto, ofereçamos sempre por ele a Deus sacrifício de louvor, isto é, o fruto dos lábios que confessam o seu nome.'),
('acf','hb',13,16,'E não vos esqueçais da beneficência e comunicação, porque com tais sacrifícios Deus se agrada.'),
('acf','hb',13,17,'Obedecei a vossos pastores, e sujeitai-vos a eles; porque velam por vossas almas, como aqueles que hão de dar conta delas; para que o façam com alegria e não gemendo, porque isso não vos seria útil.'),
('acf','hb',13,18,'Orai por nós, porque confiamos que temos boa consciência, como aqueles que em tudo querem portar-se honestamente.'),
('acf','hb',13,19,'E rogo-vos com instância que assim o façais, para que eu mais depressa vos seja restituído.'),
('acf','hb',13,20,'Ora, o Deus de paz, que pelo sangue da aliança eterna tornou a trazer dos mortos a nosso Senhor Jesus Cristo, grande pastor das ovelhas,'),
('acf','hb',13,21,'Vos aperfeiçoe em toda a boa obra, para fazerdes a sua vontade, operando em vós o que perante ele é agradável por Cristo Jesus, ao qual seja glória para todo o sempre. Amém.'),
('acf','hb',13,22,'Rogo-vos, porém, irmãos, que suporteis a palavra desta exortação; porque abreviadamente vos escrevi.'),
('acf','hb',13,23,'Sabei que já está solto o irmão Timóteo, com o qual, se ele vier depressa, vos verei.'),
('acf','hb',13,24,'Saudai a todos os vossos chefes e a todos os santos. Os da Itália vos saúdam.'),
('acf','hb',13,25,'A graça seja com todos vós. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','tg',1,1,'Tiago, servo de Deus, e do Senhor Jesus Cristo, às doze tribos que andam dispersas, saúde.'),
('acf','tg',1,2,'Meus irmãos, tende grande gozo quando cairdes em várias tentações;'),
('acf','tg',1,3,'Sabendo que a prova da vossa fé opera a paciência.'),
('acf','tg',1,4,'Tenha, porém, a paciência a sua obra perfeita, para que sejais perfeitos e completos, sem faltar em coisa alguma.'),
('acf','tg',1,5,'E, se algum de vós tem falta de sabedoria, peça-a a Deus, que a todos dá liberalmente, e o não lança em rosto, e ser-lhe-á dada.'),
('acf','tg',1,6,'Peça-a, porém, com fé, em nada duvidando; porque o que duvida é semelhante à onda do mar, que é levada pelo vento, e lançada de uma para outra parte.'),
('acf','tg',1,7,'Não pense tal homem que receberá do Senhor alguma coisa.'),
('acf','tg',1,8,'O homem de coração dobre é inconstante em todos os seus caminhos.'),
('acf','tg',1,9,'Mas glorie-se o irmão abatido na sua exaltação,'),
('acf','tg',1,10,'E o rico em seu abatimento; porque ele passará como a flor da erva.'),
('acf','tg',1,11,'Porque sai o sol com ardor, e a erva seca, e a sua flor cai, e a formosa aparência do seu aspecto perece; assim se murchará também o rico em seus caminhos.'),
('acf','tg',1,12,'Bem-aventurado o homem que sofre a tentação; porque, quando for provado, receberá a coroa da vida, a qual o Senhor tem prometido aos que o amam.'),
('acf','tg',1,13,'Ninguém, sendo tentado, diga: De Deus sou tentado; porque Deus não pode ser tentado pelo mal, e a ninguém tenta.'),
('acf','tg',1,14,'Mas cada um é tentado, quando atraído e engodado pela sua própria concupiscência.'),
('acf','tg',1,15,'Depois, havendo a concupiscência concebido, dá à luz o pecado; e o pecado, sendo consumado, gera a morte.'),
('acf','tg',1,16,'Não erreis, meus amados irmãos.'),
('acf','tg',1,17,'Toda a boa dádiva e todo o dom perfeito vem do alto, descendo do Pai das luzes, em quem não há mudança nem sombra de variação.'),
('acf','tg',1,18,'Segundo a sua vontade, ele nos gerou pela palavra da verdade, para que fôssemos como primícias das suas criaturas.'),
('acf','tg',1,19,'Portanto, meus amados irmãos, todo o homem seja pronto para ouvir, tardio para falar, tardio para se irar.'),
('acf','tg',1,20,'Porque a ira do homem não opera a justiça de Deus.'),
('acf','tg',1,21,'Por isso, rejeitando toda a imundícia e superfluidade de malícia, recebei com mansidão a palavra em vós enxertada, a qual pode salvar as vossas almas.'),
('acf','tg',1,22,'E sede cumpridores da palavra, e não somente ouvintes, enganando-vos a vós mesmos.'),
('acf','tg',1,23,'Porque, se alguém é ouvinte da palavra, e não cumpridor, é semelhante ao homem que contempla ao espelho o seu rosto natural;'),
('acf','tg',1,24,'Porque se contempla a si mesmo, e vai-se, e logo se esquece de como era.'),
('acf','tg',1,25,'Aquele, porém, que atenta bem para a lei perfeita da liberdade, e nisso persevera, não sendo ouvinte esquecediço, mas fazedor da obra, este tal será bem-aventurado no seu feito.'),
('acf','tg',1,26,'Se alguém entre vós cuida ser religioso, e não refreia a sua língua, antes engana o seu coração, a religião desse é vã.'),
('acf','tg',1,27,'A religião pura e imaculada para com Deus e Pai, é esta: Visitar os órfãos e as viúvas nas suas tribulações, e guardar-se da corrupção do mundo.'),
('acf','tg',2,1,'Meus irmãos, não tenhais a fé de nosso Senhor Jesus Cristo, Senhor da glória, em acepção de pessoas.'),
('acf','tg',2,2,'Porque, se no vosso ajuntamento entrar algum homem com anel de ouro no dedo, com trajes preciosos, e entrar também algum pobre com sórdido traje,'),
('acf','tg',2,3,'E atentardes para o que traz o traje precioso, e lhe disserdes: Assenta-te tu aqui num lugar de honra, e disserdes ao pobre: Tu, fica aí em pé, ou assenta-te abaixo do meu estrado,'),
('acf','tg',2,4,'Porventura não fizestes distinção entre vós mesmos, e não vos fizestes juízes de maus pensamentos?'),
('acf','tg',2,5,'Ouvi, meus amados irmãos: Porventura não escolheu Deus aos pobres deste mundo para serem ricos na fé, e herdeiros do reino que prometeu aos que o amam?'),
('acf','tg',2,6,'Mas vós desonrastes o pobre. Porventura não vos oprimem os ricos, e não vos arrastam aos tribunais?'),
('acf','tg',2,7,'Porventura não blasfemam eles o bom nome que sobre vós foi invocado?'),
('acf','tg',2,8,'Todavia, se cumprirdes, conforme a Escritura, a lei real: Amarás a teu próximo como a ti mesmo, bem fazeis.'),
('acf','tg',2,9,'Mas, se fazeis acepção de pessoas, cometeis pecado, e sois redargüidos pela lei como transgressores.'),
('acf','tg',2,10,'Porque qualquer que guardar toda a lei, e tropeçar em um só ponto, tornou-se culpado de todos.'),
('acf','tg',2,11,'Porque aquele que disse: Não cometerás adultério, também disse: Não matarás. Se tu pois não cometeres adultério, mas matares, estás feito transgressor da lei.'),
('acf','tg',2,12,'Assim falai, e assim procedei, como devendo ser julgados pela lei da liberdade.'),
('acf','tg',2,13,'Porque o juízo será sem misericórdia sobre aquele que não fez misericórdia; e a misericórdia triunfa do juízo.'),
('acf','tg',2,14,'Meus irmãos, que aproveita se alguém disser que tem fé, e não tiver as obras? Porventura a fé pode salvá-lo?'),
('acf','tg',2,15,'E, se o irmão ou a irmã estiverem nus, e tiverem falta de mantimento quotidiano,'),
('acf','tg',2,16,'E algum de vós lhes disser: Ide em paz, aquentai-vos, e fartai-vos; e nào lhes derdes as coisas necessárias para o corpo, que proveito virá daí?'),
('acf','tg',2,17,'Assim também a fé, se não tiver as obras, é morta em si mesma.'),
('acf','tg',2,18,'Mas dirá alguém: Tu tens a fé, e eu tenho as obras; mostra-me a tua fé sem as tuas obras, e eu te mostrarei a minha fé pelas minhas obras.'),
('acf','tg',2,19,'Tu crês que há um só Deus; fazes bem. Também os demônios o crêem, e estremecem.'),
('acf','tg',2,20,'Mas, ó homem vão, queres tu saber que a fé sem as obras é morta?'),
('acf','tg',2,21,'Porventura o nosso pai Abraão não foi justificado pelas obras, quando ofereceu sobre o altar o seu filho Isaque?'),
('acf','tg',2,22,'Bem vês que a fé cooperou com as suas obras, e que pelas obras a fé foi aperfeiçoada.'),
('acf','tg',2,23,'E cumpriu-se a Escritura, que diz: E creu Abraão em Deus, e foi-lhe isso imputado como justiça, e foi chamado o amigo de Deus.'),
('acf','tg',2,24,'Vedes então que o homem é justificado pelas obras, e não somente pela fé.'),
('acf','tg',2,25,'E de igual modo Raabe, a meretriz, não foi também justificada pelas obras, quando recolheu os emissários, e os despediu por outro caminho?'),
('acf','tg',2,26,'Porque, assim como o corpo sem o espírito está morto, assim também a fé sem obras é morta.'),
('acf','tg',3,1,'Meus irmãos, muitos de vós não sejam mestres, sabendo que receberemos mais duro juízo.'),
('acf','tg',3,2,'Porque todos tropeçamos em muitas coisas. Se alguém não tropeça em palavra, o tal é perfeito, e poderoso para também refrear todo o corpo.'),
('acf','tg',3,3,'Ora, nós pomos freio nas bocas dos cavalos, para que nos obedeçam; e conseguimos dirigir todo o seu corpo.'),
('acf','tg',3,4,'Vede também as naus que, sendo tão grandes, e levadas de impetuosos ventos, se viram com um bem pequeno leme para onde quer a vontade daquele que as governa.'),
('acf','tg',3,5,'Assim também a língua é um pequeno membro, e gloria-se de grandes coisas. Vede quão grande bosque um pequeno fogo incendeia.'),
('acf','tg',3,6,'A língua também é um fogo; como mundo de iniqüidade, a língua está posta entre os nossos membros, e contamina todo o corpo, e inflama o curso da natureza, e é inflamada pelo inferno.'),
('acf','tg',3,7,'Porque toda a natureza, tanto de bestas feras como de aves, tanto de répteis como de animais do mar, se amansa e foi domada pela natureza humana;'),
('acf','tg',3,8,'Mas nenhum homem pode domar a língua. É um mal que não se pode refrear; está cheia de peçonha mortal.'),
('acf','tg',3,9,'Com ela bendizemos a Deus e Pai, e com ela amaldiçoamos os homens, feitos à semelhança de Deus.'),
('acf','tg',3,10,'De uma mesma boca procede bênção e maldição. Meus irmãos, não convém que isto se faça assim.'),
('acf','tg',3,11,'Porventura deita alguma fonte de um mesmo manancial água doce e água amargosa?'),
('acf','tg',3,12,'Meus irmãos, pode também a figueira produzir azeitonas, ou a videira figos? Assim tampouco pode uma fonte dar água salgada e doce.'),
('acf','tg',3,13,'Quem dentre vós é sábio e entendido? Mostre pelo seu bom trato as suas obras em mansidão de sabedoria.'),
('acf','tg',3,14,'Mas, se tendes amarga inveja, e sentimento faccioso em vosso coração, não vos glorieis, nem mintais contra a verdade.'),
('acf','tg',3,15,'Essa não é a sabedoria que vem do alto, mas é terrena, animal e diabólica.'),
('acf','tg',3,16,'Porque onde há inveja e espírito faccioso aí há perturbação e toda a obra perversa.'),
('acf','tg',3,17,'Mas a sabedoria que do alto vem é, primeiramente pura, depois pacífica, moderada, tratável, cheia de misericórdia e de bons frutos, sem parcialidade, e sem hipocrisia.'),
('acf','tg',3,18,'Ora, o fruto da justiça semeia-se na paz, para os que exercitam a paz.'),
('acf','tg',4,1,'De onde vêm as guerras e pelejas entre vós? Porventura não vêm disto, a saber, dos vossos deleites, que nos vossos membros guerreiam?'),
('acf','tg',4,2,'Cobiçais, e nada tendes; matais, e sois invejosos, e nada podeis alcançar; combateis e guerreais, e nada tendes, porque não pedis.'),
('acf','tg',4,3,'Pedis, e não recebeis, porque pedis mal, para o gastardes em vossos deleites.'),
('acf','tg',4,4,'Adúlteros e adúlteras, não sabeis vós que a amizade do mundo é inimizade contra Deus? Portanto, qualquer que quiser ser amigo do mundo constitui-se inimigo de Deus.'),
('acf','tg',4,5,'Ou cuidais vós que em vão diz a Escritura: O Espírito que em nós habita tem ciúmes?'),
('acf','tg',4,6,'Antes, ele dá maior graça. Portanto diz: Deus resiste aos soberbos, mas dá graça aos humildes.'),
('acf','tg',4,7,'Sujeitai-vos, pois, a Deus, resisti ao diabo, e ele fugirá de vós.'),
('acf','tg',4,8,'Chegai-vos a Deus, e ele se chegará a vós. Alimpai as mãos, pecadores; e, vós de duplo ânimo, purificai os corações.'),
('acf','tg',4,9,'Senti as vossas misérias, e lamentai e chorai; converta-se o vosso riso em pranto, e o vosso gozo em tristeza.'),
('acf','tg',4,10,'Humilhai-vos perante o Senhor, e ele vos exaltará.'),
('acf','tg',4,11,'Irmãos, não faleis mal uns dos outros. Quem fala mal de um irmão, e julga a seu irmão, fala mal da lei, e julga a lei; e, se tu julgas a lei, já não és observador da lei, mas juiz.'),
('acf','tg',4,12,'Há só um legislador que pode salvar e destruir. Tu, porém, quem és, que julgas a outrem?'),
('acf','tg',4,13,'Eia agora vós, que dizeis: Hoje, ou amanhã, iremos a tal cidade, e lá passaremos um ano, e contrataremos, e ganharemos;'),
('acf','tg',4,14,'Digo-vos que não sabeis o que acontecerá amanhã. Porque, que é a vossa vida? É um vapor que aparece por um pouco, e depois se desvanece.'),
('acf','tg',4,15,'Em lugar do que devíeis dizer: Se o Senhor quiser, e se vivermos, faremos isto ou aquilo.'),
('acf','tg',4,16,'Mas agora vos gloriais em vossas presunções; toda a glória tal como esta é maligna.'),
('acf','tg',4,17,'Aquele, pois, que sabe fazer o bem e não o faz, comete pecado.'),
('acf','tg',5,1,'Eia, pois, agora vós, ricos, chorai e pranteai, por vossas misérias, que sobre vós hão de vir.'),
('acf','tg',5,2,'As vossas riquezas estão apodrecidas, e as vossas vestes estão comidas de traça.'),
('acf','tg',5,3,'O vosso ouro e a vossa prata se enferrujaram; e a sua ferrugem dará testemunho contra vós, e comerá como fogo a vossa carne. Entesourastes para os últimos dias.'),
('acf','tg',5,4,'Eis que o jornal dos trabalhadores que ceifaram as vossas terras, e que por vós foi diminuído, clama; e os clamores dos que ceifaram entraram nos ouvidos do Senhor dos exércitos.'),
('acf','tg',5,5,'Deliciosamente vivestes sobre a terra, e vos deleitastes; cevastes os vossos corações, como num dia de matança.'),
('acf','tg',5,6,'Condenastes e matastes o justo; ele não vos resistiu.'),
('acf','tg',5,7,'Sede pois, irmãos, pacientes até à vinda do Senhor. Eis que o lavrador espera o precioso fruto da terra, aguardando-o com paciência, até que receba a chuva temporã e serôdia.'),
('acf','tg',5,8,'Sede vós também pacientes, fortalecei os vossos corações; porque já a vinda do Senhor está próxima.'),
('acf','tg',5,9,'Irmãos, não vos queixeis uns contra os outros, para que não sejais condenados. Eis que o juiz está à porta.'),
('acf','tg',5,10,'Meus irmãos, tomai por exemplo de aflição e paciência os profetas que falaram em nome do Senhor.'),
('acf','tg',5,11,'Eis que temos por bem-aventurados os que sofreram. Ouvistes qual foi a paciência de Jó, e vistes o fim que o Senhor lhe deu; porque o Senhor é muito misericordioso e piedoso.'),
('acf','tg',5,12,'Mas, sobretudo, meus irmãos, não jureis, nem pelo céu, nem pela terra, nem façais qualquer outro juramento; mas que a vossa palavra seja sim, sim, e não, não; para que não caiais em condenação.'),
('acf','tg',5,13,'Está alguém entre vós aflito? Ore. Está alguém contente? Cante louvores.'),
('acf','tg',5,14,'Está alguém entre vós doente? Chame os presbíteros da igreja, e orem sobre ele, ungindo-o com azeite em nome do Senhor;'),
('acf','tg',5,15,'E a oração da fé salvará o doente, e o Senhor o levantará; e, se houver cometido pecados, ser-lhe-ão perdoados.'),
('acf','tg',5,16,'Confessai as vossas culpas uns aos outros, e orai uns pelos outros, para que sareis. A oração feita por um justo pode muito em seus efeitos.'),
('acf','tg',5,17,'Elias era homem sujeito às mesmas paixões que nós e, orando, pediu que não chovesse e, por três anos e seis meses, não choveu sobre a terra.'),
('acf','tg',5,18,'E orou outra vez, e o céu deu chuva, e a terra produziu o seu fruto.'),
('acf','tg',5,19,'Irmãos, se algum dentre vós se tem desviado da verdade, e alguém o converter,'),
('acf','tg',5,20,'Saiba que aquele que fizer converter do erro do seu caminho um pecador, salvará da morte uma alma, e cobrirá uma multidão de pecados.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1pe',1,1,'Pedro, apóstolo de Jesus Cristo, aos estrangeiros dispersos no Ponto, Galácia, Capadócia, Ásia e Bitínia;'),
('acf','1pe',1,2,'Eleitos segundo a presciência de Deus Pai, em santificação do Espírito, para a obediência e aspersão do sangue de Jesus Cristo: Graça e paz vos sejam multiplicadas.'),
('acf','1pe',1,3,'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo que, segundo a sua grande misericórdia, nos gerou de novo para uma viva esperança, pela ressurreição de Jesus Cristo dentre os mortos,'),
('acf','1pe',1,4,'Para uma herança incorruptível, incontaminável, e que não se pode murchar, guardada nos céus para vós,'),
('acf','1pe',1,5,'Que mediante a fé estais guardados na virtude de Deus para a salvação, já prestes para se revelar no último tempo,'),
('acf','1pe',1,6,'Em que vós grandemente vos alegrais, ainda que agora importa, sendo necessário, que estejais por um pouco contristados com várias tentações,'),
('acf','1pe',1,7,'Para que a prova da vossa fé, muito mais preciosa do que o ouro que perece e é provado pelo fogo, se ache em louvor, e honra, e glória, na revelação de Jesus Cristo;'),
('acf','1pe',1,8,'Ao qual, não o havendo visto, amais; no qual, não o vendo agora, mas crendo, vos alegrais com gozo inefável e glorioso;'),
('acf','1pe',1,9,'Alcançando o fim da vossa fé, a salvação das vossas almas.'),
('acf','1pe',1,10,'Da qual salvação inquiriram e trataram diligentemente os profetas que profetizaram da graça que vos foi dada,'),
('acf','1pe',1,11,'Indagando que tempo ou que ocasião de tempo o Espírito de Cristo, que estava neles, indicava, anteriormente testificando os sofrimentos que a Cristo haviam de vir, e a glória que se lhes havia de seguir.'),
('acf','1pe',1,12,'Aos quais foi revelado que, não para si mesmos, mas para nós, eles ministravam estas coisas que agora vos foram anunciadas por aqueles que, pelo Espírito Santo enviado do céu, vos pregaram o evangelho; para as quais coisas os anjos desejam bem atentar.'),
('acf','1pe',1,13,'Portanto, cingindo os lombos do vosso entendimento, sede sóbrios, e esperai inteiramente na graça que se vos ofereceu na revelação de Jesus Cristo;'),
('acf','1pe',1,14,'Como filhos obedientes, não vos conformando com as concupiscências que antes havia em vossa ignorância;'),
('acf','1pe',1,15,'Mas, como é santo aquele que vos chamou, sede vós também santos em toda a vossa maneira de viver;'),
('acf','1pe',1,16,'Porquanto está escrito: Sede santos, porque eu sou santo.'),
('acf','1pe',1,17,'E, se invocais por Pai aquele que, sem acepção de pessoas, julga segundo a obra de cada um, andai em temor, durante o tempo da vossa peregrinação,'),
('acf','1pe',1,18,'Sabendo que não foi com coisas corruptíveis, como prata ou ouro, que fostes resgatados da vossa vã maneira de viver que por tradição recebestes dos vossos pais,'),
('acf','1pe',1,19,'Mas com o precioso sangue de Cristo, como de um cordeiro imaculado e incontaminado,'),
('acf','1pe',1,20,'O qual, na verdade, em outro tempo foi conhecido, ainda antes da fundação do mundo, mas manifestado nestes últimos tempos por amor de vós;'),
('acf','1pe',1,21,'E por ele credes em Deus, que o ressuscitou dentre os mortos, e lhe deu glória, para que a vossa fé e esperança estivessem em Deus;'),
('acf','1pe',1,22,'Purificando as vossas almas pelo Espírito na obediência à verdade, para o amor fraternal, não fingido; amai-vos ardentemente uns aos outros com um coração puro;'),
('acf','1pe',1,23,'Sendo de novo gerados, não de semente corruptível, mas da incorruptível, pela palavra de Deus, viva, e que permanece para sempre.'),
('acf','1pe',1,24,'Porque toda a carne é como a erva,e toda a glória do homem como a flor da erva.Secou-se a erva, e caiu a sua flor;'),
('acf','1pe',1,25,'Mas a palavra do Senhor permanece para sempre.E esta é a palavra que entre vós foi evangelizada.'),
('acf','1pe',2,1,'Deixando, pois, toda a malícia, e todo o engano, e fingimentos, e invejas, e todas as murmurações,'),
('acf','1pe',2,2,'Desejai afetuosamente, como meninos novamente nascidos, o leite racional, não falsificado, para que por ele vades crescendo;'),
('acf','1pe',2,3,'Se é que já provastes que o Senhor é benigno;'),
('acf','1pe',2,4,'E, chegando-vos para ele, pedra viva, reprovada, na verdade, pelos homens, mas para com Deus eleita e preciosa,'),
('acf','1pe',2,5,'Vòs também, como pedras vivas, sois edificados casa espiritual e sacerdòcio santo, para oferecer sacrifícios espirituais agradáveis a Deus por Jesus Cristo.'),
('acf','1pe',2,6,'Por isso também na Escritura se contém:Eis que ponho em Sião a pedra principal da esquina, eleita e preciosa;e quem nela crer não será confundido.'),
('acf','1pe',2,7,'E assim para vòs, os que credes, é preciosa, mas, para os rebeldes,a pedra que os edificadores reprovaram,essa foi a principal da esquina,'),
('acf','1pe',2,8,'E uma pedra de tropeço e rocha de escândalo,para aqueles que tropeçam na palavra, sendo desobedientes; para o que também foram destinados.'),
('acf','1pe',2,9,'Mas vòs sois a geração eleita, o sacerdòcio real, a nação santa, o povo adquirido, para que anuncieis as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz;'),
('acf','1pe',2,10,'Vós, que em outro tempo não éreis povo, mas agora sois povo de Deus; que não tínheis alcançado misericórdia, mas agora alcançastes misericórdia.'),
('acf','1pe',2,11,'Amados, peço-vos, como a peregrinos e forasteiros, que vos abstenhais das concupiscências carnais, que combatem contra a alma;'),
('acf','1pe',2,12,'Tendo o vosso viver honesto entre os gentios; para que, naquilo em que falam mal de vós, como de malfeitores, glorifiquem a Deus no dia da visitação, pelas boas obras que em vós observem.'),
('acf','1pe',2,13,'Sujeitai-vos, pois, a toda a ordenação humana por amor do Senhor; quer ao rei, como superior;'),
('acf','1pe',2,14,'Quer aos governadores, como por ele enviados para castigo dos malfeitores, e para louvor dos que fazem o bem.'),
('acf','1pe',2,15,'Porque assim é a vontade de Deus, que, fazendo bem, tapeis a boca à ignorância dos homens insensatos;'),
('acf','1pe',2,16,'Como livres, e não tendo a liberdade por cobertura da malícia, mas como servos de Deus.'),
('acf','1pe',2,17,'Honrai a todos. Amai a fraternidade. Temei a Deus. Honrai ao rei.'),
('acf','1pe',2,18,'Vós, servos, sujeitai-vos com todo o temor aos senhores, não somente aos bons e humanos, mas também aos maus.'),
('acf','1pe',2,19,'Porque é coisa agradável, que alguém, por causa da consciência para com Deus, sofra agravos, padecendo injustamente.'),
('acf','1pe',2,20,'Porque, que glória será essa, se, pecando, sois esbofeteados e sofreis? Mas se, fazendo o bem, sois afligidos e o sofreis, isso é agradável a Deus.'),
('acf','1pe',2,21,'Porque para isto sois chamados; pois também Cristo padeceu por nós, deixando-nos o exemplo, para que sigais as suas pisadas.'),
('acf','1pe',2,22,'O qual não cometeu pecado, nem na sua boca se achou engano.'),
('acf','1pe',2,23,'O qual, quando o injuriavam, não injuriava, e quando padecia não ameaçava, mas entregava-se àquele que julga justamente;'),
('acf','1pe',2,24,'Levando ele mesmo em seu corpo os nossos pecados sobre o madeiro, para que, mortos para os pecados, pudéssemos viver para a justiça; e pelas suas feridas fostes sarados.'),
('acf','1pe',2,25,'Porque éreis como ovelhas desgarradas; mas agora tendes voltado ao Pastor e Bispo das vossas almas.'),
('acf','1pe',3,1,'Semelhantemente, vós, mulheres, sede sujeitas aos vossos próprios maridos; para que também, se alguns não obedecem à palavra, pelo porte de suas mulheres sejam ganhos sem palavra;'),
('acf','1pe',3,2,'Considerando a vossa vida casta, em temor.'),
('acf','1pe',3,3,'O enfeite delas não seja o exterior, no frisado dos cabelos, no uso de jóias de ouro, na compostura dos vestidos;'),
('acf','1pe',3,4,'Mas o homem encoberto no coração; no incorruptível traje de um espírito manso e quieto, que é precioso diante de Deus.'),
('acf','1pe',3,5,'Porque assim se adornavam também antigamente as santas mulheres que esperavam em Deus, e estavam sujeitas aos seus próprios maridos;'),
('acf','1pe',3,6,'Como Sara obedecia a Abraão, chamando-lhe senhor; da qual vós sois filhas, fazendo o bem, e não temendo nenhum espanto.'),
('acf','1pe',3,7,'Igualmente vós, maridos, coabitai com elas com entendimento, dando honra à mulher, como vaso mais fraco; como sendo vós os seus co-herdeiros da graça da vida; para que não sejam impedidas as vossas orações.'),
('acf','1pe',3,8,'E, finalmente, sede todos de um mesmo sentimento, compassivos, amando os irmãos, entranhavelmente misericordiosos e afáveis.'),
('acf','1pe',3,9,'Não tornando mal por mal, ou injúria por injúria; antes, pelo contrário, bendizendo; sabendo que para isto fostes chamados, para que por herança alcanceis a bênção.'),
('acf','1pe',3,10,'Porque Quem quer amar a vida, E ver os dias bons, Refreie a sua língua do mal, E os seus lábios não falem engano.'),
('acf','1pe',3,11,'Aparte-se do mal, e faça o bem; Busque a paz, e siga-a.'),
('acf','1pe',3,12,'Porque os olhos do Senhor estão sobre os justos, E os seus ouvidos atentos às suas orações; Mas o rosto do Senhor é contra os que fazem o mal.'),
('acf','1pe',3,13,'E qual é aquele que vos fará mal, se fordes seguidores do bem?'),
('acf','1pe',3,14,'Mas também, se padecerdes por amor da justiça, sois bemaventurados. E não temais com medo deles, nem vos turbeis;'),
('acf','1pe',3,15,'Antes, santificai ao Senhor Deus em vossos corações; e estai sempre preparados para responder com mansidão e temor a qualquer que vos pedir a razão da esperança que há em vós,'),
('acf','1pe',3,16,'Tendo uma boa consciência, para que, naquilo em que falam mal de vós, como de malfeitores, fiquem confundidos os que blasfemam do vosso bom porte em Cristo.'),
('acf','1pe',3,17,'Porque melhor é que padeçais fazendo bem (se a vontade de Deus assim o quer), do que fazendo mal.'),
('acf','1pe',3,18,'Porque também Cristo padeceu uma vez pelos pecados, o justo pelos injustos, para levar-nos a Deus; mortificado, na verdade, na carne, mas vivificado pelo Espírito;'),
('acf','1pe',3,19,'No qual também foi, e pregou aos espíritos em prisão;'),
('acf','1pe',3,20,'Os quais noutro tempo foram rebeldes, quando a longanimidade de Deus esperava nos dias de Noé, enquanto se preparava a arca; na qual poucas (isto é, oito) almas se salvaram pela água;'),
('acf','1pe',3,21,'Que também, como uma verdadeira figura, agora vos salva, o batismo, não do despojamento da imundícia da carne, mas da indagação de uma boa consciência para com Deus, pela ressurreição de Jesus Cristo;'),
('acf','1pe',3,22,'O qual está à destra de Deus, tendo subido ao céu, havendo-se-lhe sujeitado os anjos, e as autoridades, e as potências.'),
('acf','1pe',4,1,'Ora, pois, já que Cristo padeceu por nós na carne, armai-vos também vós com este mesmo pensamento, que aquele que padeceu na carne já cessou do pecado;'),
('acf','1pe',4,2,'Para que, no tempo que vos resta na carne, não vivais mais segundo as concupiscências dos homens, mas segundo a vontade de Deus.'),
('acf','1pe',4,3,'Porque é bastante que no tempo passado da vida fizéssemos a vontade dos gentios, andando em dissoluções, concupiscências, borrachices, glutonarias, bebedices e abomináveis idolatrias;'),
('acf','1pe',4,4,'E acham estranho não correrdes com eles no mesmo desenfreamento de dissolução, blasfemando de vós.'),
('acf','1pe',4,5,'Os quais hão de dar conta ao que está preparado para julgar os vivos e os mortos.'),
('acf','1pe',4,6,'Porque por isto foi pregado o evangelho também aos mortos, para que, na verdade, fossem julgados segundo os homens na carne, mas vivessem segundo Deus em espírito;'),
('acf','1pe',4,7,'E já está próximo o fim de todas as coisas; portanto sede sóbrios e vigiai em oração.'),
('acf','1pe',4,8,'Mas, sobretudo, tende ardente amor uns para com os outros; porque o amor cobrirá a multidão de pecados.'),
('acf','1pe',4,9,'Sendo hospitaleiros uns para com os outros, sem murmurações,'),
('acf','1pe',4,10,'Cada um administre aos outros o dom como o recebeu, como bons despenseiros da multiforme graça de Deus.'),
('acf','1pe',4,11,'Se alguém falar, fale segundo as palavras de Deus; se alguém administrar, administre segundo o poder que Deus dá; para que em tudo Deus seja glorificado por Jesus Cristo, a quem pertence a glória e poder para todo o sempre. Amém.'),
('acf','1pe',4,12,'Amados, não estranheis a ardente prova que vem sobre vós para vos tentar, como se coisa estranha vos acontecesse;'),
('acf','1pe',4,13,'Mas alegrai-vos no fato de serdes participantes das aflições de Cristo, para que também na revelação da sua glória vos regozijeis e alegreis.'),
('acf','1pe',4,14,'Se pelo nome de Cristo sois vituperados, bem-aventurados sois, porque sobre vós repousa o Espírito da glória e de Deus; quanto a eles, é ele, sim, blasfemado, mas quanto a vós, é glorificado.'),
('acf','1pe',4,15,'Que nenhum de vós padeça como homicida, ou ladrão, ou malfeitor, ou como o que se entremete em negócios alheios;'),
('acf','1pe',4,16,'Mas, se padece como cristão, não se envergonhe, antes glorifique a Deus nesta parte.'),
('acf','1pe',4,17,'Porque já é tempo que comece o julgamento pela casa de Deus; e, se primeiro começa por nós, qual será o fim daqueles que são desobedientes ao evangelho de Deus?'),
('acf','1pe',4,18,'E, se o justo apenas se salva, onde aparecerá o ímpio e o pecador?'),
('acf','1pe',4,19,'Portanto também os que padecem segundo a vontade de Deus encomendem-lhe as suas almas, como ao fiel Criador, fazendo o bem.'),
('acf','1pe',5,1,'Aos presbíteros, que estão entre vós, admoesto eu, que sou também presbítero com eles, e testemunha das aflições de Cristo, e participante da glória que se há de revelar:'),
('acf','1pe',5,2,'Apascentai o rebanho de Deus, que está entre vós, tendo cuidado dele, não por força, mas voluntariamente; nem por torpe ganância, mas de ânimo pronto;'),
('acf','1pe',5,3,'Nem como tendo domínio sobre a herança de Deus, mas servindo de exemplo ao rebanho.'),
('acf','1pe',5,4,'E, quando aparecer o Sumo Pastor, alcançareis a incorruptível coroa da glória.'),
('acf','1pe',5,5,'Semelhantemente vós jovens, sede sujeitos aos anciãos; e sede todos sujeitos uns aos outros, e revesti-vos de humildade, porque Deus resiste aos soberbos, mas dá graça aos humildes.'),
('acf','1pe',5,6,'Humilhai-vos, pois, debaixo da potente mão de Deus, para que a seu tempo vos exalte;'),
('acf','1pe',5,7,'Lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.'),
('acf','1pe',5,8,'Sede sóbrios; vigiai; porque o diabo, vosso adversário, anda em derredor, bramando como leão, buscando a quem possa tragar;'),
('acf','1pe',5,9,'Ao qual resisti firmes na fé, sabendo que as mesmas aflições se cumprem entre os vossos irmãos no mundo.'),
('acf','1pe',5,10,'E o Deus de toda a graça, que em Cristo Jesus nos chamou à sua eterna glória, depois de havemos padecido um pouco, ele mesmo vos aperfeiçoe, confirme, fortifique e estabeleça.'),
('acf','1pe',5,11,'A ele seja a glória e o poderio para todo o sempre. Amém.'),
('acf','1pe',5,12,'Por Silvano, vosso fiel irmão, como cuido, escrevi brevemente, exortando e testificando que esta é a verdadeira graça de Deus, na qual estais firmes.'),
('acf','1pe',5,13,'A vossa co-eleita em babilônia vos saúda, e meu filho Marcos.'),
('acf','1pe',5,14,'Saudai-vos uns aos outros com ósculo de amor. Paz seja com todos vós que estais em Cristo Jesus. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2pe',1,1,'Simão Pedro, servo e apóstolo de Jesus Cristo, aos que conosco alcançaram fé igualmente preciosa pela justiça do nosso Deus e Salvador Jesus Cristo:'),
('acf','2pe',1,2,'Graça e paz vos sejam multiplicadas, pelo conhecimento de Deus, e de Jesus nosso Senhor;'),
('acf','2pe',1,3,'Visto como o seu divino poder nos deu tudo o que diz respeito à vida e piedade, pelo conhecimento daquele que nos chamou pela sua glória e virtude;'),
('acf','2pe',1,4,'Pelas quais ele nos tem dado grandíssimas e preciosas promessas, para que por elas fiqueis participantes da natureza divina, havendo escapado da corrupção, que pela concupiscência há no mundo.'),
('acf','2pe',1,5,'E vós também, pondo nisto mesmo toda a diligência, acrescentai à vossa fé a virtude, e à virtude a ciência,'),
('acf','2pe',1,6,'E à ciência a temperança, e à temperança a paciência, e à paciência a piedade,'),
('acf','2pe',1,7,'E à piedade o amor fraternal, e ao amor fraternal a caridade.'),
('acf','2pe',1,8,'Porque, se em vós houver e abundarem estas coisas, não vos deixarão ociosos nem estéreis no conhecimento de nosso Senhor Jesus Cristo.'),
('acf','2pe',1,9,'Pois aquele em quem não há estas coisas é cego, nada vendo ao longe, havendo-se esquecido da purificação dos seus antigos pecados.'),
('acf','2pe',1,10,'Portanto, irmãos, procurai fazer cada vez mais firme a vossa vocação e eleição; porque, fazendo isto, nunca jamais tropeçareis.'),
('acf','2pe',1,11,'Porque assim vos será amplamente concedida a entrada no reino eterno de nosso Senhor e Salvador Jesus Cristo.'),
('acf','2pe',1,12,'Por isso não deixarei de exortar-vos sempre acerca destas coisas, ainda que bem as saibais, e estejais confirmados na presente verdade.'),
('acf','2pe',1,13,'E tenho por justo, enquanto estiver neste tabernáculo, despertar-vos com admoestações,'),
('acf','2pe',1,14,'Sabendo que brevemente hei de deixar este meu tabernáculo, como também nosso Senhor Jesus Cristo já mo tem revelado.'),
('acf','2pe',1,15,'Mas também eu procurarei em toda a ocasião que depois da minha morte tenhais lembrança destas coisas.'),
('acf','2pe',1,16,'Porque não vos fizemos saber a virtude e a vinda de nosso Senhor Jesus Cristo, seguindo fábulas artificialmente compostas; mas nós mesmos vimos a sua majestade.'),
('acf','2pe',1,17,'Porquanto ele recebeu de Deus Pai honra e glória, quando da magnífica glória lhe foi dirigida a seguinte voz: Este é o meu Filho amado, em quem me tenho comprazido.'),
('acf','2pe',1,18,'E ouvimos esta voz dirigida do céu, estando nós com ele no monte santo;'),
('acf','2pe',1,19,'E temos, mui firme, a palavra dos profetas, à qual bem fazeis em estar atentos, como a uma luz que alumia em lugar escuro, até que o dia amanheça, e a estrela da alva apareça em vossos corações.'),
('acf','2pe',1,20,'Sabendo primeiramente isto: que nenhuma profecia da Escritura é de particular interpretação.'),
('acf','2pe',1,21,'Porque a profecia nunca foi produzida por vontade de homem algum, mas os homens santos de Deus falaram inspirados pelo Espírito Santo.'),
('acf','2pe',2,1,'E também houve entre o povo falsos profetas, como entre vós haverá também falsos doutores, que introduzirão encobertamente heresias de perdição, e negarão o Senhor que os resgatou, trazendo sobre si mesmos repentina perdição.'),
('acf','2pe',2,2,'E muitos seguirão as suas dissoluções, pelos quais será blasfemado o caminho da verdade.'),
('acf','2pe',2,3,'E por avareza farão de vós negócio com palavras fingidas; sobre os quais já de largo tempo não será tardia a sentença, e a sua perdição não dormita.'),
('acf','2pe',2,4,'Porque, se Deus não perdoou aos anjos que pecaram, mas, havendo-os lançado no inferno, os entregou às cadeias da escuridão, ficando reservados para o juízo;'),
('acf','2pe',2,5,'E não perdoou ao mundo antigo, mas guardou a Noé, a oitava pessoa, o pregoeiro da justiça, ao trazer o dilúvio sobre o mundo dos ímpios;'),
('acf','2pe',2,6,'E condenou à destruição as cidades de Sodoma e Gomorra, reduzindo-as a cinza, e pondo-as para exemplo aos que vivessem impiamente;'),
('acf','2pe',2,7,'E livrou o justo Ló, enfadado da vida dissoluta dos homens abomináveis'),
('acf','2pe',2,8,'(Porque este justo, habitando entre eles, afligia todos os dias a sua alma justa, por isso via e ouvia sobre as suas obras injustas);'),
('acf','2pe',2,9,'Assim, sabe o Senhor livrar da tentação os piedosos, e reservar os injustos para o dia do juízo, para serem castigados;'),
('acf','2pe',2,10,'Mas principalmente aqueles que segundo a carne andam em concupiscências de imundícia, e desprezam as autoridades; atrevidos, obstinados, não receando blasfemar das dignidades;'),
('acf','2pe',2,11,'Enquanto os anjos, sendo maiores em força e poder, não pronunciam contra eles juízo blasfemo diante do Senhor.'),
('acf','2pe',2,12,'Mas estes, como animais irracionais, que seguem a natureza, feitos para serem presos e mortos, blasfemando do que não entendem, perecerão na sua corrupção,'),
('acf','2pe',2,13,'Recebendo o galardão da injustiça; pois que tais homens têm prazer nos deleites quotidianos; nódoas são eles e máculas, deleitando-se em seus enganos, quando se banqueteiam convosco;'),
('acf','2pe',2,14,'Tendo os olhos cheios de adultério, e não cessando de pecar, engodando as almas inconstantes, tendo o coração exercitado na avareza, filhos de maldição;'),
('acf','2pe',2,15,'Os quais, deixando o caminho direito, erraram seguindo o caminho de Balaão, filho de Beor, que amou o prêmio da injustiça;'),
('acf','2pe',2,16,'Mas teve a repreensão da sua transgressão; o mudo jumento, falando com voz humana, impediu a loucura do profeta.'),
('acf','2pe',2,17,'Estes são fontes sem água, nuvens levadas pela força do vento, para os quais a escuridão das trevas eternamente se reserva.'),
('acf','2pe',2,18,'Porque, falando coisas mui arrogantes de vaidades, engodam com as concupiscências da carne, e com dissoluções, aqueles que se estavam afastando dos que andam em erro,'),
('acf','2pe',2,19,'Prometendo-lhes liberdade, sendo eles mesmos servos da corrupção. Porque de quem alguém é vencido, do tal faz-se também servo.'),
('acf','2pe',2,20,'Porquanto se, depois de terem escapado das corrupções do mundo, pelo conhecimento do Senhor e Salvador Jesus Cristo, forem outra vez envolvidos nelas e vencidos, tornou-se-lhes o último estado pior do que o primeiro.'),
('acf','2pe',2,21,'Porque melhor lhes fora não conhecerem o caminho da justiça, do que, conhecendo-o, desviarem-se do santo mandamento que lhes fora dado;'),
('acf','2pe',2,22,'Deste modo sobreveio-lhes o que por um verdadeiro provérbio se diz: O cão voltou ao seu próprio vômito, e a porca lavada ao espojadouro de lama.'),
('acf','2pe',3,1,'Amados, escrevo-vos agora esta segunda carta, em ambas as quais desperto com exortação o vosso ânimo sincero;'),
('acf','2pe',3,2,'Para que vos lembreis das palavras que primeiramente foram ditas pelos santos profetas, e do nosso mandamento, como apòstolos do Senhor e Salvador.'),
('acf','2pe',3,3,'Sabendo primeiro isto, que nos últimos dias virão escarnecedores, andando segundo as suas próprias concupiscências,'),
('acf','2pe',3,4,'E dizendo: Onde está a promessa da sua vinda? porque desde que os pais dormiram, todas as coisas permanecem como desde o princípio da criação.'),
('acf','2pe',3,5,'Eles voluntariamente ignoram isto, que pela palavra de Deus já desde a antiguidade existiram os céus, e a terra, que foi tirada da água e no meio da água subsiste.'),
('acf','2pe',3,6,'Pelas quais coisas pereceu o mundo de então, coberto com as águas do dilúvio,'),
('acf','2pe',3,7,'Mas os céus e a terra que agora existem pela mesma palavra se reservam como tesouro, e se guardam para o fogo, até o dia do juízo, e da perdição dos homens ímpios.'),
('acf','2pe',3,8,'Mas, amados, não ignoreis uma coisa, que um dia para o Senhor é como mil anos, e mil anos como um dia.'),
('acf','2pe',3,9,'O Senhor não retarda a sua promessa, ainda que alguns a têm por tardia; mas é longânimo para conosco, não querendo que alguns se percam, senão que todos venham a arrepender-se.'),
('acf','2pe',3,10,'Mas o dia do Senhor virá como o ladrão de noite; no qual os céus passarão com grande estrondo, e os elementos, ardendo, se desfarão, e a terra, e as obras que nela há, se queimarão.'),
('acf','2pe',3,11,'Havendo, pois, de perecer todas estas coisas, que pessoas vos convém ser em santo trato, e piedade,'),
('acf','2pe',3,12,'Aguardando, e apressando-vos para a vinda do dia de Deus, em que os céus, em fogo se desfarão, e os elementos, ardendo, se fundirão?'),
('acf','2pe',3,13,'Mas nós, segundo a sua promessa, aguardamos novos céus e nova terra, em que habita a justiça.'),
('acf','2pe',3,14,'Por isso, amados, aguardando estas coisas, procurai que dele sejais achados imaculados e irrepreensíveis em paz.'),
('acf','2pe',3,15,'E tende por salvação a longanimidade de nosso Senhor; como também o nosso amado irmão Paulo vos escreveu, segundo a sabedoria que lhe foi dada;'),
('acf','2pe',3,16,'Falando disto, como em todas as suas epístolas, entre as quais há pontos difíceis de entender, que os indoutos e inconstantes torcem, e igualmente as outras Escrituras, para sua própria perdição.'),
('acf','2pe',3,17,'Vós, portanto, amados, sabendo isto de antemão, guardai-vos de que, pelo engano dos homens abomináveis, sejais juntamente arrebatados, e descaiais da vossa firmeza;'),
('acf','2pe',3,18,'Antes crescei na graça e conhecimento de nosso Senhor e Salvador, Jesus Cristo. A ele seja dada a glória, assim agora, como no dia da eternidade. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1jo',1,1,'O que era desde o princípio, o que ouvimos, o que vimos com os nossos olhos, o que temos contemplado, e as nossas mãos tocaram da Palavra da vida'),
('acf','1jo',1,2,'(Porque a vida foi manifestada, e nós a vimos, e testificamos dela, e vos anunciamos a vida eterna, que estava com o Pai, e nos foi manifestada);'),
('acf','1jo',1,3,'O que vimos e ouvimos, isso vos anunciamos, para que também tenhais comunhão conosco; e a nossa comunhão é com o Pai, e com seu Filho Jesus Cristo.'),
('acf','1jo',1,4,'Estas coisas vos escrevemos, para que o vosso gozo se cumpra.'),
('acf','1jo',1,5,'E esta é a mensagem que dele ouvimos, e vos anunciamos: que Deus é luz, e não há nele trevas nenhumas.'),
('acf','1jo',1,6,'Se dissermos que temos comunhão com ele, e andarmos em trevas, mentimos, e não praticamos a verdade.'),
('acf','1jo',1,7,'Mas, se andarmos na luz, como ele na luz está, temos comunhão uns com os outros, e o sangue de Jesus Cristo, seu Filho, nos purifica de todo o pecado.'),
('acf','1jo',1,8,'Se dissermos que não temos pecado, enganamo-nos a nós mesmos, e não há verdade em nós.'),
('acf','1jo',1,9,'Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados, e nos purificar de toda a injustiça.'),
('acf','1jo',1,10,'Se dissermos que não pecamos, fazemo-lo mentiroso, e a sua palavra não está em nós.'),
('acf','1jo',2,1,'Meus filhinhos, estas coisas vos escrevo, para que não pequeis; e, se alguém pecar, temos um Advogado para com o Pai, Jesus Cristo, o justo.'),
('acf','1jo',2,2,'E ele é a propiciação pelos nossos pecados, e não somente pelos nossos, mas também pelos de todo o mundo.'),
('acf','1jo',2,3,'E nisto sabemos que o conhecemos: se guardarmos os seus mandamentos.'),
('acf','1jo',2,4,'Aquele que diz: Eu conheço-o, e não guarda os seus mandamentos, é mentiroso, e nele não está a verdade.'),
('acf','1jo',2,5,'Mas qualquer que guarda a sua palavra, o amor de Deus está nele verdadeiramente aperfeiçoado; nisto conhecemos que estamos nele.'),
('acf','1jo',2,6,'Aquele que diz que está nele, também deve andar como ele andou.'),
('acf','1jo',2,7,'Irmãos, não vos escrevo mandamento novo, mas o mandamento antigo, que desde o princípio tivestes. Este mandamento antigo é a palavra que desde o princípio ouvistes.'),
('acf','1jo',2,8,'Outra vez vos escrevo um mandamento novo, que é verdadeiro nele e em vós; porque vão passando as trevas, e já a verdadeira luz ilumina.'),
('acf','1jo',2,9,'Aquele que diz que está na luz, e odeia a seu irmão, até agora está em trevas.'),
('acf','1jo',2,10,'Aquele que ama a seu irmão está na luz, e nele não há escândalo.'),
('acf','1jo',2,11,'Mas aquele que odeia a seu irmão está em trevas, e anda em trevas, e não sabe para onde deva ir; porque as trevas lhe cegaram os olhos.'),
('acf','1jo',2,12,'Filhinhos, escrevo-vos, porque pelo seu nome vos são perdoados os pecados.'),
('acf','1jo',2,13,'Pais, escrevo-vos, porque conhecestes aquele que é desde o princípio. Jovens, escrevo-vos, porque vencestes o maligno. Eu vos escrevo, filhos, porque conhecestes o Pai.'),
('acf','1jo',2,14,'Eu vos escrevi, pais, porque já conhecestes aquele que é desde o princípio. Eu vos escrevi, jovens, porque sois fortes, e a palavra de Deus está em vós, e já vencestes o maligno.'),
('acf','1jo',2,15,'Não ameis o mundo, nem o que no mundo há. Se alguém ama o mundo, o amor do Pai não está nele.'),
('acf','1jo',2,16,'Porque tudo o que há no mundo, a concupiscência da carne, a concupiscência dos olhos e a soberba da vida, não é do Pai, mas do mundo.'),
('acf','1jo',2,17,'E o mundo passa, e a sua concupiscência; mas aquele que faz a vontade de Deus permanece para sempre.'),
('acf','1jo',2,18,'Filhinhos, é já a última hora; e, como ouvistes que vem o anticristo, também agora muitos se têm feito anticristos, por onde conhecemos que é já a última hora.'),
('acf','1jo',2,19,'Saíram de nós, mas não eram de nós; porque, se fossem de nós, ficariam conosco; mas isto é para que se manifestasse que não são todos de nós.'),
('acf','1jo',2,20,'E vós tendes a unção do Santo, e sabeis todas as coisas.'),
('acf','1jo',2,21,'Não vos escrevi porque não soubésseis a verdade, mas porque a sabeis, e porque nenhuma mentira vem da verdade.'),
('acf','1jo',2,22,'Quem é o mentiroso, senão aquele que nega que Jesus é o Cristo? É o anticristo esse mesmo que nega o Pai e o Filho.'),
('acf','1jo',2,23,'Qualquer que nega o Filho, também não tem o Pai; mas aquele que confessa o Filho, tem também o Pai.'),
('acf','1jo',2,24,'Portanto, o que desde o princípio ouvistes permaneça em vós. Se em vós permanecer o que desde o princípio ouvistes, também permanecereis no Filho e no Pai.'),
('acf','1jo',2,25,'E esta é a promessa que ele nos fez: a vida eterna.'),
('acf','1jo',2,26,'Estas coisas vos escrevi acerca dos que vos enganam.'),
('acf','1jo',2,27,'E a unção que vós recebestes dele, fica em vós, e não tendes necessidade de que alguém vos ensine; mas, como a sua unção vos ensina todas as coisas, e é verdadeira, e não é mentira, como ela vos ensinou, assim nele permanecereis.'),
('acf','1jo',2,28,'E agora, filhinhos, permanecei nele; para que, quando ele se manifestar, tenhamos confiança, e não sejamos confundidos por ele na sua vinda.'),
('acf','1jo',2,29,'Se sabeis que ele é justo, sabeis que todo aquele que pratica a justiça é nascido dele.'),
('acf','1jo',3,1,'Vede quão grande amor nos tem concedido o Pai, que fôssemos chamados filhos de Deus. Por isso o mundo não nos conhece; porque não o conhece a ele.'),
('acf','1jo',3,2,'Amados, agora somos filhos de Deus, e ainda não é manifestado o que havemos de ser. Mas sabemos que, quando ele se manifestar, seremos semelhantes a ele; porque assim como é o veremos.'),
('acf','1jo',3,3,'E qualquer que nele tem esta esperança purifica-se a si mesmo, como também ele é puro.'),
('acf','1jo',3,4,'Qualquer que comete pecado, também comete iniqüidade; porque o pecado é iniqüidade.'),
('acf','1jo',3,5,'E bem sabeis que ele se manifestou para tirar os nossos pecados; e nele não há pecado.'),
('acf','1jo',3,6,'Qualquer que permanece nele não peca; qualquer que peca não o viu nem o conheceu.'),
('acf','1jo',3,7,'Filhinhos, ninguém vos engane. Quem pratica justiça é justo, assim como ele é justo.'),
('acf','1jo',3,8,'Quem comete o pecado é do diabo; porque o diabo peca desde o princípio. Para isto o Filho de Deus se manifestou: para desfazer as obras do diabo.'),
('acf','1jo',3,9,'Qualquer que é nascido de Deus não comete pecado; porque a sua semente permanece nele; e não pode pecar, porque é nascido de Deus.'),
('acf','1jo',3,10,'Nisto são manifestos os filhos de Deus, e os filhos do diabo. Qualquer que não pratica a justiça, e não ama a seu irmão, não é de Deus.'),
('acf','1jo',3,11,'Porque esta é a mensagem que ouvistes desde o princípio: que nos amemos uns aos outros.'),
('acf','1jo',3,12,'Não como Caim, que era do maligno, e matou a seu irmão. E por que causa o matou? Porque as suas obras eram más e as de seu irmão justas.'),
('acf','1jo',3,13,'Meus irmãos, não vos maravilheis, se o mundo vos odeia.'),
('acf','1jo',3,14,'Nós sabemos que passamos da morte para a vida, porque amamos os irmãos. Quem não ama a seu irmão permanece na morte.'),
('acf','1jo',3,15,'Qualquer que odeia a seu irmão é homicida. E vós sabeis que nenhum homicida tem a vida eterna permanecendo nele.'),
('acf','1jo',3,16,'Conhecemos o amor nisto: que ele deu a sua vida por nós, e nós devemos dar a vida pelos irmãos.'),
('acf','1jo',3,17,'Quem, pois, tiver bens do mundo, e, vendo o seu irmão necessitado, lhe cerrar as suas entranhas, como estará nele o amor de Deus?'),
('acf','1jo',3,18,'Meus filhinhos, não amemos de palavra, nem de língua, mas por obra e em verdade.'),
('acf','1jo',3,19,'E nisto conhecemos que somos da verdade, e diante dele asseguraremos nossos corações;'),
('acf','1jo',3,20,'Sabendo que, se o nosso coração nos condena, maior é Deus do que o nosso coração, e conhece todas as coisas.'),
('acf','1jo',3,21,'Amados, se o nosso coração não nos condena, temos confiança para com Deus;'),
('acf','1jo',3,22,'E qualquer coisa que lhe pedirmos, dele a receberemos, porque guardamos os seus mandamentos, e fazemos o que é agradável à sua vista.'),
('acf','1jo',3,23,'E o seu mandamento é este: que creiamos no nome de seu Filho Jesus Cristo, e nos amemos uns aos outros, segundo o seu mandamento.'),
('acf','1jo',3,24,'E aquele que guarda os seus mandamentos nele está, e ele nele. E nisto conhecemos que ele está em nós, pelo Espírito que nos tem dado.'),
('acf','1jo',4,1,'Amados, não creiais a todo o espírito, mas provai se os espíritos são de Deus, porque já muitos falsos profetas se têm levantado no mundo.'),
('acf','1jo',4,2,'Nisto conhecereis o Espírito de Deus: Todo o espírito que confessa que Jesus Cristo veio em carne é de Deus;'),
('acf','1jo',4,3,'E todo o espírito que não confessa que Jesus Cristo veio em carne não é de Deus; mas este é o espírito do anticristo, do qual já ouvistes que há de vir, e eis que já agora está no mundo.'),
('acf','1jo',4,4,'Filhinhos, sois de Deus, e já os tendes vencido; porque maior é o que está em vós do que o que está no mundo.'),
('acf','1jo',4,5,'Do mundo são, por isso falam do mundo, e o mundo os ouve.'),
('acf','1jo',4,6,'Nós somos de Deus; aquele que conhece a Deus ouve-nos; aquele que não é de Deus não nos ouve. Nisto conhecemos nós o espírito da verdade e o espírito do erro.'),
('acf','1jo',4,7,'Amados, amemo-nos uns aos outros; porque o amor é de Deus; e qualquer que ama é nascido de Deus e conhece a Deus.'),
('acf','1jo',4,8,'Aquele que não ama não conhece a Deus; porque Deus é amor.'),
('acf','1jo',4,9,'Nisto se manifestou o amor de Deus para conosco: que Deus enviou seu Filho unigênito ao mundo, para que por ele vivamos.'),
('acf','1jo',4,10,'Nisto está o amor, não em que nós tenhamos amado a Deus, mas em que ele nos amou a nós, e enviou seu Filho para propiciação pelos nossos pecados.'),
('acf','1jo',4,11,'Amados, se Deus assim nos amou, também nòs devemos amar uns aos outros.'),
('acf','1jo',4,12,'Ninguém jamais viu a Deus; se nos amamos uns aos outros, Deus está em nós, e em nós é perfeito o seu amor.'),
('acf','1jo',4,13,'Nisto conhecemos que estamos nele, e ele em nós, pois que nos deu do seu Espírito.'),
('acf','1jo',4,14,'E vimos, e testificamos que o Pai enviou seu Filho para Salvador do mundo.'),
('acf','1jo',4,15,'Qualquer que confessar que Jesus é o Filho de Deus, Deus está nele, e ele em Deus.'),
('acf','1jo',4,16,'E nós conhecemos, e cremos no amor que Deus nos tem. Deus é amor; e quem está em amor está em Deus, e Deus nele.'),
('acf','1jo',4,17,'Nisto é perfeito o amor para conosco, para que no dia do juízo tenhamos confiança; porque, qual ele é, somos nós também neste mundo.'),
('acf','1jo',4,18,'No amor não há temor, antes o perfeito amor lança fora o temor; porque o temor tem consigo a pena, e o que teme não é perfeito em amor.'),
('acf','1jo',4,19,'Nós o amamos a ele porque ele nos amou primeiro.'),
('acf','1jo',4,20,'Se alguém diz: Eu amo a Deus, e odeia a seu irmão, é mentiroso. Pois quem não ama a seu irmão, ao qual viu, como pode amar a Deus, a quem não viu?'),
('acf','1jo',4,21,'E dele temos este mandamento: que quem ama a Deus, ame também a seu irmão.'),
('acf','1jo',5,1,'Todo aquele que crê que Jesus é o Cristo, é nascido de Deus; e todo aquele que ama ao que o gerou também ama ao que dele é nascido.'),
('acf','1jo',5,2,'Nisto conhecemos que amamos os filhos de Deus, quando amamos a Deus e guardamos os seus mandamentos.'),
('acf','1jo',5,3,'Porque este é o amor de Deus: que guardemos os seus mandamentos; e os seus mandamentos não são pesados.'),
('acf','1jo',5,4,'Porque todo o que é nascido de Deus vence o mundo; e esta é a vitória que vence o mundo, a nossa fé.'),
('acf','1jo',5,5,'Quem é que vence o mundo, senão aquele que crê que Jesus é o Filho de Deus?'),
('acf','1jo',5,6,'Este é aquele que veio por água e sangue, isto é, Jesus Cristo; não só por água, mas por água e por sangue. E o Espírito é o que testifica, porque o Espírito é a verdade.'),
('acf','1jo',5,7,'Porque três são os que testificam no céu: o Pai, a Palavra, e o Espírito Santo; e estes três são um.'),
('acf','1jo',5,8,'E três são os que testificam na terra: o Espírito, e a água e o sangue; e estes três concordam num.'),
('acf','1jo',5,9,'Se recebemos o testemunho dos homens, o testemunho de Deus é maior; porque o testemunho de Deus é este, que de seu Filho testificou.'),
('acf','1jo',5,10,'Quem crê no Filho de Deus, em si mesmo tem o testemunho; quem a Deus não crê mentiroso o fez, porquanto não creu no testemunho que Deus de seu Filho deu.'),
('acf','1jo',5,11,'E o testemunho é este: que Deus nos deu a vida eterna; e esta vida está em seu Filho.'),
('acf','1jo',5,12,'Quem tem o Filho tem a vida; quem não tem o Filho de Deus não tem a vida.'),
('acf','1jo',5,13,'Estas coisas vos escrevi a vós, os que credes no nome do Filho de Deus, para que saibais que tendes a vida eterna, e para que creiais no nome do Filho de Deus.'),
('acf','1jo',5,14,'E esta é a confiança que temos nele, que, se pedirmos alguma coisa, segundo a sua vontade, ele nos ouve.'),
('acf','1jo',5,15,'E, se sabemos que nos ouve em tudo o que pedimos, sabemos que alcançamos as petições que lhe fizemos.'),
('acf','1jo',5,16,'Se alguém vir pecar seu irmão, pecado que não é para morte, orará, e Deus dará a vida àqueles que não pecarem para morte. Há pecado para morte, e por esse não digo que ore.'),
('acf','1jo',5,17,'Toda a iniqüidade é pecado, e há pecado que não é para morte.'),
('acf','1jo',5,18,'Sabemos que todo aquele que é nascido de Deus não peca; mas o que de Deus é gerado conserva-se a si mesmo, e o maligno não lhe toca.'),
('acf','1jo',5,19,'Sabemos que somos de Deus, e que todo o mundo está no maligno.'),
('acf','1jo',5,20,'E sabemos que já o Filho de Deus é vindo, e nos deu entendimento para que conheçamos ao Verdadeiro; e no que é verdadeiro estamos, isto é, em seu Filho Jesus Cristo. Este é o verdadeiro Deus e a vida eterna.'),
('acf','1jo',5,21,'Filhinhos, guardai-vos dos ídolos. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2jo',1,1,'O ancião à senhora eleita, e a seus filhos, aos quais amo na verdade, e não somente eu, mas também todos os que têm conhecido a verdade,'),
('acf','2jo',1,2,'Por amor da verdade que está em nós, e para sempre estará conosco:'),
('acf','2jo',1,3,'Graça, misericórdia e paz, da parte de Deus Pai e da do Senhor Jesus Cristo, o Filho do Pai, seja convosco na verdade e amor.'),
('acf','2jo',1,4,'Muito me alegro por achar que alguns de teus filhos andam na verdade, assim como temos recebido o mandamento do Pai.'),
('acf','2jo',1,5,'E agora, senhora, rogo-te, não como escrevendo-te um novo mandamento, mas aquele mesmo que desde o princípio tivemos: que nos amemos uns aos outros.'),
('acf','2jo',1,6,'E o amor é este: que andemos segundo os seus mandamentos. Este é o mandamento, como já desde o princípio ouvistes, que andeis nele.'),
('acf','2jo',1,7,'Porque já muitos enganadores entraram no mundo, os quais não confessam que Jesus Cristo veio em carne. Este tal é o enganador e o anticristo.'),
('acf','2jo',1,8,'Olhai por vós mesmos, para que não percamos o que temos ganho, antes recebamos o inteiro galardão.'),
('acf','2jo',1,9,'Todo aquele que prevarica, e não persevera na doutrina de Cristo, não tem a Deus. Quem persevera na doutrina de Cristo, esse tem tanto ao Pai como ao Filho.'),
('acf','2jo',1,10,'Se alguém vem ter convosco, e não traz esta doutrina, não o recebais em casa, nem tampouco o saudeis.'),
('acf','2jo',1,11,'Porque quem o saúda tem parte nas suas más obras.'),
('acf','2jo',1,12,'Tendo muito que escrever-vos, não quis fazê-lo com papel e tinta; mas espero ir ter convosco e falar face a face, para que o nosso gozo seja cumprido.'),
('acf','2jo',1,13,'Saúdam-te os filhos de tua irmã, a eleita. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','3jo',1,1,'O presbítero ao amado Gaio, a quem em verdade eu amo.'),
('acf','3jo',1,2,'Amado, desejo que te vá bem em todas as coisas, e que tenhas saúde, assim como bem vai a tua alma.'),
('acf','3jo',1,3,'Porque muito me alegrei quando os irmãos vieram, e testificaram da tua verdade, como tu andas na verdade.'),
('acf','3jo',1,4,'Não tenho maior gozo do que este, o de ouvir que os meus filhos andam na verdade.'),
('acf','3jo',1,5,'Amado, procedes fielmente em tudo o que fazes para com os irmãos, e para com os estranhos,'),
('acf','3jo',1,6,'Que em presença da igreja testificaram do teu amor; aos quais, se conduzires como é digno para com Deus, bem farás;'),
('acf','3jo',1,7,'Porque pelo seu Nome saíram, nada tomando dos gentios.'),
('acf','3jo',1,8,'Portanto, aos tais devemos receber, para que sejamos cooperadores da verdade.'),
('acf','3jo',1,9,'Tenho escrito à igreja; mas Diótrefes, que procura ter entre eles o primado, não nos recebe.'),
('acf','3jo',1,10,'Por isso, se eu for, trarei à memória as obras que ele faz, proferindo contra nós palavras maliciosas; e, não contente com isto, não recebe os irmãos, e impede os que querem recebê-los, e os lança fora da igreja.'),
('acf','3jo',1,11,'Amado, não sigas o mal, mas o bem. Quem faz o bem é de Deus; mas quem faz o mal não tem visto a Deus.'),
('acf','3jo',1,12,'Todos dão testemunho de Demétrio, até a mesma verdade; e também nós testemunhamos; e vós bem sabeis que o nosso testemunho é verdadeiro.'),
('acf','3jo',1,13,'Tinha muito que escrever, mas não quero escrever-te com tinta e pena.'),
('acf','3jo',1,14,'Espero, porém, ver-te brevemente, e falaremos face a face.'),
('acf','3jo',1,15,'Paz seja contigo. Os amigos te saúdam. Saúda os amigos por nome.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','jd',1,1,'Judas, servo de Jesus Cristo, e irmão de Tiago, aos chamados, santificados em Deus Pai, e conservados por Jesus Cristo:'),
('acf','jd',1,2,'Misericórdia, e paz, e amor vos sejam multiplicados.'),
('acf','jd',1,3,'Amados, procurando eu escrever-vos com toda a diligência acerca da salvação comum, tive por necessidade escrever-vos, e exortar-vos a batalhar pela fé que uma vez foi dada aos santos.'),
('acf','jd',1,4,'Porque se introduziram alguns, que já antes estavam escritos para este mesmo juízo, homens ímpios, que convertem em dissolução a graça de Deus, e negam a Deus, único dominador e Senhor nosso, Jesus Cristo.'),
('acf','jd',1,5,'Mas quero lembrar-vos, como a quem já uma vez soube isto, que, havendo o Senhor salvo um povo, tirando-o da terra do Egito, destruiu depois os que não creram;'),
('acf','jd',1,6,'E aos anjos que não guardaram o seu principado, mas deixaram a sua própria habitação, reservou na escuridão e em prisões eternas até ao juízo daquele grande dia;'),
('acf','jd',1,7,'Assim como Sodoma e Gomorra, e as cidades circunvizinhas, que, havendo-se entregue à fornicação como aqueles, e ido após outra carne, foram postas por exemplo, sofrendo a pena do fogo eterno.'),
('acf','jd',1,8,'E, contudo, também estes, semelhantemente adormecidos, contaminam a sua carne, e rejeitam a dominação, e vituperam as dignidades.'),
('acf','jd',1,9,'Mas o arcanjo Miguel, quando contendia com o diabo, e disputava a respeito do corpo de Moisés, não ousou pronunciar juízo de maldição contra ele; mas disse: O Senhor te repreenda.'),
('acf','jd',1,10,'Estes, porém, dizem mal do que não sabem; e, naquilo que naturalmente conhecem, como animais irracionais se corrompem.'),
('acf','jd',1,11,'Ai deles! porque entraram pelo caminho de Caim, e foram levados pelo engano do prêmio de Balaão, e pereceram na contradição de Coré.'),
('acf','jd',1,12,'Estes são manchas em vossas festas de amor, banqueteando-se convosco, e apascentando-se a si mesmos sem temor; são nuvens sem água, levadas pelos ventos de uma para outra parte; são como árvores murchas, infrutíferas, duas vezes mortas, desarraigadas;'),
('acf','jd',1,13,'Ondas impetuosas do mar, que escumam as suas mesmas abominações; estrelas errantes, para os quais está eternamente reservada a negrura das trevas.'),
('acf','jd',1,14,'E destes profetizou também Enoque, o sétimo depois de Adão, dizendo: Eis que é vindo o Senhor com milhares de seus santos;'),
('acf','jd',1,15,'Para fazer juízo contra todos e condenar dentre eles todos os ímpios, por todas as suas obras de impiedade, que impiamente cometeram, e por todas as duras palavras que ímpios pecadores disseram contra ele.'),
('acf','jd',1,16,'Estes são murmuradores, queixosos da sua sorte, andando segundo as suas concupiscências, e cuja boca diz coisas mui arrogantes, admirando as pessoas por causa do interesse.'),
('acf','jd',1,17,'Mas vós, amados, lembrai-vos das palavras que vos foram preditas pelos apóstolos de nosso Senhor Jesus Cristo;'),
('acf','jd',1,18,'Os quais vos diziam que nos últimos tempos haveria escarnecedores que andariam segundo as suas ímpias concupiscências.'),
('acf','jd',1,19,'Estes são os que a si mesmos se separam, sensuais, que não têm o Espírito.'),
('acf','jd',1,20,'Mas vós, amados, edificando-vos a vós mesmos sobre a vossa santíssima fé, orando no Espírito Santo,'),
('acf','jd',1,21,'Conservai-vos a vós mesmos no amor de Deus, esperando a misericórdia de nosso Senhor Jesus Cristo para a vida eterna.'),
('acf','jd',1,22,'E apiedai-vos de alguns, usando de discernimento;'),
('acf','jd',1,23,'E salvai alguns com temor, arrebatando-os do fogo, odiando até a túnica manchada da carne.'),
('acf','jd',1,24,'Ora, àquele que é poderoso para vos guardar de tropeçar, e apresentar-vos irrepreensíveis, com alegria, perante a sua glória,'),
('acf','jd',1,25,'Ao único Deus sábio, Salvador nosso, seja glória e majestade, domínio e poder, agora, e para todo o sempre. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ap',1,1,'Revelação de Jesus Cristo, a qual Deus lhe deu, para mostrar aos seus servos as coisas que brevemente devem acontecer; e pelo seu anjo as enviou, e as notificou a João seu servo;'),
('acf','ap',1,2,'O qual testificou da palavra de Deus, e do testemunho de Jesus Cristo, e de tudo o que tem visto.'),
('acf','ap',1,3,'Bem-aventurado aquele que lê, e os que ouvem as palavras desta profecia, e guardam as coisas que nela estão escritas; porque o tempo está próximo.'),
('acf','ap',1,4,'João, às sete igrejas que estão na Ásia: Graça e paz seja convosco da parte daquele que é, e que era, e que há de vir, e da dos sete espíritos que estão diante do seu trono;'),
('acf','ap',1,5,'E da parte de Jesus Cristo, que é a fiel testemunha, o primogênito dentre os mortos e o príncipe dos reis da terra. Àquele que nos amou, e em seu sangue nos lavou dos nossos pecados,'),
('acf','ap',1,6,'E nos fez reis e sacerdotes para Deus e seu Pai; a ele glória e poder para todo o sempre. Amém.'),
('acf','ap',1,7,'Eis que vem com as nuvens, e todo o olho o verá, até os mesmos que o traspassaram; e todas as tribos da terra se lamentarão sobre ele. Sim. Amém.'),
('acf','ap',1,8,'Eu sou o Alfa e o Ômega, o princípio e o fim, diz o Senhor, que é, e que era, e que há de vir, o Todo-Poderoso.'),
('acf','ap',1,9,'Eu, João, que também sou vosso irmão, e companheiro na aflição, e no reino, e paciência de Jesus Cristo, estava na ilha chamada Patmos, por causa da palavra de Deus, e pelo testemunho de Jesus Cristo.'),
('acf','ap',1,10,'Eu fui arrebatado no Espírito no dia do Senhor, e ouvi detrás de mim uma grande voz, como de trombeta,'),
('acf','ap',1,11,'Que dizia: Eu sou o Alfa e o Ômega, o primeiro e o derradeiro; e o que vês, escreve-o num livro, e envia-o às sete igrejas que estão na Ásia: a Éfeso, e a Esmirna, e a Pérgamo, e a Tiatira, e a Sardes, e a Filadélfia, e a Laodicéia.'),
('acf','ap',1,12,'E virei-me para ver quem falava comigo. E, virando-me, vi sete castiçais de ouro;'),
('acf','ap',1,13,'E no meio dos sete castiçais um semelhante ao Filho do homem, vestido até aos pés de uma roupa comprida, e cingido pelos peitos com um cinto de ouro.'),
('acf','ap',1,14,'E a sua cabeça e cabelos eram brancos como lã branca, como a neve, e os seus olhos como chama de fogo;'),
('acf','ap',1,15,'E os seus pés, semelhantes a latão reluzente, como se tivessem sido refinados numa fornalha, e a sua voz como a voz de muitas águas.'),
('acf','ap',1,16,'E ele tinha na sua destra sete estrelas; e da sua boca saía uma aguda espada de dois fios; e o seu rosto era como o sol, quando na sua força resplandece.'),
('acf','ap',1,17,'E eu, quando o vi, caí a seus pés como morto; e ele pôs sobre mim a sua destra, dizendo-me: Não temas; Eu sou o primeiro e o último;'),
('acf','ap',1,18,'E o que vivo e fui morto, mas eis aqui estou vivo para todo o sempre. Amém. E tenho as chaves da morte e do inferno.'),
('acf','ap',1,19,'Escreve as coisas que tens visto, e as que são, e as que depois destas hão de acontecer;'),
('acf','ap',1,20,'O mistério das sete estrelas, que viste na minha destra, e dos sete castiçais de ouro. As sete estrelas são os anjos das sete igrejas, e os sete castiçais, que viste, são as sete igrejas.'),
('acf','ap',2,1,'Escreve ao anjo da igreja de Éfeso: Isto diz aquele que tem na sua destra as sete estrelas, que anda no meio dos sete castiçais de ouro:'),
('acf','ap',2,2,'Conheço as tuas obras, e o teu trabalho, e a tua paciência, e que não podes sofrer os maus; e puseste à prova os que dizem ser apóstolos, e o não são, e tu os achaste mentirosos.'),
('acf','ap',2,3,'E sofreste, e tens paciência; e trabalhaste pelo meu nome, e não te cansaste.'),
('acf','ap',2,4,'Tenho, porém, contra ti que deixaste o teu primeiro amor.'),
('acf','ap',2,5,'Lembra-te, pois, de onde caíste, e arrepende-te, e pratica as primeiras obras; quando não, brevemente a ti virei, e tirarei do seu lugar o teu castiçal, se não te arrependeres.'),
('acf','ap',2,6,'Tens, porém, isto: que odeias as obras dos nicolaítas, as quais eu também odeio.'),
('acf','ap',2,7,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: Ao que vencer, dar-lhe-ei a comer da árvore da vida, que está no meio do paraíso de Deus.'),
('acf','ap',2,8,'E ao anjo da igreja em Esmirna, escreve: Isto diz o primeiro e o último, que foi morto, e reviveu:'),
('acf','ap',2,9,'Conheço as tuas obras, e tribulação, e pobreza (mas tu és rico), e a blasfêmia dos que se dizem judeus, e não o são, mas são a sinagoga de Satanás.'),
('acf','ap',2,10,'Nada temas das coisas que hás de padecer. Eis que o diabo lançará alguns de vós na prisão, para que sejais tentados; e tereis uma tribulação de dez dias. Sê fiel até à morte, e dar-te-ei a coroa da vida.'),
('acf','ap',2,11,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: O que vencer não receberá o dano da segunda morte.'),
('acf','ap',2,12,'E ao anjo da igreja que está em Pérgamo escreve: Isto diz aquele que tem a espada aguda de dois fios:'),
('acf','ap',2,13,'Conheço as tuas obras, e onde habitas, que é onde está o trono de Satanás; e reténs o meu nome, e não negaste a minha fé, ainda nos dias de Antipas, minha fiel testemunha, o qual foi morto entre vós, onde Satanás habita.'),
('acf','ap',2,14,'Mas algumas poucas coisas tenho contra ti, porque tens lá os que seguem a doutrina de Balaão, o qual ensinava Balaque a lançar tropeços diante dos filhos de Israel, para que comessem dos sacrifícios da idolatria, e fornicassem.'),
('acf','ap',2,15,'Assim tens também os que seguem a doutrina dos nicolaítas, o que eu odeio.'),
('acf','ap',2,16,'Arrepende-te, pois, quando não em breve virei a ti, e contra eles batalharei com a espada da minha boca.'),
('acf','ap',2,17,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: Ao que vencer darei eu a comer do maná escondido, e dar-lhe-ei uma pedra branca, e na pedra um novo nome escrito, o qual ninguém conhece senão aquele que o recebe.'),
('acf','ap',2,18,'E ao anjo da igreja de Tiatira escreve: Isto diz o Filho de Deus, que tem seus olhos como chama de fogo, e os pés semelhantes ao latão reluzente:'),
('acf','ap',2,19,'Eu conheço as tuas obras, e o teu amor, e o teu serviço, e a tua fé, e a tua paciência, e que as tuas últimas obras são mais do que as primeiras.'),
('acf','ap',2,20,'Mas algumas poucas coisas tenho contra ti que deixas Jezabel, mulher que se diz profetisa, ensinar e enganar os meus servos, para que forniquem e comam dos sacrifícios da idolatria.'),
('acf','ap',2,21,'E dei-lhe tempo para que se arrependesse da sua fornicação; e não se arrependeu.'),
('acf','ap',2,22,'Eis que a porei numa cama, e sobre os que adulteram com ela virá grande tribulação, se não se arrependerem das suas obras.'),
('acf','ap',2,23,'E ferirei de morte a seus filhos, e todas as igrejas saberão que eu sou aquele que sonda os rins e os corações. E darei a cada um de vós segundo as vossas obras.'),
('acf','ap',2,24,'Mas eu vos digo a vós, e aos restantes que estão em Tiatira, a todos quantos não têm esta doutrina, e não conheceram, como dizem, as profundezas de Satanás, que outra carga vos não porei.'),
('acf','ap',2,25,'Mas o que tendes, retende-o até que eu venha.'),
('acf','ap',2,26,'E ao que vencer, e guardar até ao fim as minhas obras, eu lhe darei poder sobre as nações,'),
('acf','ap',2,27,'E com vara de ferro as regerá; e serão quebradas como vasos de oleiro; como também recebi de meu Pai.'),
('acf','ap',2,28,'E dar-lhe-ei a estrela da manhã.'),
('acf','ap',2,29,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
('acf','ap',3,1,'E ao anjo da igreja que está em Sardes escreve: Isto diz o que tem os sete espíritos de Deus, e as sete estrelas: Conheço as tuas obras, que tens nome de que vives, e estás morto.'),
('acf','ap',3,2,'Sê vigilante, e confirma os restantes, que estavam para morrer; porque não achei as tuas obras perfeitas diante de Deus.'),
('acf','ap',3,3,'Lembra-te, pois, do que tens recebido e ouvido, e guarda-o, e arrepende-te. E, se não vigiares, virei sobre ti como um ladrão, e não saberás a que hora sobre ti virei.'),
('acf','ap',3,4,'Mas também tens em Sardes algumas poucas pessoas que não contaminaram suas vestes, e comigo andarão de branco; porquanto são dignas disso.'),
('acf','ap',3,5,'O que vencer será vestido de vestes brancas, e de maneira nenhuma riscarei o seu nome do livro da vida; e confessarei o seu nome diante de meu Pai e diante dos seus anjos.'),
('acf','ap',3,6,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
('acf','ap',3,7,'E ao anjo da igreja que está em Filadélfia escreve: Isto diz o que é santo, o que é verdadeiro, o que tem a chave de Davi; o que abre, e ninguém fecha; e fecha, e ninguém abre:'),
('acf','ap',3,8,'Conheço as tuas obras; eis que diante de ti pus uma porta aberta, e ninguém a pode fechar; tendo pouca força, guardaste a minha palavra, e não negaste o meu nome.'),
('acf','ap',3,9,'Eis que eu farei aos da sinagoga de Satanás, aos que se dizem judeus, e não são, mas mentem: eis que eu farei que venham, e adorem prostrados a teus pés, e saibam que eu te amo.'),
('acf','ap',3,10,'Como guardaste a palavra da minha paciência, também eu te guardarei da hora da tentação que há de vir sobre todo o mundo, para tentar os que habitam na terra.'),
('acf','ap',3,11,'Eis que venho sem demora; guarda o que tens, para que ninguém tome a tua coroa.'),
('acf','ap',3,12,'A quem vencer, eu o farei coluna no templo do meu Deus, e dele nunca sairá; e escreverei sobre ele o nome do meu Deus, e o nome da cidade do meu Deus, a nova Jerusalém, que desce do céu, do meu Deus, e também o meu novo nome.'),
('acf','ap',3,13,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
('acf','ap',3,14,'E ao anjo da igreja de Laodicéia escreve: Isto diz o Amém, a testemunha fiel e verdadeira, o princípio da criação de Deus:'),
('acf','ap',3,15,'Conheço as tuas obras, que nem és frio nem quente; quem dera foras frio ou quente!'),
('acf','ap',3,16,'Assim, porque és morno, e não és frio nem quente, vomitar-te-ei da minha boca.'),
('acf','ap',3,17,'Como dizes: Rico sou, e estou enriquecido, e de nada tenho falta; e não sabes que és um desgraçado, e miserável, e pobre, e cego, e nu;'),
('acf','ap',3,18,'Aconselho-te que de mim compres ouro provado no fogo, para que te enriqueças; e roupas brancas, para que te vistas, e não apareça a vergonha da tua nudez; e que unjas os teus olhos com colírio, para que vejas.'),
('acf','ap',3,19,'Eu repreendo e castigo a todos quantos amo; sê pois zeloso, e arrepende-te.'),
('acf','ap',3,20,'Eis que estou à porta, e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei em sua casa, e com ele cearei, e ele comigo.'),
('acf','ap',3,21,'Ao que vencer lhe concederei que se assente comigo no meu trono; assim como eu venci, e me assentei com meu Pai no seu trono.'),
('acf','ap',3,22,'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
('acf','ap',4,1,'Depois destas coisas, olhei, e eis que estava uma porta aberta no céu; e a primeira voz, que como de trombeta ouvira falar comigo, disse: Sobe aqui, e mostrar-te-ei as coisas que depois destas devem acontecer.'),
('acf','ap',4,2,'E logo fui arrebatado em espírito, e eis que um trono estava posto no céu, e um assentado sobre o trono.'),
('acf','ap',4,3,'E o que estava assentado era, na aparência, semelhante à pedra jaspe e sardônica; e o arco celeste estava ao redor do trono, e parecia semelhante à esmeralda.'),
('acf','ap',4,4,'E ao redor do trono havia vinte e quatro tronos; e vi assentados sobre os tronos vinte e quatro anciãos vestidos de vestes brancas; e tinham sobre suas cabeças coroas de ouro.'),
('acf','ap',4,5,'E do trono saíam relâmpagos, e trovões, e vozes; e diante do trono ardiam sete lâmpadas de fogo, as quais são os sete espíritos de Deus.'),
('acf','ap',4,6,'E havia diante do trono um como mar de vidro, semelhante ao cristal. E no meio do trono, e ao redor do trono, quatro animais cheios de olhos, por diante e por detrás.'),
('acf','ap',4,7,'E o primeiro animal era semelhante a um leão, e o segundo animal semelhante a um bezerro, e tinha o terceiro animal o rosto como de homem, e o quarto animal era semelhante a uma águia voando.'),
('acf','ap',4,8,'E os quatro animais tinham, cada um de per si, seis asas, e ao redor, e por dentro, estavam cheios de olhos; e não descansam nem de dia nem de noite, dizendo: Santo, Santo, Santo, é o Senhor Deus, o Todo-Poderoso, que era, e que é, e que há de vir.'),
('acf','ap',4,9,'E, quando os animais davam glória, e honra, e ações de graças ao que estava assentado sobre o trono, ao que vive para todo o sempre,'),
('acf','ap',4,10,'Os vinte e quatro anciãos prostravam-se diante do que estava assentado sobre o trono, e adoravam o que vive para todo o sempre; e lançavam as suas coroas diante do trono, dizendo:'),
('acf','ap',4,11,'Digno és, Senhor, de receber glória, e honra, e poder; porque tu criaste todas as coisas, e por tua vontade são e foram criadas.'),
('acf','ap',5,1,'E vi na destra do que estava assentado sobre o trono um livro escrito por dentro e por fora, selado com sete selos.'),
('acf','ap',5,2,'E vi um anjo forte, bradando com grande voz: Quem é digno de abrir o livro e de desatar os seus selos?'),
('acf','ap',5,3,'E ninguém no céu, nem na terra, nem debaixo da terra, podia abrir o livro, nem olhar para ele.'),
('acf','ap',5,4,'E eu chorava muito, porque ninguém fora achado digno de abrir o livro, nem de o ler, nem de olhar para ele.'),
('acf','ap',5,5,'E disse-me um dos anciãos: Não chores; eis aqui o Leão da tribo de Judá, a raiz de Davi, que venceu, para abrir o livro e desatar os seus sete selos.'),
('acf','ap',5,6,'E olhei, e eis que estava no meio do trono e dos quatro animais viventes e entre os anciãos um Cordeiro, como havendo sido morto, e tinha sete pontas e sete olhos, que são os sete espíritos de Deus enviados a toda a terra.'),
('acf','ap',5,7,'E veio, e tomou o livro da destra do que estava assentado no trono.'),
('acf','ap',5,8,'E, havendo tomado o livro, os quatro animais e os vinte e quatro anciãos prostraram-se diante do Cordeiro, tendo todos eles harpas e salvas de ouro cheias de incenso, que são as orações dos santos.'),
('acf','ap',5,9,'E cantavam um novo cântico, dizendo: Digno és de tomar o livro, e de abrir os seus selos; porque foste morto, e com o teu sangue nos compraste para Deus de toda a tribo, e língua, e povo, e nação;'),
('acf','ap',5,10,'E para o nosso Deus nos fizeste reis e sacerdotes; e reinaremos sobre a terra.'),
('acf','ap',5,11,'E olhei, e ouvi a voz de muitos anjos ao redor do trono, e dos animais, e dos anciãos; e era o número deles milhões de milhões, e milhares de milhares,'),
('acf','ap',5,12,'Que com grande voz diziam: Digno é o Cordeiro, que foi morto, de receber o poder, e riquezas, e sabedoria, e força, e honra, e glória, e ações de graças.'),
('acf','ap',5,13,'E ouvi a toda a criatura que está no céu, e na terra, e debaixo da terra, e que estão no mar, e a todas as coisas que neles há, dizer: Ao que está assentado sobre o trono, e ao Cordeiro, sejam dadas ações de graças, e honra, e glória, e poder para todo o sempre.'),
('acf','ap',5,14,'E os quatro animais diziam: Amém. E os vinte e quatro anciãos prostraram-se, e adoraram ao que vive para todo o sempre.'),
('acf','ap',6,1,'E, havendo o Cordeiro aberto um dos selos, olhei, e ouvi um dos quatro animais, que dizia como em voz de trovão: Vem, e vê.'),
('acf','ap',6,2,'E olhei, e eis um cavalo branco; e o que estava assentado sobre ele tinha um arco; e foi-lhe dada uma coroa, e saiu vitorioso, e para vencer.'),
('acf','ap',6,3,'E, havendo aberto o segundo selo, ouvi o segundo animal, dizendo: Vem, e vê.'),
('acf','ap',6,4,'E saiu outro cavalo, vermelho; e ao que estava assentado sobre ele foi dado que tirasse a paz da terra, e que se matassem uns aos outros; e foi-lhe dada uma grande espada.'),
('acf','ap',6,5,'E, havendo aberto o terceiro selo, ouvi dizer o terceiro animal: Vem, e vê. E olhei, e eis um cavalo preto e o que sobre ele estava assentado tinha uma balança em sua mão.'),
('acf','ap',6,6,'E ouvi uma voz no meio dos quatro animais, que dizia: Uma medida de trigo por um dinheiro, e três medidas de cevada por um dinheiro; e não danifiques o azeite e o vinho.'),
('acf','ap',6,7,'E, havendo aberto o quarto selo, ouvi a voz do quarto animal, que dizia: Vem, e vê.'),
('acf','ap',6,8,'E olhei, e eis um cavalo amarelo, e o que estava assentado sobre ele tinha por nome Morte; e o inferno o seguia; e foi-lhes dado poder para matar a quarta parte da terra, com espada, e com fome, e com peste, e com as feras da terra.'),
('acf','ap',6,9,'E, havendo aberto o quinto selo, vi debaixo do altar as almas dos que foram mortos por amor da palavra de Deus e por amor do testemunho que deram.'),
('acf','ap',6,10,'E clamavam com grande voz, dizendo: Até quando, ó verdadeiro e santo Dominador, não julgas e vingas o nosso sangue dos que habitam sobre a terra?'),
('acf','ap',6,11,'E foram dadas a cada um compridas vestes brancas e foi-lhes dito que repousassem ainda um pouco de tempo, até que também se completasse o número de seus conservos e seus irmãos, que haviam de ser mortos como eles foram.'),
('acf','ap',6,12,'E, havendo aberto o sexto selo, olhei, e eis que houve um grande tremor de terra; e o sol tornou-se negro como saco de cilício, e a lua tornou-se como sangue;'),
('acf','ap',6,13,'E as estrelas do céu caíram sobre a terra, como quando a figueira lança de si os seus figos verdes, abalada por um vento forte.'),
('acf','ap',6,14,'E o céu retirou-se como um livro que se enrola; e todos os montes e ilhas foram removidos dos seus lugares.'),
('acf','ap',6,15,'E os reis da terra, e os grandes, e os ricos, e os tribunos, e os poderosos, e todo o servo, e todo o livre, se esconderam nas cavernas e nas rochas das montanhas;'),
('acf','ap',6,16,'E diziam aos montes e aos rochedos: Caí sobre nós, e escondei-nos do rosto daquele que está assentado sobre o trono, e da ira do Cordeiro;'),
('acf','ap',6,17,'Porque é vindo o grande dia da sua ira; e quem poderá subsistir?'),
('acf','ap',7,1,'E depois destas coisas vi quatro anjos que estavam sobre os quatro cantos da terra, retendo os quatro ventos da terra, para que nenhum vento soprasse sobre a terra, nem sobre o mar, nem contra árvore alguma.'),
('acf','ap',7,2,'E vi outro anjo subir do lado do sol nascente, e que tinha o selo do Deus vivo; e clamou com grande voz aos quatro anjos, a quem fora dado o poder de danificar a terra e o mar,'),
('acf','ap',7,3,'Dizendo: Não danifiqueis a terra, nem o mar, nem as árvores, até que hajamos selado nas suas testas os servos do nosso Deus.'),
('acf','ap',7,4,'E ouvi o número dos selados, e eram cento e quarenta e quatro mil selados, de todas as tribos dos filhos de Israel.'),
('acf','ap',7,5,'Da tribo de Judá, havia doze mil selados; da tribo de Rúbem, doze mil selados; da tribo de Gade, doze mil selados;'),
('acf','ap',7,6,'Da tribo de Aser, doze mil selados; da tribo de Naftali, doze mil selados; da tribo de Manassés, doze mil selados;'),
('acf','ap',7,7,'Da tribo de Simeão, doze mil selados; da tribo de Levi, doze mil selados; da tribo de Issacar, doze mil selados;'),
('acf','ap',7,8,'Da tribo de Zebulom, doze mil selados; da tribo de José, doze mil selados; da tribo de Benjamim, doze mil selados.'),
('acf','ap',7,9,'Depois destas coisas olhei, e eis aqui uma multidão, a qual ninguém podia contar, de todas as nações, e tribos, e povos, e línguas, que estavam diante do trono, e perante o Cordeiro, trajando vestes brancas e com palmas nas suas mãos;'),
('acf','ap',7,10,'E clamavam com grande voz, dizendo: Salvação ao nosso Deus, que está assentado no trono, e ao Cordeiro.'),
('acf','ap',7,11,'E todos os anjos estavam ao redor do trono, e dos anciãos, e dos quatro animais; e prostraram-se diante do trono sobre seus rostos, e adoraram a Deus,'),
('acf','ap',7,12,'Dizendo: Amém. Louvor, e glória, e sabedoria, e ação de graças, e honra, e poder, e força ao nosso Deus, para todo o sempre. Amém.'),
('acf','ap',7,13,'E um dos anciãos me falou, dizendo: Estes que estão vestidos de vestes brancas, quem são, e de onde vieram?'),
('acf','ap',7,14,'E eu disse-lhe: Senhor, tu sabes. E ele disse-me: Estes são os que vieram da grande tribulação, e lavaram as suas vestes e as branquearam no sangue do Cordeiro.'),
('acf','ap',7,15,'Por isso estão diante do trono de Deus, e o servem de dia e de noite no seu templo; e aquele que está assentado sobre o trono os cobrirá com a sua sombra.'),
('acf','ap',7,16,'Nunca mais terão fome, nunca mais terão sede; nem sol nem calma alguma cairá sobre eles.'),
('acf','ap',7,17,'Porque o Cordeiro que está no meio do trono os apascentará, e lhes servirá de guia para as fontes vivas das águas; e Deus limpará de seus olhos toda a lágrima.'),
('acf','ap',8,1,'E, havendo aberto o sétimo selo, fez-se silêncio no céu quase por meia hora.'),
('acf','ap',8,2,'E vi os sete anjos, que estavam diante de Deus, e foram-lhes dadas sete trombetas.'),
('acf','ap',8,3,'E veio outro anjo, e pôs-se junto ao altar, tendo um incensário de ouro; e foi-lhe dado muito incenso, para o pôr com as orações de todos os santos sobre o altar de ouro, que está diante do trono.'),
('acf','ap',8,4,'E a fumaça do incenso subiu com as orações dos santos desde a mão do anjo até diante de Deus.'),
('acf','ap',8,5,'E o anjo tomou o incensário, e o encheu do fogo do altar, e o lançou sobre a terra; e houve depois vozes, e trovões, e relâmpagos e terremotos.'),
('acf','ap',8,6,'E os sete anjos, que tinham as sete trombetas, prepararam-se para tocá-las.'),
('acf','ap',8,7,'E o primeiro anjo tocou a sua trombeta, e houve saraiva e fogo misturado com sangue, e foram lançados na terra, que foi queimada na sua terça parte; queimou-se a terça parte das árvores, e toda a erva verde foi queimada.'),
('acf','ap',8,8,'E o segundo anjo tocou a trombeta; e foi lançada no mar uma coisa como um grande monte ardendo em fogo, e tornou-se em sangue a terça parte do mar.'),
('acf','ap',8,9,'E morreu a terça parte das criaturas que tinham vida no mar; e perdeu-se a terça parte das naus.'),
('acf','ap',8,10,'E o terceiro anjo tocou a sua trombeta, e caiu do céu uma grande estrela ardendo como uma tocha, e caiu sobre a terça parte dos rios, e sobre as fontes das águas.'),
('acf','ap',8,11,'E o nome da estrela era Absinto, e a terça parte das águas tornou-se em absinto, e muitos homens morreram das águas, porque se tornaram amargas.'),
('acf','ap',8,12,'E o quarto anjo tocou a sua trombeta, e foi ferida a terça parte do sol, e a terça parte da lua, e a terça parte das estrelas; para que a terça parte deles se escurecesse, e a terça parte do dia não brilhasse, e semelhantemente a noite.'),
('acf','ap',8,13,'E olhei, e ouvi um anjo voar pelo meio do céu, dizendo com grande voz: Ai! ai! ai! dos que habitam sobre a terra! por causa das outras vozes das trombetas dos três anjos que hão de ainda tocar.'),
('acf','ap',9,1,'E o quinto anjo tocou a sua trombeta, e vi uma estrela que do céu caiu na terra; e foi-lhe dada a chave do poço do abismo.'),
('acf','ap',9,2,'E abriu o poço do abismo, e subiu fumaça do poço, como a fumaça de uma grande fornalha, e com a fumaça do poço escureceu-se o sol e o ar.'),
('acf','ap',9,3,'E da fumaça vieram gafanhotos sobre a terra; e foi-lhes dado poder, como o poder que têm os escorpiões da terra.'),
('acf','ap',9,4,'E foi-lhes dito que não fizessem dano à erva da terra, nem a verdura alguma, nem a árvore alguma, mas somente aos homens que não têm nas suas testas o selo de Deus.'),
('acf','ap',9,5,'E foi-lhes permitido, não que os matassem, mas que por cinco meses os atormentassem; e o seu tormento era semelhante ao tormento do escorpião, quando fere o homem.'),
('acf','ap',9,6,'E naqueles dias os homens buscarão a morte, e não a acharão; e desejarão morrer, e a morte fugirá deles.'),
('acf','ap',9,7,'E o parecer dos gafanhotos era semelhante ao de cavalos aparelhados para a guerra; e sobre as suas cabeças havia umas como coroas semelhantes ao ouro; e os seus rostos eram como rostos de homens.'),
('acf','ap',9,8,'E tinham cabelos como cabelos de mulheres, e os seus dentes eram como de leões.'),
('acf','ap',9,9,'E tinham couraças como couraças de ferro; e o ruído das suas asas era como o ruído de carros, quando muitos cavalos correm ao combate.'),
('acf','ap',9,10,'E tinham caudas semelhantes às dos escorpiões, e aguilhões nas suas caudas; e o seu poder era para danificar os homens por cinco meses.'),
('acf','ap',9,11,'E tinham sobre si rei, o anjo do abismo; em hebreu era o seu nome Abadom, e em grego Apoliom.'),
('acf','ap',9,12,'Passado é já um ai; eis que depois disso vêm ainda dois ais.'),
('acf','ap',9,13,'E tocou o sexto anjo a sua trombeta, e ouvi uma voz que vinha das quatro pontas do altar de ouro, que estava diante de Deus,'),
('acf','ap',9,14,'A qual dizia ao sexto anjo, que tinha a trombeta: Solta os quatro anjos, que estão presos junto ao grande rio Eufrates.'),
('acf','ap',9,15,'E foram soltos os quatro anjos, que estavam preparados para a hora, e dia, e mês, e ano, a fim de matarem a terça parte dos homens.'),
('acf','ap',9,16,'E o número dos exércitos dos cavaleiros era de duzentos milhões; e ouvi o número deles.'),
('acf','ap',9,17,'E assim vi os cavalos nesta visão; e os que sobre eles cavalgavam tinham couraças de fogo, e de jacinto, e de enxofre; e as cabeças dos cavalos eram como cabeças de leões; e de suas bocas saía fogo e fumaça e enxofre.'),
('acf','ap',9,18,'Por estes três foi morta a terça parte dos homens, isto é pelo fogo, pela fumaça, e pelo enxofre, que saíam das suas bocas.'),
('acf','ap',9,19,'Porque o poder dos cavalos está na sua boca e nas suas caudas. Porquanto as suas caudas são semelhantes a serpentes, e têm cabeças, e com elas danificam.'),
('acf','ap',9,20,'E os outros homens, que não foram mortos por estas pragas, não se arrependeram das obras de suas mãos, para não adorarem os demônios, e os ídolos de ouro, e de prata, e de bronze, e de pedra, e de madeira, que nem podem ver, nem ouvir, nem andar.'),
('acf','ap',9,21,'E não se arrependeram dos seus homicídios, nem das suas feitiçarias, nem da sua fornicação, nem dos seus furtos.'),
('acf','ap',10,1,'E vi outro anjo forte, que descia do céu, vestido de uma nuvem; e por cima da sua cabeça estava o arco celeste, e o seu rosto era como o sol, e os seus pés como colunas de fogo;'),
('acf','ap',10,2,'E tinha na sua mão um livrinho aberto. E pôs o seu pé direito sobre o mar, e o esquerdo sobre a terra;'),
('acf','ap',10,3,'E clamou com grande voz, como quando ruge um leão; e, havendo clamado, os sete trovões emitiram as suas vozes.'),
('acf','ap',10,4,'E, quando os sete trovões acabaram de emitir as suas vozes, eu ia escrever; mas ouvi uma voz do céu, que me dizia: Sela o que os sete trovões emitiram, e nào o escrevas.'),
('acf','ap',10,5,'E o anjo que vi estar sobre o mar e sobre a terra levantou a sua mão ao céu,'),
('acf','ap',10,6,'E jurou por aquele que vive para todo o sempre, o qual criou o céu e o que nele há, e a terra e o que nela há, e o mar e o que nele há, que não haveria mais demora;'),
('acf','ap',10,7,'Mas nos dias da voz do sétimo anjo, quando tocar a sua trombeta, se cumprirá o segredo de Deus, como anunciou aos profetas, seus servos.'),
('acf','ap',10,8,'E a voz que eu do céu tinha ouvido tornou a falar comigo, e disse: Vai, e toma o livrinho aberto da mão do anjo que está em pé sobre o mar e sobre a terra.'),
('acf','ap',10,9,'E fui ao anjo, dizendo-lhe: Dá-me o livrinho. E ele disse-me: Toma-o, e come-o, e ele fará amargo o teu ventre, mas na tua boca será doce como mel.'),
('acf','ap',10,10,'E tomei o livrinho da mão do anjo, e comi-o; e na minha boca era doce como mel; e, havendo-o comido, o meu ventre ficou amargo.'),
('acf','ap',10,11,'E ele disse-me: Importa que profetizes outra vez a muitos povos, e nações, e línguas e reis.'),
('acf','ap',11,1,'E foi-me dada uma cana semelhante a uma vara; e chegou o anjo, e disse: Levanta-te, e mede o templo de Deus, e o altar, e os que nele adoram.'),
('acf','ap',11,2,'E deixa o átrio que está fora do templo, e não o meças; porque foi dado às nações, e pisarão a cidade santa por quarenta e dois meses.'),
('acf','ap',11,3,'E darei poder às minhas duas testemunhas, e profetizarão por mil duzentos e sessenta dias, vestidas de saco.'),
('acf','ap',11,4,'Estas são as duas oliveiras e os dois castiçais que estão diante do Deus da terra.'),
('acf','ap',11,5,'E, se alguém lhes quiser fazer mal, fogo sairá da sua boca, e devorará os seus inimigos; e, se alguém lhes quiser fazer mal, importa que assim seja morto.'),
('acf','ap',11,6,'Estes têm poder para fechar o céu, para que não chova, nos dias da sua profecia; e têm poder sobre as águas para convertê-las em sangue, e para ferir a terra com toda a sorte de pragas, todas quantas vezes quiserem.'),
('acf','ap',11,7,'E, quando acabarem o seu testemunho, a besta que sobe do abismo lhes fará guerra, e os vencerá, e os matará.'),
('acf','ap',11,8,'E jazerão os seus corpos mortos na praça da grande cidade que espiritualmente se chama Sodoma e Egito, onde o nosso Senhor também foi crucificado.'),
('acf','ap',11,9,'E homens de vários povos, e tribos, e línguas, e nações verão seus corpos mortos por três dias e meio, e não permitirão que os seus corpos mortos sejam postos em sepulcros.'),
('acf','ap',11,10,'E os que habitam na terra se regozijarão sobre eles, e se alegrarão, e mandarão presentes uns aos outros; porquanto estes dois profetas tinham atormentado os que habitam sobre a terra.'),
('acf','ap',11,11,'E depois daqueles três dias e meio o espírito de vida, vindo de Deus, entrou neles; e puseram-se sobre seus pés, e caiu grande temor sobre os que os viram.'),
('acf','ap',11,12,'E ouviram uma grande voz do céu, que lhes dizia: Subi para aqui. E subiram ao céu em uma nuvem; e os seus inimigos os viram.'),
('acf','ap',11,13,'E naquela mesma hora houve um grande terremoto, e caiu a décima parte da cidade, e no terremoto foram mortos sete mil homens; e os demais ficaram muito atemorizados, e deram glória ao Deus do céu.'),
('acf','ap',11,14,'É passado o segundo ai; eis que o terceiro ai cedo virá.'),
('acf','ap',11,15,'E o sétimo anjo tocou a sua trombeta, e houve no céu grandes vozes, que diziam: Os reinos do mundo vieram a ser de nosso Senhor e do seu Cristo, e ele reinará para todo o sempre.'),
('acf','ap',11,16,'E os vinte e quatro anciãos, que estão assentados em seus tronos diante de Deus, prostraram-se sobre seus rostos e adoraram a Deus,'),
('acf','ap',11,17,'Dizendo: Graças te damos, Senhor Deus Todo-Poderoso, que és, e que eras, e que hás de vir, que tomaste o teu grande poder, e reinaste.'),
('acf','ap',11,18,'E iraram-se as nações, e veio a tua ira, e o tempo dos mortos, para que sejam julgados, e o tempo de dares o galardão aos profetas, teus servos, e aos santos, e aos que temem o teu nome, a pequenos e a grandes, e o tempo de destruíres os que destroem a terra.'),
('acf','ap',11,19,'E abriu-se no céu o templo de Deus, e a arca da sua aliança foi vista no seu templo; e houve relâmpagos, e vozes, e trovões, e terremotos e grande saraiva.'),
('acf','ap',12,1,'E viu-se um grande sinal no céu: uma mulher vestida do sol, tendo a lua debaixo dos seus pés, e uma coroa de doze estrelas sobre a sua cabeça.'),
('acf','ap',12,2,'E estava grávida, e com dores de parto, e gritava com ânsias de dar à luz.'),
('acf','ap',12,3,'E viu-se outro sinal no céu; e eis que era um grande dragão vermelho, que tinha sete cabeças e dez chifres, e sobre as suas cabeças sete diademas.'),
('acf','ap',12,4,'E a sua cauda levou após si a terça parte das estrelas do céu, e lançou-as sobre a terra; e o dragão parou diante da mulher que havia de dar à luz, para que, dando ela à luz, lhe tragasse o filho.'),
('acf','ap',12,5,'E deu à luz um filho homem que há de reger todas as nações com vara de ferro; e o seu filho foi arrebatado para Deus e para o seu trono.'),
('acf','ap',12,6,'E a mulher fugiu para o deserto, onde já tinha lugar preparado por Deus, para que ali fosse alimentada durante mil duzentos e sessenta dias.'),
('acf','ap',12,7,'E houve batalha no céu; Miguel e os seus anjos batalhavam contra o dragão, e batalhavam o dragão e os seus anjos;'),
('acf','ap',12,8,'Mas não prevaleceram, nem mais o seu lugar se achou nos céus.'),
('acf','ap',12,9,'E foi precipitado o grande dragão, a antiga serpente, chamada o Diabo, e Satanás, que engana todo o mundo; ele foi precipitado na terra, e os seus anjos foram lançados com ele.'),
('acf','ap',12,10,'E ouvi uma grande voz no céu, que dizia: Agora é chegada a salvação, e a força, e o reino do nosso Deus, e o poder do seu Cristo; porque já o acusador de nossos irmãos é derrubado, o qual diante do nosso Deus os acusava de dia e de noite.'),
('acf','ap',12,11,'E eles o venceram pelo sangue do Cordeiro e pela palavra do seu testemunho; e não amaram as suas vidas até à morte.'),
('acf','ap',12,12,'Por isso alegrai-vos, ó céus, e vós que neles habitais. Ai dos que habitam na terra e no mar; porque o diabo desceu a vós, e tem grande ira, sabendo que já tem pouco tempo.'),
('acf','ap',12,13,'E, quando o dragão viu que fora lançado na terra, perseguiu a mulher que dera à luz o filho homem.'),
('acf','ap',12,14,'E foram dadas à mulher duas asas de grande águia, para que voasse para o deserto, ao seu lugar, onde é sustentada por um tempo, e tempos, e metade de um tempo, fora da vista da serpente.'),
('acf','ap',12,15,'E a serpente lançou da sua boca, atrás da mulher, água como um rio, para que pela corrente a fizesse arrebatar.'),
('acf','ap',12,16,'E a terra ajudou a mulher; e a terra abriu a sua boca, e tragou o rio que o dragão lançara da sua boca.'),
('acf','ap',12,17,'E o dragão irou-se contra a mulher, e foi fazer guerra ao remanescente da sua semente, os que guardam os mandamentos de Deus, e têm o testemunho de Jesus Cristo.'),
('acf','ap',13,1,'E eu pus-me sobre a areia do mar, e vi subir do mar uma besta que tinha sete cabeças e dez chifres, e sobre os seus chifres dez diademas, e sobre as suas cabeças um nome de blasfêmia.'),
('acf','ap',13,2,'E a besta que vi era semelhante ao leopardo, e os seus pés como os de urso, e a sua boca como a de leão; e o dragão deu-lhe o seu poder, e o seu trono, e grande poderio.'),
('acf','ap',13,3,'E vi uma das suas cabeças como ferida de morte, e a sua chaga mortal foi curada; e toda a terra se maravilhou após a besta.'),
('acf','ap',13,4,'E adoraram o dragão que deu à besta o seu poder; e adoraram a besta, dizendo: Quem é semelhante à besta? Quem poderá batalhar contra ela?'),
('acf','ap',13,5,'E foi-lhe dada uma boca, para proferir grandes coisas e blasfêmias; e deu-se-lhe poder para agir por quarenta e dois meses.'),
('acf','ap',13,6,'E abriu a sua boca em blasfêmias contra Deus, para blasfemar do seu nome, e do seu tabernáculo, e dos que habitam no céu.'),
('acf','ap',13,7,'E foi-lhe permitido fazer guerra aos santos, e vencê-los; e deu-se-lhe poder sobre toda a tribo, e língua, e nação.'),
('acf','ap',13,8,'E adoraram-na todos os que habitam sobre a terra, esses cujos nomes não estão escritos no livro da vida do Cordeiro que foi morto desde a fundação do mundo.'),
('acf','ap',13,9,'Se alguém tem ouvidos, ouça.'),
('acf','ap',13,10,'Se alguém leva em cativeiro, em cativeiro irá; se alguém matar à espada, necessário é que à espada seja morto. Aqui está a paciência e a fé dos santos.'),
('acf','ap',13,11,'E vi subir da terra outra besta, e tinha dois chifres semelhantes aos de um cordeiro; e falava como o dragão.'),
('acf','ap',13,12,'E exerce todo o poder da primeira besta na sua presença, e faz que a terra e os que nela habitam adorem a primeira besta, cuja chaga mortal fora curada.'),
('acf','ap',13,13,'E faz grandes sinais, de maneira que até fogo faz descer do céu à terra, à vista dos homens.'),
('acf','ap',13,14,'E engana os que habitam na terra com sinais que lhe foi permitido que fizesse em presença da besta, dizendo aos que habitam na terra que fizessem uma imagem à besta que recebera a ferida da espada e vivia.'),
('acf','ap',13,15,'E foi-lhe concedido que desse espírito à imagem da besta, para que também a imagem da besta falasse, e fizesse que fossem mortos todos os que não adorassem a imagem da besta.'),
('acf','ap',13,16,'E faz que a todos, pequenos e grandes, ricos e pobres, livres e servos, lhes seja posto um sinal na sua mão direita, ou nas suas testas,'),
('acf','ap',13,17,'Para que ninguém possa comprar ou vender, senão aquele que tiver o sinal, ou o nome da besta, ou o número do seu nome.'),
('acf','ap',13,18,'Aqui há sabedoria. Aquele que tem entendimento, calcule o número da besta; porque é o número de um homem, e o seu número é seiscentos e sessenta e seis.'),
('acf','ap',14,1,'E olhei, e eis que estava o Cordeiro sobre o monte Sião, e com ele cento e quarenta e quatro mil, que em suas testas tinham escrito o nome de seu Pai.'),
('acf','ap',14,2,'E ouvi uma voz do céu, como a voz de muitas águas, e como a voz de um grande trovão; e ouvi uma voz de harpistas, que tocavam com as suas harpas.'),
('acf','ap',14,3,'E cantavam um como cântico novo diante do trono, e diante dos quatro animais e dos anciãos; e ninguém podia aprender aquele cântico, senão os cento e quarenta e quatro mil que foram comprados da terra.'),
('acf','ap',14,4,'Estes são os que não estão contaminados com mulheres; porque são virgens. Estes são os que seguem o Cordeiro para onde quer que vá. Estes são os que dentre os homens foram comprados como primícias para Deus e para o Cordeiro.'),
('acf','ap',14,5,'E na sua boca não se achou engano; porque são irrepreensíveis diante do trono de Deus.'),
('acf','ap',14,6,'E vi outro anjo voar pelo meio do céu, e tinha o evangelho eterno, para o proclamar aos que habitam sobre a terra, e a toda a nação, e tribo, e língua, e povo,'),
('acf','ap',14,7,'Dizendo com grande voz: Temei a Deus, e dai-lhe glória; porque é vinda a hora do seu juízo. E adorai aquele que fez o céu, e a terra, e o mar, e as fontes das águas.'),
('acf','ap',14,8,'E outro anjo seguiu, dizendo: Caiu, caiu Babilônia, aquela grande cidade, que a todas as nações deu a beber do vinho da ira da sua fornicação.'),
('acf','ap',14,9,'E seguiu-os o terceiro anjo, dizendo com grande voz: Se alguém adorar a besta, e a sua imagem, e receber o sinal na sua testa, ou na sua mão,'),
('acf','ap',14,10,'Também este beberá do vinho da ira de Deus, que se deitou, não misturado, no cálice da sua ira; e será atormentado com fogo e enxofre diante dos santos anjos e diante do Cordeiro.'),
('acf','ap',14,11,'E a fumaça do seu tormento sobe para todo o sempre; e não têm repouso nem de dia nem de noite os que adoram a besta e a sua imagem, e aquele que receber o sinal do seu nome.'),
('acf','ap',14,12,'Aqui está a paciência dos santos; aqui estão os que guardam os mandamentos de Deus e a fé em Jesus.'),
('acf','ap',14,13,'E ouvi uma voz do céu, que me dizia: Escreve: Bem-aventurados os mortos que desde agora morrem no Senhor. Sim, diz o Espírito, para que descansem dos seus trabalhos, e as suas obras os seguem.'),
('acf','ap',14,14,'E olhei, e eis uma nuvem branca, e assentado sobre a nuvem um semelhante ao Filho do homem, que tinha sobre a sua cabeça uma coroa de ouro, e na sua mão uma foice aguda.'),
('acf','ap',14,15,'E outro anjo saiu do templo, clamando com grande voz ao que estava assentado sobre a nuvem: Lança a tua foice, e sega; a hora de segar te é vinda, porque já a seara da terra está madura.'),
('acf','ap',14,16,'E aquele que estava assentado sobre a nuvem meteu a sua foice à terra, e a terra foi segada.'),
('acf','ap',14,17,'E saiu do templo, que está no céu, outro anjo, o qual também tinha uma foice aguda.'),
('acf','ap',14,18,'E saiu do altar outro anjo, que tinha poder sobre o fogo, e clamou com grande voz ao que tinha a foice aguda, dizendo: Lança a tua foice aguda, e vindima os cachos da vinha da terra, porque já as suas uvas estão maduras.'),
('acf','ap',14,19,'E o anjo lançou a sua foice à terra e vindimou as uvas da vinha da terra, e atirou-as no grande lagar da ira de Deus.'),
('acf','ap',14,20,'E o lagar foi pisado fora da cidade, e saiu sangue do lagar até aos freios dos cavalos, pelo espaço de mil e seiscentos estádios.'),
('acf','ap',15,1,'E vi outro grande e admirável sinal no céu: sete anjos, que tinham as sete últimas pragas; porque nelas é consumada a ira de Deus.'),
('acf','ap',15,2,'E vi um como mar de vidro misturado com fogo; e também os que saíram vitoriosos da besta, e da sua imagem, e do seu sinal, e do número do seu nome, que estavam junto ao mar de vidro, e tinham as harpas de Deus.'),
('acf','ap',15,3,'E cantavam o cântico de Moisés, servo de Deus, e o cântico do Cordeiro, dizendo: Grandes e maravilhosas são as tuas obras, Senhor Deus Todo-Poderoso! Justos e verdadeiros são os teus caminhos, ó Rei dos santos.'),
('acf','ap',15,4,'Quem te não temerá, ó Senhor, e não magnificará o teu nome? Porque só tu és santo; por isso todas as nações virão, e se prostrarão diante de ti, porque os teus juízos são manifestos.'),
('acf','ap',15,5,'E depois disto olhei, e eis que o templo do tabernáculo do testemunho se abriu no céu.'),
('acf','ap',15,6,'E os sete anjos que tinham as sete pragas saíram do templo, vestidos de linho puro e resplandecente, e cingidos com cintos de ouro pelos peitos.'),
('acf','ap',15,7,'E um dos quatro animais deu aos sete anjos sete taças de ouro, cheias da ira de Deus, que vive para todo o sempre.'),
('acf','ap',15,8,'E o templo encheu-se com a fumaça da glória de Deus e do seu poder; e ninguém podia entrar no templo, até que se consumassem as sete pragas dos sete anjos.'),
('acf','ap',16,1,'E ouvi, vinda do templo, uma grande voz, que dizia aos sete anjos: Ide, e derramaisobre a terra as sete taças da ira de Deus.'),
('acf','ap',16,2,'E foi o primeiro, e derramou a sua taça sobre a terra, e fez-se uma chaga má e maligna nos homens que tinham o sinal da besta e que adoravam a sua imagem.'),
('acf','ap',16,3,'E o segundo anjo derramou a sua taça no mar, que se tornou em sangue como de um morto, e morreu no mar toda a alma vivente.'),
('acf','ap',16,4,'E o terceiro anjo derramou a sua taça nos rios e nas fontes das águas, e se tornaram em sangue.'),
('acf','ap',16,5,'E ouvi o anjo das águas, que dizia: Justo és tu, ó Senhor, que és, e que eras, e hás de ser, porque julgaste estas coisas.'),
('acf','ap',16,6,'Visto como derramaram o sangue dos santos e dos profetas, também tu lhes deste o sangue a beber; porque disto são merecedores.'),
('acf','ap',16,7,'E ouvi outro do altar, que dizia: Na verdade, ó Senhor Deus Todo-Poderoso, verdadeiros e justos são os teus juízos.'),
('acf','ap',16,8,'E o quarto anjo derramou a sua taça sobre o sol, e foi-lhe permitido que abrasasse os homens com fogo.'),
('acf','ap',16,9,'E os homens foram abrasados com grandes calores, e blasfemaram o nome de Deus, que tem poder sobre estas pragas; e não se arrependeram para lhe darem glória.'),
('acf','ap',16,10,'E o quinto anjo derramou a sua taça sobre o trono da besta, e o seu reino se fez tenebroso; e eles mordiam as suas línguas de dor.'),
('acf','ap',16,11,'E por causa das suas dores, e por causa das suas chagas, blasfemaram do Deus do céu; e não se arrependeram das suas obras.'),
('acf','ap',16,12,'E o sexto anjo derramou a sua taça sobre o grande rio Eufrates; e a sua água secou-se, para que se preparasse o caminho dos reis do oriente.'),
('acf','ap',16,13,'E da boca do dragão, e da boca da besta, e da boca do falso profeta vi sair três espíritos imundos, semelhantes a rãs.'),
('acf','ap',16,14,'Porque são espíritos de demônios, que fazem prodígios; os quais vão ao encontro dos reis da terra e de todo o mundo, para os congregar para a batalha, naquele grande dia do Deus Todo-Poderoso.'),
('acf','ap',16,15,'Eis que venho como ladrão. Bem-aventurado aquele que vigia, e guarda as suas roupas, para que não ande nu, e não se vejam as suas vergonhas.'),
('acf','ap',16,16,'E os congregaram no lugar que em hebreu se chama Armagedom.'),
('acf','ap',16,17,'E o sétimo anjo derramou a sua taça no ar, e saiu grande voz do templo do céu, do trono, dizendo: Está feito.'),
('acf','ap',16,18,'E houve vozes, e trovões, e relâmpagos, e houve um grande terremoto, como nunca houve desde que há homens sobre a terra; tal foi este tão grande terremoto.'),
('acf','ap',16,19,'E a grande cidade fendeu-se em três partes, e as cidades das nações caíram; e da grande babilônia se lembrou Deus, para lhe dar o cálice do vinho da indignação da sua ira.'),
('acf','ap',16,20,'E toda a ilha fugiu; e os montes não se acharam.'),
('acf','ap',16,21,'E sobre os homens caiu do céu uma grande saraiva, pedras do peso de um talento; e os homens blasfemaram de Deus por causa da praga da saraiva; porque a sua praga era mui grande.'),
('acf','ap',17,1,'E veio um dos sete anjos que tinham as sete taças, e falou comigo, dizendo-me: Vem, mostrar-te-ei a condenação da grande prostituta que está assentada sobre muitas águas;'),
('acf','ap',17,2,'Com a qual fornicaram os reis da terra; e os que habitam na terra se embebedaram com o vinho da sua fornicação.'),
('acf','ap',17,3,'E levou-me em espírito a um deserto, e vi uma mulher assentada sobre uma besta de cor de escarlata, que estava cheia de nomes de blasfêmia, e tinha sete cabeças e dez chifres.'),
('acf','ap',17,4,'E a mulher estava vestida de púrpura e de escarlata, e adornada com ouro, e pedras preciosas e pérolas; e tinha na sua mão um cálice de ouro cheio das abominações e da imundícia da sua fornicação;'),
('acf','ap',17,5,'E na sua testa estava escrito o nome: Mistério, a grande babilônia, a mãe das prostituições e abominações da terra.'),
('acf','ap',17,6,'E vi que a mulher estava embriagada do sangue dos santos, e do sangue das testemunhas de Jesus. E, vendo-a eu, maravilhei-me com grande admiração.'),
('acf','ap',17,7,'E o anjo me disse: Por que te admiras? Eu te direi o mistério da mulher, e da besta que a traz, a qual tem sete cabeças e dez chifres.'),
('acf','ap',17,8,'A besta que viste foi e já não é, e há de subir do abismo, e irá à perdição; e os que habitam na terra (cujos nomes não estão escritos no livro da vida, desde a fundação do mundo) se admirarão, vendo a besta que era e já não é, ainda que é.'),
('acf','ap',17,9,'Aqui o sentido, que tem sabedoria. As sete cabeças são sete montes, sobre os quais a mulher está assentada.'),
('acf','ap',17,10,'E são também sete reis; cinco já caíram, e um existe; outro ainda não é vindo; e, quando vier, convém que dure um pouco de tempo.'),
('acf','ap',17,11,'E a besta que era e já não é, é ela também o oitavo, e é dos sete, e vai à perdição.'),
('acf','ap',17,12,'E os dez chifres que viste são dez reis, que ainda não receberam o reino, mas receberão poder como reis por uma hora, juntamente com a besta.'),
('acf','ap',17,13,'Estes têm um mesmo intento, e entregarão o seu poder e autoridade à besta.'),
('acf','ap',17,14,'Estes combaterão contra o Cordeiro, e o Cordeiro os vencerá, porque é o Senhor dos senhores e o Rei dos reis; vencerão os que estão com ele, chamados, e eleitos, e fiéis.'),
('acf','ap',17,15,'E disse-me: As águas que viste, onde se assenta a prostituta, são povos, e multidões, e nações, e línguas.'),
('acf','ap',17,16,'E os dez chifres que viste na besta são os que odiarào a prostituta, e a colocarão desolada e nua, e comerão a sua carne, e a queimarão no fogo.'),
('acf','ap',17,17,'Porque Deus tem posto em seus corações, que cumpram o seu intento, e tenham uma mesma idéia, e que dêem à besta o seu reino, até que se cumpram as palavras de Deus.'),
('acf','ap',17,18,'E a mulher que viste é a grande cidade que reina sobre os reis da terra.'),
('acf','ap',18,1,'E depois destas coisas vi descer do céu outro anjo, que tinha grande poder, e a terra foi iluminada com a sua glória.'),
('acf','ap',18,2,'E clamou fortemente com grande voz, dizendo: Caiu, caiu a grande Babilônia, e se tornou morada de demônios, e coito de todo espírito imundo, e coito de toda ave imunda e odiável.'),
('acf','ap',18,3,'Porque todas as nações beberam do vinho da ira da sua fornicação, e os reis da terra fornicaram com ela; e os mercadores da terra se enriqueceram com a abundância de suas delícias.'),
('acf','ap',18,4,'E ouvi outra voz do céu, que dizia: Sai dela, povo meu, para que não sejas participante dos seus pecados, e para que não incorras nas suas pragas.'),
('acf','ap',18,5,'Porque já os seus pecados se acumularam até ao céu, e Deus se lembrou das iniqüidades dela.'),
('acf','ap',18,6,'Tornai-lhe a dar como ela vos tem dado, e retribuí-lhe em dobro conforme as suas obras; no cálice em que vos deu de beber, dai-lhe a ela em dobro.'),
('acf','ap',18,7,'Quanto ela se glorificou, e em delícias esteve, foi-lhe outro tanto de tormento e pranto; porque diz em seu coração: Estou assentada como rainha, e não sou viúva, e não verei o pranto.'),
('acf','ap',18,8,'Portanto, num dia virão as suas pragas, a morte, e o pranto, e a fome; e será queimada no fogo; porque é forte o Senhor Deus que a julga.'),
('acf','ap',18,9,'E os reis da terra, que fornicaram com ela, e viveram em delícias, a chorarão, e sobre ela prantearão, quando virem a fumaça do seu incêndio;'),
('acf','ap',18,10,'Estando de longe pelo temor do seu tormento, dizendo: Ai! ai daquela grande cidade de Babilônia, aquela forte cidade! pois em uma hora veio o seu juízo.'),
('acf','ap',18,11,'E sobre ela choram e lamentam os mercadores da terra; porque ninguém mais compra as suas mercadorias:'),
('acf','ap',18,12,'Mercadorias de ouro, e de prata, e de pedras preciosas, e de pérolas, e de linho fino, e de púrpura, e de seda, e de escarlata; e toda a madeira odorífera, e todo o vaso de marfim, e todo o vaso de madeira preciosíssima, de bronze e de ferro, e de mármore;'),
('acf','ap',18,13,'E canela, e perfume, e mirra, e incenso, e vinho, e azeite, e flor de farinha, e trigo, e gado, e ovelhas; e cavalos, e carros, e corpos e almas de homens.'),
('acf','ap',18,14,'E o fruto do desejo da tua alma foi-se de ti; e todas as coisas gostosas e excelentes se foram de ti, e não mais as acharás.'),
('acf','ap',18,15,'Os mercadores destas coisas, que dela se enriqueceram, estarão de longe, pelo temor do seu tormento, chorando e lamentando,'),
('acf','ap',18,16,'E dizendo: Ai, ai daquela grande cidade! que estava vestida de linho fino, de púrpura, de escarlata; e adornada com ouro e pedras preciosas e pérolas! porque numa hora foram assoladas tantas riquezas.'),
('acf','ap',18,17,'E todo piloto, e todo o que navega em naus, e todo marinheiro, e todos os que negociam no mar se puseram de longe;'),
('acf','ap',18,18,'E, vendo a fumaça do seu incêndio, clamaram, dizendo: Que cidade é semelhante a esta grande cidade?'),
('acf','ap',18,19,'E lançaram pó sobre as suas cabeças, e clamaram, chorando, e lamentando, e dizendo: Ai, ai daquela grande cidade! na qual todos os que tinham naus no mar se enriqueceram em razão da sua opulência; porque numa hora foi assolada.'),
('acf','ap',18,20,'Alegra-te sobre ela, ó céu, e vós, santos apóstolos e profetas; porque já Deus julgou a vossa causa quanto a ela.'),
('acf','ap',18,21,'E um forte anjo levantou uma pedra como uma grande mó, e lançou-a no mar, dizendo: Com igual ímpeto será lançada babilônia, aquela grande cidade, e não será jamais achada.'),
('acf','ap',18,22,'E em ti não se ouvirá mais a voz de harpistas, e de músicos, e de flautistas, e de trombeteiros, e nenhum artífice de arte alguma se achará mais em ti; e ruído de mó em ti não se ouvirá mais;'),
('acf','ap',18,23,'E luz de candeia não mais luzirá em ti, e voz de esposo e de esposa não mais em ti se ouvirá; porque os teus mercadores eram os grandes da terra; porque todas as nações foram enganadas pelas tuas feitiçarias.'),
('acf','ap',18,24,'E nela se achou o sangue dos profetas, e dos santos, e de todos os que foram mortos na terra.'),
('acf','ap',19,1,'E, depois destas coisas ouvi no céu uma grande voz de uma grande multidão, que dizia: Aleluia! A salvação, e a glória, e a honra, e o poder pertencem ao Senhor nosso Deus;'),
('acf','ap',19,2,'Porque verdadeiros e justos são os seus juízos, pois julgou a grande prostituta, que havia corrompido a terra com a sua fornicação, e das mãos dela vingou o sangue dos seus servos.'),
('acf','ap',19,3,'E outra vez disseram: Aleluia! E a fumaça dela sobe para todo o sempre.'),
('acf','ap',19,4,'E os vinte e quatro anciãos, e os quatro animais, prostraram-se e adoraram a Deus, que estava assentado no trono, dizendo: Amém. Aleluia!'),
('acf','ap',19,5,'E saiu uma voz do trono, que dizia: Louvai o nosso Deus, vós, todos os seus servos, e vós que o temeis, assim pequenos como grandes.'),
('acf','ap',19,6,'E ouvi como que a voz de uma grande multidão, e como que a voz de muitas águas, e como que a voz de grandes trovões, que dizia: Aleluia! pois já o Senhor Deus Todo-Poderoso reina.'),
('acf','ap',19,7,'Regozijemo-nos, e alegremo-nos, e demos-lhe glória; porque vindas são as bodas do Cordeiro, e já a sua esposa se aprontou.'),
('acf','ap',19,8,'E foi-lhe dado que se vestisse de linho fino, puro e resplandecente; porque o linho fino são as justiças dos santos.'),
('acf','ap',19,9,'E disse-me: Escreve: Bemaventurados aqueles que são chamados à ceia das bodas do Cordeiro. E disse-me: Estas são as verdadeiras palavras de Deus.'),
('acf','ap',19,10,'E eu lancei-me a seus pés para o adorar; mas ele disse-me: Olha não faças tal; sou teu conservo, e de teus irmãos, que têm o testemunho de Jesus. Adora a Deus; porque o testemunho de Jesus é o espírito de profecia.'),
('acf','ap',19,11,'E vi o céu aberto, e eis um cavalo branco; e o que estava assentado sobre ele chama-se Fiel e Verdadeiro; e julga e peleja com justiça.'),
('acf','ap',19,12,'E os seus olhos eram como chama de fogo; e sobre a sua cabeça havia muitos diademas; e tinha um nome escrito, que ninguém sabia senão ele mesmo.'),
('acf','ap',19,13,'E estava vestido de veste tingida em sangue; e o nome pelo qual se chama é A Palavra de Deus.'),
('acf','ap',19,14,'E seguiam-no os exércitos no céu em cavalos brancos, e vestidos de linho fino, branco e puro.'),
('acf','ap',19,15,'E da sua boca saía uma aguda espada, para ferir com ela as nações; e ele as regerá com vara de ferro; e ele mesmo é o que pisa o lagar do vinho do furor e da ira do Deus Todo-Poderoso.'),
('acf','ap',19,16,'E no manto e na sua coxa tem escrito este nome: Rei dos reis, e Senhor dos senhores.'),
('acf','ap',19,17,'E vi um anjo que estava no sol, e clamou com grande voz, dizendo a todas as aves que voavam pelo meio do céu: Vinde, e ajuntai-vos à ceia do grande Deus;'),
('acf','ap',19,18,'Para que comais a carne dos reis, e a carne dos tribunos, e a carne dos fortes, e a carne dos cavalos e dos que sobre eles se assentam; e a carne de todos os homens, livres e servos, pequenos e grandes.'),
('acf','ap',19,19,'E vi a besta, e os reis da terra, e os seus exércitos reunidos, para fazerem guerra àquele que estava assentado sobre o cavalo, e ao seu exército.'),
('acf','ap',19,20,'E a besta foi presa, e com ela o falso profeta, que diante dela fizera os sinais, com que enganou os que receberam o sinal da besta, e adoraram a sua imagem. Estes dois foram lançados vivos no lago de fogo que arde com enxofre.'),
('acf','ap',19,21,'E os demais foram mortos com a espada que saía da boca do que estava assentado sobre o cavalo, e todas as aves se fartaram das suas carnes.'),
('acf','ap',20,1,'E vi descer do céu um anjo, que tinha a chave do abismo, e uma grande cadeia na sua mão.'),
('acf','ap',20,2,'Ele prendeu o dragão, a antiga serpente, que é o Diabo e Satanás, e amarrou-o por mil anos.'),
('acf','ap',20,3,'E lançou-o no abismo, e ali o encerrou, e pôs selo sobre ele, para que não mais engane as nações, até que os mil anos se acabem. E depois importa que seja solto por um pouco de tempo.'),
('acf','ap',20,4,'E vi tronos; e assentaram-se sobre eles, e foi-lhes dado o poder de julgar; e vi as almas daqueles que foram degolados pelo testemunho de Jesus, e pela palavra de Deus, e que não adoraram a besta, nem a sua imagem, e não receberam o sinal em suas testas nem em suas mãos; e viveram, e reinaram com Cristo durante mil anos.'),
('acf','ap',20,5,'Mas os outros mortos não reviveram, até que os mil anos se acabaram. Esta é a primeira ressurreição.'),
('acf','ap',20,6,'Bem-aventurado e santo aquele que tem parte na primeira ressurreição; sobre estes não tem poder a segunda morte; mas serão sacerdotes de Deus e de Cristo, e reinarão com ele mil anos.'),
('acf','ap',20,7,'E, acabando-se os mil anos, Satanás será solto da sua prisão,'),
('acf','ap',20,8,'E sairá a enganar as nações que estão sobre os quatro cantos da terra, Gogue e Magogue, cujo número é como a areia do mar, para as ajuntar em batalha.'),
('acf','ap',20,9,'E subiram sobre a largura da terra, e cercaram o arraial dos santos e a cidade amada; e de Deus desceu fogo, do céu, e os devorou.'),
('acf','ap',20,10,'E o diabo, que os enganava, foi lançado no lago de fogo e enxofre, onde estão a besta e o falso profeta; e de dia e de noite serão atormentados para todo o sempre.'),
('acf','ap',20,11,'E vi um grande trono branco, e o que estava assentado sobre ele, de cuja presença fugiu a terra e o céu; e não se achou lugar para eles.'),
('acf','ap',20,12,'E vi os mortos, grandes e pequenos, que estavam diante de Deus, e abriram-se os livros; e abriu-se outro livro, que é o da vida. E os mortos foram julgados pelas coisas que estavam escritas nos livros, segundo as suas obras.'),
('acf','ap',20,13,'E deu o mar os mortos que nele havia; e a morte e o inferno deram os mortos que neles havia; e foram julgados cada um segundo as suas obras.'),
('acf','ap',20,14,'E a morte e o inferno foram lançados no lago de fogo. Esta é a segunda morte.'),
('acf','ap',20,15,'E aquele que não foi achado escrito no livro da vida foi lançado no lago de fogo.'),
('acf','ap',21,1,'E vi um novo céu, e uma nova terra. Porque já o primeiro céu e a primeira terra passaram, e o mar já não existe.'),
('acf','ap',21,2,'E eu, João, vi a santa cidade, a nova Jerusalém, que de Deus descia do céu, adereçada como uma esposa ataviada para o seu marido.'),
('acf','ap',21,3,'E ouvi uma grande voz do céu, que dizia: Eis aqui o tabernáculo de Deus com os homens, pois com eles habitará, e eles serão o seu povo, e o mesmo Deus estará com eles, e será o seu Deus.'),
('acf','ap',21,4,'E Deus limpará de seus olhos toda a lágrima; e não haverá mais morte, nem pranto, nem clamor, nem dor; porque já as primeiras coisas são passadas.'),
('acf','ap',21,5,'E o que estava assentado sobre o trono disse: Eis que faço novas todas as coisas. E disse-me: Escreve; porque estas palavras são verdadeiras e fiéis.'),
('acf','ap',21,6,'E disse-me mais: Está cumprido. Eu sou o Alfa e o Ômega, o princípio e o fim. A quem quer que tiver sede, de graça lhe darei da fonte da água da vida.'),
('acf','ap',21,7,'Quem vencer, herdará todas as coisas; e eu serei seu Deus, e ele será meu filho.'),
('acf','ap',21,8,'Mas, quanto aos tímidos, e aos incrédulos, e aos abomináveis, e aos homicidas, e aos que se prostituem, e aos feiticeiros, e aos idólatras e a todos os mentirosos, a sua parte será no lago que arde com fogo e enxofre; o que é a segunda morte.'),
('acf','ap',21,9,'E veio a mim um dos sete anjos que tinham as sete taças cheias das últimas sete pragas, e falou comigo, dizendo: Vem, mostrar-te-ei a esposa, a mulher do Cordeiro.'),
('acf','ap',21,10,'E levou-me em espírito a um grande e alto monte, e mostrou-me a grande cidade, a santa Jerusalém, que de Deus descia do céu.'),
('acf','ap',21,11,'E tinha a glória de Deus; e a sua luz era semelhante a uma pedra preciosíssima, como a pedra de jaspe, como o cristal resplandecente.'),
('acf','ap',21,12,'E tinha um grande e alto muro com doze portas, e nas portas doze anjos, e nomes escritos sobre elas, que são os nomes das doze tribos dos filhos de Israel.'),
('acf','ap',21,13,'Do lado do levante tinha três portas, do lado do norte, três portas, do lado do sul, três portas, do lado do poente, três portas.'),
('acf','ap',21,14,'E o muro da cidade tinha doze fundamentos, e neles os nomes dos doze apóstolos do Cordeiro.'),
('acf','ap',21,15,'E aquele que falava comigo tinha uma cana de ouro, para medir a cidade, e as suas portas, e o seu muro.'),
('acf','ap',21,16,'E a cidade estava situada em quadrado; e o seu comprimento era tanto como a sua largura. E mediu a cidade com a cana até doze mil estádios; e o seu comprimento, largura e altura eram iguais.'),
('acf','ap',21,17,'E mediu o seu muro, de cento e quarenta e quatro côvados, conforme à medida de homem, que é a de um anjo.'),
('acf','ap',21,18,'E a construção do seu muro era de jaspe, e a cidade de ouro puro, semelhante a vidro puro.'),
('acf','ap',21,19,'E os fundamentos do muro da cidade estavam adornados de toda a pedra preciosa. O primeiro fundamento era jaspe; o segundo, safira; o terceiro, calcedônia; o quarto, esmeralda;'),
('acf','ap',21,20,'O quinto, sardônica; o sexto, sárdio; o sétimo, crisólito; o oitavo, berilo; o nono, topázio; o décimo, crisópraso; o undécimo, jacinto; o duodécimo, ametista.'),
('acf','ap',21,21,'E as doze portas eram doze pérolas; cada uma das portas era uma pérola; e a praça da cidade de ouro puro, como vidro transparente.'),
('acf','ap',21,22,'E nela não vi templo, porque o seu templo é o Senhor Deus Todo-Poderoso, e o Cordeiro.'),
('acf','ap',21,23,'E a cidade não necessita de sol nem de lua, para que nela resplandeçam, porque a glória de Deus a tem iluminado, e o Cordeiro é a sua lâmpada.'),
('acf','ap',21,24,'E as nações dos salvos andarão à sua luz; e os reis da terra trarão para ela a sua glória e honra.'),
('acf','ap',21,25,'E as suas portas não se fecharão de dia, porque ali não haverá noite.'),
('acf','ap',21,26,'E a ela trarão a glória e honra das nações.'),
('acf','ap',21,27,'E não entrará nela coisa alguma que contamine, e cometa abominação e mentira; mas só os que estão inscritos no livro da vida do Cordeiro.'),
('acf','ap',22,1,'E mostrou-me o rio puro da água da vida, claro como cristal, que procedia do trono de Deus e do Cordeiro.'),
('acf','ap',22,2,'No meio da sua praça, e de um e de outro lado do rio, estava a árvore da vida, que produz doze frutos, dando seu fruto de mês em mês; e as folhas da árvore são para a saúde das nações.'),
('acf','ap',22,3,'E ali nunca mais haverá maldição contra alguém; e nela estará o trono de Deus e do Cordeiro, e os seus servos o servirão.'),
('acf','ap',22,4,'E verão o seu rosto, e nas suas testas estará o seu nome.'),
('acf','ap',22,5,'E ali não haverá mais noite, e não necessitarão de lâmpada nem de luz do sol, porque o Senhor Deus os ilumina; e reinarão para todo o sempre.'),
('acf','ap',22,6,'E disse-me: Estas palavras são fiéis e verdadeiras; e o Senhor, o Deus dos santos profetas, enviou o seu anjo, para mostrar aos seus servos as coisas que em breve hão de acontecer.'),
('acf','ap',22,7,'Eis que presto venho: Bem-aventurado aquele que guarda as palavras da profecia deste livro.'),
('acf','ap',22,8,'E eu, João, sou aquele que vi e ouvi estas coisas. E, havendo-as ouvido e visto, prostrei-me aos pés do anjo que mas mostrava para o adorar.'),
('acf','ap',22,9,'E disse-me: Olha, não faças tal; porque eu sou conservo teu e de teus irmãos, os profetas, e dos que guardam as palavras deste livro. Adora a Deus.'),
('acf','ap',22,10,'E disse-me: Não seles as palavras da profecia deste livro; porque próximo está o tempo.'),
('acf','ap',22,11,'Quem é injusto, seja injusto ainda; e quem é sujo, seja sujo ainda; e quem é justo, seja justificado ainda; e quem é santo, seja santificado ainda.'),
('acf','ap',22,12,'E, eis que cedo venho, e o meu galardão está comigo, para dar a cada um segundo a sua obra.'),
('acf','ap',22,13,'Eu sou o Alfa e o Ômega, o princípio e o fim, o primeiro e o derradeiro.'),
('acf','ap',22,14,'Bem-aventurados aqueles que guardam os seus mandamentos, para que tenham direito à árvore da vida, e possam entrar na cidade pelas portas.'),
('acf','ap',22,15,'Mas, ficarão de fora os cães e os feiticeiros, e os que se prostituem, e os homicidas, e os idólatras, e qualquer que ama e comete a mentira.'),
('acf','ap',22,16,'Eu, Jesus, enviei o meu anjo, para vos testificar estas coisas nas igrejas. Eu sou a raiz e a geração de Davi, a resplandecente estrela da manhã.'),
('acf','ap',22,17,'E o Espírito e a esposa dizem: Vem. E quem ouve, diga: Vem. E quem tem sede, venha; e quem quiser, tome de graça da água da vida.'),
('acf','ap',22,18,'Porque eu testifico a todo aquele que ouvir as palavras da profecia deste livro que, se alguém lhes acrescentar alguma coisa, Deus fará vir sobre ele as pragas que estão escritas neste livro;'),
('acf','ap',22,19,'E, se alguém tirar quaisquer palavras do livro desta profecia, Deus tirará a sua parte do livro da vida, e da cidade santa, e das coisas que estão escritas neste livro.'),
('acf','ap',22,20,'Aquele que testifica estas coisas diz: Certamente cedo venho. Amém. Ora vem, Senhor Jesus.'),
('acf','ap',22,21,'A graça de nosso Senhor Jesus Cristo seja com todos vós. Amém.')
